  });

  const { mutate: updatePatient, isPending: isUpdatingPatient } = useMutation({
    mutationKey: ["update_patient"],
    mutationFn: mutate(patientApi.update, {
      pathParams: { id: patientId || "" },
    }),
    onSuccess: () => {
      toast.success(t("patient_update_success"));
      form.reset(form.getValues());
      goBack();
    },
  });

  const isPending = isCreatingPatient || isUpdatingPatient;

  const showDuplicate =
    !patientPhoneSearch.isLoading &&
    !!duplicatePatients?.length &&
    !!isValidPhoneNumber(phoneNumber) &&
    !suppressDuplicateWarning;

  useNavigationPrompt(
    form.formState.isDirty && !isPending && !showDuplicate,
    t("unsaved_changes"),
  );

  if (patientId && patientQuery.isLoading) {
    return <Loading />;
  }

  function onSubmit(values: z.infer<typeof formSchema>) {
    if (!facility) {
      return;
    }

    const { extensions: formExtensions, ...restValues } = values;
    const cleanedExtensions = extensions.prepareForSubmit(
      formExtensions as NamespacedExtensionData,
    );

    const basePayload = {
      ...restValues,

      age:
        restValues.age_or_dob === "dob"
          ? undefined
          : restValues.age || undefined,
      date_of_birth:
        restValues.age_or_dob === "dob"
          ? restValues.date_of_birth || undefined
          : undefined,

      emergency_phone_number:
        restValues.emergency_phone_number_same_as_phone_number
