type PatientSearchMode =
  typeof SEARCH_MODE_IDENTIFIER | typeof SEARCH_MODE_ENCOUNTER;
type EncounterSearchKey =
  | typeof ENCOUNTER_SEARCH_PATIENT_NAME
  | typeof ENCOUNTER_SEARCH_EXTERNAL_IDENTIFIER;

