import mutate from "@/Utils/request/mutate";
import {
  AbhaCreateAddressRequest,
  AbhaCreateSendOtpRequest,
  AbhaJourney,
  AbhaSearchRequest,
  AbhaSelectAccountRequest,
  AbhaSendOtpRequest,
  AbhaTransactionRequest,
  AbhaVerifyOtpRequest,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";

import { abhaSilent } from "./utils";

/** Every journey step call; each one answers with the updated journey */
export type AbhaJourneyAction =
  | { type: "search"; body: AbhaSearchRequest }
  | { type: "send_otp"; body: AbhaSendOtpRequest }
  | { type: "create_send_otp"; body: AbhaCreateSendOtpRequest }
  | { type: "verify_otp"; body: AbhaVerifyOtpRequest }
  | { type: "resend_otp"; body: AbhaTransactionRequest }
  | { type: "select_account"; body: AbhaSelectAccountRequest }
  | { type: "skip_mobile_otp"; body: AbhaTransactionRequest }
  | { type: "create_address"; body: AbhaCreateAddressRequest };

export type AbhaJourneyActionType = AbhaJourneyAction["type"];

export function runAbhaJourneyAction(
  action: AbhaJourneyAction,
): Promise<AbhaJourney> {
  const options = { silent: abhaSilent };

  switch (action.type) {
    case "search":
      return mutate(abhaApi.search, options)(action.body);
    case "send_otp":
      return mutate(abhaApi.sendOtp, options)(action.body);
    case "create_send_otp":
      return mutate(abhaApi.createSendOtp, options)(action.body);
    case "verify_otp":
      return mutate(abhaApi.verifyOtp, options)(action.body);
    case "resend_otp":
      return mutate(abhaApi.resendOtp, options)(action.body);
    case "select_account":
      return mutate(abhaApi.selectAccount, options)(action.body);
    case "skip_mobile_otp":
      return mutate(abhaApi.skipMobileOtp, options)(action.body);
    case "create_address":
      return mutate(abhaApi.createAddress, options)(action.body);
  }
}

