import { AbhaJourney, PatientAbha } from "@/types/abdm/abha";
import { PatientRead } from "@/types/emr/patient/patient";

import { AbhaFacts } from "./useAbhaFacts";

/**
 * - `register`: before the registration form; the result fills the form
 * - `link`: link an ABHA to an existing patient
 * - `reverify`: OTP for the ABHA already linked to a patient, to see the card
 */
export type AbhaJourneyMode = "register" | "link" | "reverify";

export interface AbhaJourneyResult {
  /** A `verified` journey */
  journey: AbhaJourney;
  facts: AbhaFacts;
  /** Set in `link` mode */
  patientAbha?: PatientAbha;
}

/** The existing patient, shown beside the ABHA profile before linking */
export type AbhaLinkTarget = Pick<
  PatientRead,
  "name" | "gender" | "date_of_birth" | "year_of_birth"
>;

import { ReactNode } from "react";

/**
 * Every journey step starts with this heading. The journey moves focus to it
 * when the step changes.
 */
export function AbhaStepHeading({
  title,
  description,
}: {
  title: string;
  description?: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-1">
      <h3
        tabIndex={-1}
        data-abha-step-heading
        data-testid="abha-step-heading"
        className="text-lg font-semibold text-gray-900 outline-none"
      >
        {title}
      </h3>
      {description && <p className="text-sm text-gray-600">{description}</p>}
    </div>
  );
}

export function AbhaFieldError({
  id,
  message,
}: {
  id?: string;
  message?: string | null;
}) {
  if (!message) {
    return null;
  }

  return (
    <p
      id={id}
      role="alert"
      className="text-sm text-red-500"
      data-testid="abha-field-error"
    >
      {message}
    </p>
  );
}

