import { Loader2Icon } from "lucide-react";
import { FormEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import RadioInput from "@/components/ui/RadioInput";

import { AbhaAuthMethod, AbhaIdentifierType } from "@/types/abdm/abha";

import { AbhaConsentPanel } from "./AbhaConsentPanel";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFact, AbhaFacts, AbhaTriedRoute } from "./useAbhaFacts";
import {
  ABHA_AUTH_METHOD_LABELS,
  ABHA_IDENTIFIER_LABELS,
  isValidAadhaar,
  isValidAbhaAddressForLogin,
  isValidMobile,
  normalizeAadhaar,
  normalizeAbhaNumber,
  normalizeMobile,
} from "./utils";

export interface AbhaIdentifyInput {
  type: AbhaIdentifierType;
  /** Normalised value, as sent to CARE */
  value: string;
  authMethod?: AbhaAuthMethod;
}

const IDENTIFIER_TYPES: AbhaIdentifierType[] = [
  "mobile",
  "aadhaar",
  "abha_number",
  "abha_address",
];

const AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

const PLACEHOLDERS: Record<AbhaIdentifierType, string> = {
  mobile: "abha_identifier_placeholder__mobile",
  aadhaar: "abha_identifier_placeholder__aadhaar",
  abha_number: "abha_identifier_placeholder__abha_number",
  abha_address: "abha_identifier_placeholder__abha_address",
};

/** Local validation (contract §5.1); nothing is sent when it fails */
const validate = (
  type: AbhaIdentifierType,
  value: string,
): { value: string } | { error: string } => {
  switch (type) {
    case "mobile":
      return isValidMobile(value)
        ? { value: normalizeMobile(value) }
        : { error: "abha_error_invalid_mobile" };
    case "aadhaar":
      return isValidAadhaar(value)
        ? { value: normalizeAadhaar(value) }
        : { error: "abha_error_invalid_aadhaar" };
    case "abha_number": {
      const abhaNumber = normalizeAbhaNumber(value);
      return abhaNumber
        ? { value: abhaNumber }
        : { error: "abha_error_invalid_abha_number" };
    }
    case "abha_address":
      return isValidAbhaAddressForLogin(value)
        ? { value: value.trim() }
        : { error: "abha_error_invalid_abha_address" };
  }
};

/**
 * Identify (screen 1): one screen for finding or creating an ABHA. It never
 * asks "login or create?"; creation is offered when no ABHA is found.
 */
export function AbhaIdentifyStep({
  facts,
  tried,
  initialType,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  facts: AbhaFacts;
  tried: AbhaTriedRoute[];
  initialType: AbhaIdentifierType;
  /** Server error for the identifier, shown under the input */
  error?: string;
  isPending: boolean;
  onSubmit: (input: AbhaIdentifyInput) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const inputId = `${id}-identifier`;
  const errorId = `${id}-error`;

  const [type, setType] = useState(initialType);
  const [values, setValues] = useState<Record<AbhaIdentifierType, string>>(
    () => ({
      mobile: facts.mobile?.value ?? "",
      aadhaar: "",
      abha_number: facts.abhaNumber?.value ?? "",
      abha_address: facts.abhaAddress?.value ?? "",
    }),
  );
  const [consented, setConsented] = useState(!!facts.consent);
  const [authMethod, setAuthMethod] = useState<AbhaAuthMethod>("aadhaar_otp");
  const [localError, setLocalError] = useState<string>();

  const value = values[type];
  const heldFacts: Record<AbhaIdentifierType, AbhaFact<string> | undefined> = {
    mobile: facts.mobile,
    aadhaar: undefined,
    abha_number: facts.abhaNumber,
    abha_address: facts.abhaAddress,
  };
  const heldFact = heldFacts[type];
  const needsConsent = type === "aadhaar" && !consented;
  const errorMessage = localError ?? error;

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    if (needsConsent || isPending) {
      return;
    }
    const result = validate(type, value);
    if ("error" in result) {
      setLocalError(t(result.error));
      return;
    }
    onSubmit({
      type,
      value: result.value,
      authMethod: type === "abha_number" ? authMethod : undefined,
    });
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-identify-step"
    >
      <AbhaStepHeading
        title={t("abha_identify_title")}
        description={t("abha_identify_description")}
      />

      <div className="flex flex-col gap-2">
        <Label>{t("abha_identify_with")}</Label>
        <RadioInput
          required
          value={type}
          disabled={isPending}
          onValueChange={(next) => {
            setType(next as AbhaIdentifierType);
            clearErrors();
          }}
          options={IDENTIFIER_TYPES.map((option) => ({
            value: option,
            label: t(ABHA_IDENTIFIER_LABELS[option]),
          }))}
        />
      </div>

      {type === "aadhaar" && (
        <AbhaConsentPanel checked={consented} onCheckedChange={setConsented} />
      )}

      <div className="flex flex-col gap-2">
        <Label htmlFor={inputId}>{t(ABHA_IDENTIFIER_LABELS[type])}</Label>
        <div className="flex items-center gap-2">
          {type === "mobile" && (
            <span className="rounded-md border border-gray-200 bg-gray-50 px-3 py-1.5 text-sm text-gray-700">
              {t("abha_country_code")}
            </span>
          )}
          <Input
            key={type}
            id={inputId}
            value={value}
            disabled={isPending || needsConsent}
            placeholder={t(PLACEHOLDERS[type])}
            autoComplete="off"
            inputMode={
              type === "abha_address" || type === "abha_number"
                ? "text"
                : "numeric"
            }
            aria-invalid={!!errorMessage}
            aria-describedby={errorMessage ? errorId : undefined}
            data-testid="abha-identifier-input"
            onChange={(event) => {
              setValues((current) => ({
                ...current,
                [type]: event.target.value,
              }));
              clearErrors();
            }}
          />
        </div>
        {heldFact && heldFact.value === value && (
          <AbhaProvenanceBadge source={heldFact.source} />
        )}
        <AbhaFieldError id={errorId} message={errorMessage} />
      </div>

      {type === "abha_number" && (
        <div className="flex flex-col gap-2">
          <Label>{t("abha_auth_method")}</Label>
          <RadioInput
            required
            value={authMethod}
            disabled={isPending}
            onValueChange={(next) => setAuthMethod(next as AbhaAuthMethod)}
            options={AUTH_METHODS.map((method) => ({
              value: method,
              label: t(ABHA_AUTH_METHOD_LABELS[method]),
            }))}
          />
        </div>
      )}

      {tried.length > 0 && (
        <div
          className="rounded-md bg-gray-50 p-3 text-sm text-gray-700"
          data-testid="abha-tried-routes"
        >
          <p className="font-medium">{t("abha_already_tried")}</p>
          <ul className="list-inside list-disc">
            {tried.map((route) => (
              <li key={`${route.route}-${route.reason}`}>
                {t(`abha_tried__${route.reason}`, {
                  identifier: t(ABHA_IDENTIFIER_LABELS[route.route]),
                })}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="flex justify-end">
        <Button
          type="submit"
          variant="primary"
          disabled={isPending || needsConsent}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {type === "abha_address" ? t("search") : t("send_otp")}
        </Button>
      </div>
    </form>
  );
}

