import { Loader2Icon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { AbhaSearchResult } from "@/types/abdm/abha";

import { AbhaDetail } from "./AbhaProfileSummary";
import { AbhaStepHeading } from "./AbhaStepHeading";

/** Confirm it is them (screen 2), after the free ABHA address lookup */
export function AbhaConfirmIdentityStep({
  searchResult,
  isPending,
  onConfirm,
  onReject,
}: {
  searchResult: AbhaSearchResult | null;
  isPending: boolean;
  onConfirm: () => void;
  onReject: () => void;
}) {
  const { t } = useTranslation();

  return (
    <div
      className="flex flex-col gap-5"
      data-testid="abha-confirm-identity-step"
    >
      <AbhaStepHeading
        title={t("abha_confirm_identity_title")}
        description={t("abha_confirm_identity_description")}
      />

      <dl className="grid grid-cols-1 gap-3 rounded-md border border-gray-200 p-4 sm:grid-cols-3">
        <AbhaDetail
          label={t("name")}
          value={searchResult?.full_name}
          testId="abha-search-name"
        />
        <AbhaDetail
          label={t("abha_address")}
          value={searchResult?.abha_address}
        />
        <AbhaDetail
          label={t("mobile_number")}
          value={searchResult?.masked_mobile}
          testId="abha-search-mobile"
        />
      </dl>

      <div className="flex flex-wrap justify-end gap-2">
        <Button variant="outline" disabled={isPending} onClick={onReject}>
          {t("abha_confirm_identity_no")}
        </Button>
        <Button variant="primary" disabled={isPending} onClick={onConfirm}>
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("abha_confirm_identity_yes")}
        </Button>
      </div>
    </div>
  );
}

import { Loader2Icon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import RadioInput from "@/components/ui/RadioInput";

import { AbhaAuthMethod } from "@/types/abdm/abha";

import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFact } from "./useAbhaFacts";
import { ABHA_AUTH_METHOD_LABELS } from "./utils";

/**
 * Method chooser, used after an ABHA address lookup with more than one
 * method, and to re-verify the ABHA number already linked to a patient.
 */
export function AbhaMethodStep({
  methods,
  identifierLabel,
  identifier,
  isPending,
  onSubmit,
}: {
  methods: AbhaAuthMethod[];
  identifierLabel: string;
  identifier?: AbhaFact<string> | string;
  isPending: boolean;
  onSubmit: (method: AbhaAuthMethod) => void;
}) {
  const { t } = useTranslation();
  const [method, setMethod] = useState<AbhaAuthMethod>(methods[0]);
  const fact = typeof identifier === "string" ? undefined : identifier;
  const identifierValue = typeof identifier === "string" ? identifier : fact?.value;

  return (
    <div className="flex flex-col gap-5" data-testid="abha-method-step">
      <AbhaStepHeading
        title={t("abha_method_title")}
        description={t("abha_method_description")}
      />

      {identifierValue && (
        <div className="flex flex-col gap-1">
          <span className="text-xs text-gray-500">{identifierLabel}</span>
          <div className="flex flex-wrap items-center gap-2">
            <span
              className="text-sm font-semibold text-gray-900"
              data-testid="abha-method-identifier"
            >
              {identifierValue}
            </span>
            {fact && <AbhaProvenanceBadge source={fact.source} />}
          </div>
        </div>
      )}

      <div className="flex flex-col gap-2">
        <Label>{t("abha_auth_method")}</Label>
        <RadioInput
          required
          value={method}
          disabled={isPending}
          onValueChange={(next) => setMethod(next as AbhaAuthMethod)}
          options={methods.map((option) => ({
            value: option,
            label: t(ABHA_AUTH_METHOD_LABELS[option]),
          }))}
        />
      </div>

      <div className="flex justify-end">
        <Button
          variant="primary"
          disabled={isPending}
          onClick={() => onSubmit(method)}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("send_otp")}
        </Button>
      </div>
    </div>
  );
}

import { REGEXP_ONLY_DIGITS } from "input-otp";
import { Loader2Icon } from "lucide-react";
import { FormEvent, useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";

import { AbhaOtp } from "@/types/abdm/abha";

import { AbhaJourneyActionType } from "./abhaJourneyActions";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFacts } from "./useAbhaFacts";
import {
  ABHA_COUNTRY_CODE,
  ABHA_OTP_LENGTH,
  AbhaUiError,
  AbhaUiErrorCode,
  isValidMobile,
  normalizeMobile,
} from "./utils";

export interface AbhaOtpMobile {
  /** 10 digits, without +91 */
  value: string;
  /** The desk changed a mobile the journey already held */
  edited: boolean;
}

const RESEND_ERROR_CODES: AbhaUiErrorCode[] = [
  "resend_cooldown",
  "resend_limit_reached",
  "rate_limited",
];

/**
 * OTP (screen 3), for every purpose. The identifier is never asked again
 * here; for the Aadhaar OTP during creation, the communication mobile is
 * asked once if the journey holds none.
 */
export function AbhaOtpStep({
  otp,
  facts,
  error,
  pendingAction,
  onVerify,
  onResend,
  onSkip,
  onClearError,
}: {
  otp: AbhaOtp;
  facts: AbhaFacts;
  /** Inline error for this step (OTP, mobile or resend) */
  error: AbhaUiError | null;
  pendingAction?: AbhaJourneyActionType;
  onVerify: (
    code: string,
    mobile: AbhaOtpMobile | undefined,
    onError: () => void,
  ) => void;
  onResend: () => void;
  onSkip: () => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const heldMobile = facts.mobile;

  const [code, setCode] = useState("");
  const [editingMobile, setEditingMobile] = useState(false);
  const [mobile, setMobile] = useState(heldMobile?.value ?? "");
  const [localError, setLocalError] = useState<{
    field: "otp" | "mobile";
    message: string;
  }>();
  const [now, setNow] = useState(() => Date.now());

  const isPending = !!pendingAction;
  const asksMobile = otp.purpose === "aadhaar";
  const showMobileInput = asksMobile && (!heldMobile || editingMobile);

  const fieldError = (field: "otp" | "mobile") =>
    localError?.field === field
      ? localError.message
      : error?.field === field
        ? error.message
        : undefined;
  const otpError = fieldError("otp");
  const mobileError = fieldError("mobile");
  const resendError =
    error && RESEND_ERROR_CODES.includes(error.code)
      ? error.message
      : undefined;

  // The countdown follows `resend_available_at`, or `retry_after` from a 429
  const cooldownUntil = Math.max(
    Date.parse(otp.resend_available_at) || 0,
    error?.code === "resend_cooldown" && error.retryAfter
      ? error.receivedAt + error.retryAfter * 1000
      : 0,
  );
  const secondsLeft = Math.max(0, Math.ceil((cooldownUntil - now) / 1000));
  const isCountingDown = secondsLeft > 0;
  const resendsExhausted =
    otp.resends_remaining <= 0 || error?.code === "resend_limit_reached";

  useEffect(() => {
    if (!isCountingDown) {
      return;
    }
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [isCountingDown]);

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleVerify = (event: FormEvent) => {
    event.preventDefault();
    if (isPending) {
      return;
    }
    if (code.length !== ABHA_OTP_LENGTH) {
      setLocalError({ field: "otp", message: t("abha_error_otp_length") });
      return;
    }

    let otpMobile: AbhaOtpMobile | undefined;
    if (showMobileInput) {
      if (!isValidMobile(mobile)) {
        setLocalError({
          field: "mobile",
          message: t("abha_error_invalid_mobile"),
        });
        return;
      }
      otpMobile = { value: normalizeMobile(mobile), edited: !!heldMobile };
      setEditingMobile(false);
    } else if (asksMobile && heldMobile) {
      otpMobile = { value: heldMobile.value, edited: false };
    }

    onVerify(code, otpMobile, () => setCode(""));
  };

  const description =
    otp.message ??
    (otp.sent_to
      ? t("abha_otp_sent_to", { destination: otp.sent_to })
      : t("abha_otp_sent"));

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleVerify}
      noValidate
      data-testid="abha-otp-step"
      data-purpose={otp.purpose}
    >
      <AbhaStepHeading
        title={t(`abha_otp_title__${otp.purpose}`)}
        description={description}
      />

      <div className="flex flex-col gap-2">
        <Label htmlFor={`${id}-otp`}>{t("abha_otp_label")}</Label>
        <InputOTP
          id={`${id}-otp`}
          maxLength={ABHA_OTP_LENGTH}
          pattern={REGEXP_ONLY_DIGITS}
          value={code}
          disabled={isPending}
          autoComplete="one-time-code"
          aria-invalid={!!otpError}
          aria-describedby={otpError ? `${id}-otp-error` : undefined}
          data-testid="abha-otp-input"
          onChange={(value) => {
            setCode(value);
            clearErrors();
          }}
        >
          <InputOTPGroup>
            {Array.from({ length: ABHA_OTP_LENGTH }, (_, index) => (
              <InputOTPSlot
                key={index}
                index={index}
                aria-invalid={!!otpError}
                className="size-10"
              />
            ))}
          </InputOTPGroup>
        </InputOTP>
        <AbhaFieldError id={`${id}-otp-error`} message={otpError} />
      </div>

      {asksMobile && (
        <div
          className="flex flex-col gap-2"
          data-testid="abha-communication-mobile"
        >
          {showMobileInput ? (
            <>
              <Label htmlFor={`${id}-mobile`}>
                {t("abha_communication_mobile")}
              </Label>
              <div className="flex items-center gap-2">
                <span className="rounded-md border border-gray-200 bg-gray-50 px-3 py-1.5 text-sm text-gray-700">
                  {ABHA_COUNTRY_CODE}
                </span>
                <Input
                  id={`${id}-mobile`}
                  value={mobile}
                  inputMode="numeric"
                  autoComplete="off"
                  disabled={isPending}
                  placeholder={t("abha_identifier_placeholder__mobile")}
                  aria-invalid={!!mobileError}
                  aria-describedby={`${id}-mobile-help`}
                  data-testid="abha-communication-mobile-input"
                  onChange={(event) => {
                    setMobile(event.target.value);
                    clearErrors();
                  }}
                />
              </div>
              <p id={`${id}-mobile-help`} className="text-xs text-gray-500">
                {t("abha_communication_mobile_help")}
              </p>
              <AbhaFieldError message={mobileError} />
            </>
          ) : (
            heldMobile && (
              <>
                <span className="text-sm font-medium text-gray-900">
                  {t("abha_communication_mobile")}
                </span>
                <div className="flex flex-wrap items-center gap-2">
                  <span
                    className="text-sm font-semibold text-gray-900"
                    data-testid="abha-held-mobile"
                  >
                    {`${ABHA_COUNTRY_CODE} ${heldMobile.value}`}
                  </span>
                  <AbhaProvenanceBadge source={heldMobile.source} />
                  <Button
                    type="button"
                    variant="link"
                    className="h-auto p-0 text-primary-700"
                    disabled={isPending}
                    onClick={() => {
                      setMobile(heldMobile.value);
                      setEditingMobile(true);
                    }}
                  >
                    {t("change")}
                  </Button>
                </div>
              </>
            )
          )}
        </div>
      )}

      <div className="flex flex-col items-start gap-1" data-testid="abha-resend">
        {resendsExhausted ? (
          <p className="text-sm text-gray-600">
            {t("abha_otp_no_resends_left")}
          </p>
        ) : (
          <div className="flex flex-wrap items-center gap-3">
            <Button
              type="button"
              variant="link"
              className="h-auto p-0 text-primary-700"
              disabled={isPending || isCountingDown}
              data-testid="abha-resend-otp"
              onClick={() => {
                setNow(Date.now());
                setCode("");
                clearErrors();
                onResend();
              }}
            >
              {pendingAction === "resend_otp" && (
                <Loader2Icon className="animate-spin" />
              )}
              {isCountingDown
                ? t("resend_otp_timer", { time: secondsLeft })
                : t("resend_otp")}
            </Button>
            <span className="text-xs text-gray-500">
              {t("abha_otp_resends_remaining", {
                count: otp.resends_remaining,
              })}
            </span>
          </div>
        )}
        <AbhaFieldError message={resendError} />
      </div>

      <div className="flex flex-wrap justify-end gap-2">
        {otp.skippable && (
          <Button
            type="button"
            variant="outline"
            disabled={isPending}
            onClick={onSkip}
          >
            {pendingAction === "skip_mobile_otp" && (
              <Loader2Icon className="animate-spin" />
            )}
            {t("abha_skip_mobile_verification")}
          </Button>
        )}
        <Button type="submit" variant="primary" disabled={isPending}>
          {pendingAction === "verify_otp" && (
            <Loader2Icon className="animate-spin" />
          )}
          {t("verify_otp")}
        </Button>
      </div>
    </form>
  );
}

import { Loader2Icon } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import { Avatar } from "@/components/Common/Avatar";

import { AbhaAccount } from "@/types/abdm/abha";

import { AbhaKycBadge } from "./AbhaProfileSummary";
import { AbhaStepHeading } from "./AbhaStepHeading";
import { getAbhaPhotoSrc } from "./utils";

/** Choose an account (screen 4); one mobile can hold up to 6 ABHAs */
export function AbhaAccountStep({
  accounts,
  isPending,
  onSelect,
}: {
  accounts: AbhaAccount[];
  isPending: boolean;
  onSelect: (abhaNumber: string) => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const [selected, setSelected] = useState(accounts[0]?.abha_number ?? "");

  return (
    <div className="flex flex-col gap-5" data-testid="abha-account-step">
      <AbhaStepHeading
        title={t("abha_account_title")}
        description={t("abha_account_description", { count: accounts.length })}
      />

      <RadioGroup
        value={selected}
        onValueChange={setSelected}
        disabled={isPending}
        aria-label={t("abha_account_title")}
        className="gap-2"
      >
        {accounts.map((account) => {
          const itemId = `${id}-${account.abha_number}`;
          const linkedPatient = account.linked_patient;
          return (
            <label
              key={account.abha_number}
              htmlFor={itemId}
              className={cn(
                "flex cursor-pointer items-start gap-3 rounded-md border p-3",
                selected === account.abha_number
                  ? "border-primary-500 bg-primary-50"
                  : "border-gray-200 bg-white hover:border-primary-300",
              )}
              data-testid="abha-account-option"
            >
              <RadioGroupItem
                id={itemId}
                value={account.abha_number}
                className="mt-1"
              />
              <Avatar
                name={account.name}
                imageUrl={getAbhaPhotoSrc(account.photo)}
                className="size-12 shrink-0"
              />
              <div className="flex min-w-0 flex-1 flex-col gap-1 text-sm">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-semibold text-gray-900">
                    {account.name}
                  </span>
                  <AbhaKycBadge verified={account.kyc_verified} />
                </div>
                <span className="text-gray-900">{account.abha_number}</span>
                <span className="break-all text-gray-700">
                  {account.preferred_abha_address}
                </span>
                <span className="text-gray-600">
                  {[
                    account.gender && t(`GENDER__${account.gender}`),
                    account.year_of_birth &&
                      t("abha_year_of_birth_value", {
                        year: account.year_of_birth,
                      }),
                  ]
                    .filter(Boolean)
                    .join(" · ")}
                </span>
                {linkedPatient && (
                  <Badge
                    variant={
                      linkedPatient.is_current_patient ? "green" : "yellow"
                    }
                    size="xs"
                    className="w-fit"
                    data-testid="abha-account-linked"
                  >
                    {linkedPatient.is_current_patient
                      ? t("abha_linked_to_this_patient")
                      : t("abha_already_linked_to", {
                          name: linkedPatient.name,
                          partial_id: linkedPatient.partial_id,
                        })}
                  </Badge>
                )}
              </div>
            </label>
          );
        })}
      </RadioGroup>

      <div className="flex justify-end">
        <Button
          variant="primary"
          disabled={isPending || !selected}
          onClick={() => onSelect(selected)}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("continue")}
        </Button>
      </div>
    </div>
  );
}

result.output:
import { GenderChoices } from "@/types/emr/patient/patient";

/**
 * ABDM Milestone 1 (ABHA create and verify) types.
 *
 * These mirror the CARE backend HTTP contract under `/api/v1/abdm/abha/`.
 * The frontend never calls ABDM directly; every call goes through CARE, which
 * keeps the ABDM transaction state in a server-side "journey".
 */

export const ABHA_CONSENT_VERSION = "1.4";

export type AbhaFlow = "login" | "create";

export type AbhaJourneyStatus =
  | "confirm_identity"
  | "otp_sent"
  | "no_account"
  | "select_account"
  | "select_address"
  | "verified";

export type AbhaIdentifierType =
  | "mobile"
  | "aadhaar"
  | "abha_number"
  | "abha_address";

export type AbhaAuthMethod = "aadhaar_otp" | "mobile_otp";

export type AbhaOtpPurpose = "login" | "aadhaar" | "mobile";

export type AbdmGender = "M" | "F" | "O" | "T";

export interface AbhaConsent {
  accepted: true;
  version: typeof ABHA_CONSENT_VERSION;
}

/** Result of the free ABHA address lookup (`search/`). */
export interface AbhaSearchResult {
  abha_address: string;
  full_name: string;
  masked_mobile: string;
}

export interface AbhaOtp {
  purpose: AbhaOtpPurpose;
  /** Masked destination, if known */
  sent_to: string | null;
  message: string | null;
  resend_available_at: string;
  resends_remaining: number;
  /** True only for the mobile OTP during creation */
  skippable: boolean;
}

/**
 * A CARE patient that already holds an ABHA. Same exposure as CARE's
 * partial patient spec; never carries the real patient id.
 */
export interface LinkedPatient {
  partial_id: string;
  name: string;
  gender: GenderChoices;
  year_of_birth: number;
  phone_number: string;
  is_current_patient: boolean;
}

/** One entry of the account chooser (up to 6 per mobile). */
export interface AbhaAccount {
  abha_number: string;
  preferred_abha_address: string;
  name: string;
  gender: GenderChoices | null;
  date_of_birth: string | null;
  year_of_birth: number | null;
  /** Base64 encoded jpeg */
  photo: string | null;
  kyc_verified: boolean;
  status: string;
  linked_patient: LinkedPatient | null;
}

export interface AbhaProfile {
  abha_number: string;
  abha_address: string | null;
  abha_addresses: string[];
  name: string;
  first_name: string;
  middle_name: string;
  last_name: string;
  gender: GenderChoices | null;
  abdm_gender: AbdmGender | null;
  date_of_birth: string | null;
  year_of_birth: number | null;
  /** Null when ABDM only returns it masked */
  mobile: string | null;
  email: string | null;
  address: string | null;
  pincode: string | null;
  state_name: string | null;
  district_name: string | null;
  /** Base64 encoded jpeg */
  photo: string | null;
  kyc_verified: boolean;
  status: string;
  is_new: boolean;
  auth_method: AbhaAuthMethod | null;
}

/** Shared response of every journey step. */
export interface AbhaJourney {
  transaction_id: string;
  flow: AbhaFlow;
  status: AbhaJourneyStatus;
  identifier_type: AbhaIdentifierType;
  /** Display only; Aadhaar as "XXXX XXXX 1234" */
  masked_identifier: string;
  auth_methods: AbhaAuthMethod[];
  search_result: AbhaSearchResult | null;
  otp: AbhaOtp | null;
  accounts: AbhaAccount[] | null;
  profile: AbhaProfile | null;
  linked_patient: LinkedPatient | null;
  consent_recorded: boolean;
  message: string | null;
}

export interface AbhaAddressSuggestions {
  suggestions: string[];
  suffix: string;
}

export interface AbhaLinkedBy {
  id: string;
  username: string;
  first_name: string;
  last_name: string;
}

export interface PatientAbhaLinked {
  linked: true;
  abha_number: string;
  abha_address: string | null;
  kyc_verified: boolean | null;
  auth_method: AbhaAuthMethod | null;
  linked_on: string;
  linked_by: AbhaLinkedBy | null;
}

export interface PatientAbhaUnlinked {
  linked: false;
}

export type PatientAbha = PatientAbhaLinked | PatientAbhaUnlinked;

/** `facility` and `patient` are external ids. `patient` means link mode. */
interface AbhaJourneyContext {
  facility?: string;
  patient?: string;
}

export interface AbhaSearchRequest extends AbhaJourneyContext {
  abha_address: string;
}

export interface AbhaSendOtpRequest extends AbhaJourneyContext {
  identifier_type: AbhaIdentifierType;
  identifier?: string;
  auth_method?: AbhaAuthMethod;
  transaction_id?: string;
  consent?: AbhaConsent;
}

export interface AbhaCreateSendOtpRequest extends AbhaJourneyContext {
  transaction_id?: string;
  aadhaar?: string;
  consent?: AbhaConsent;
}

export interface AbhaTransactionRequest {
  transaction_id: string;
}

export interface AbhaVerifyOtpRequest extends AbhaTransactionRequest {
  otp: string;
  /** Communication mobile, only for the Aadhaar OTP during creation */
  mobile?: string;
}

export interface AbhaSelectAccountRequest extends AbhaTransactionRequest {
  abha_number: string;
}

export interface AbhaCreateAddressRequest extends AbhaTransactionRequest {
  /** Without the suffix */
  abha_address: string;
}

export interface AbhaLinkRequest extends AbhaTransactionRequest {
  patient: string;
}

export type AbhaErrorCode =
  | `ABDM-${string}`
  | "invalid_aadhaar"
  | "invalid_mobile"
  | "invalid_abha_number"
  | "invalid_abha_address"
  | "consent_required"
  | "transaction_expired"
  | "invalid_state"
  | "abha_already_linked"
  | "patient_already_has_abha"
  | "card_unavailable"
  | "resend_cooldown"
  | "resend_limit_reached"
  | "rate_limited"
  | "abdm_unavailable"
  | "abdm_auth_failed"
  | "abdm_timeout"
  | "abdm_disabled";

export type AbhaErrorField =
  | "otp"
  | "identifier"
  | "aadhaar"
  | "mobile"
  | "abha_address"
  | "abha_number";

export interface AbhaErrorItem {
  type: "abdm_error";
  code: AbhaErrorCode;
  msg: string;
  field?: AbhaErrorField;
  /** Seconds, with `resend_cooldown` */
  retry_after?: number;
  /** With `abha_already_linked` */
  linked_patient?: LinkedPatient;
}

export interface AbhaErrorResponse {
  errors: AbhaErrorItem[];
  /** Accepted here too, in case the backend puts the extra keys on the body */
  retry_after?: number;
  linked_patient?: LinkedPatient;
}

import { TFunction } from "i18next";

import { HTTPError } from "@/Utils/request/types";
import {
  ABHA_CONSENT_VERSION,
  AbhaConsent,
  AbhaErrorCode,
  AbhaErrorItem,
  AbhaErrorResponse,
  AbhaAuthMethod,
  AbhaIdentifierType,
  LinkedPatient,
} from "@/types/abdm/abha";

export const ABHA_CONSENT: AbhaConsent = {
  accepted: true,
  version: ABHA_CONSENT_VERSION,
};

export const ABHA_OTP_LENGTH = 6;

/**
 * Errors land on the active journey step instead of a global toast. 401s still
 * go to the global handler so an expired session redirects as usual.
 */
export const abhaSilent = (res: Response) => res.status !== 401;

export const ABHA_COUNTRY_CODE = "+91";

export const ABHA_IDENTIFIER_LABELS: Record<AbhaIdentifierType, string> = {
  mobile: "abha_identifier__mobile",
  aadhaar: "abha_identifier__aadhaar",
  abha_number: "abha_identifier__abha_number",
  abha_address: "abha_identifier__abha_address",
};

export const ABHA_AUTH_METHOD_LABELS: Record<AbhaAuthMethod, string> = {
  aadhaar_otp: "abha_auth_method__aadhaar_otp",
  mobile_otp: "abha_auth_method__mobile_otp",
};

// Local validation, shared with the backend (contract §5.1). Nothing is sent
// to CARE when these fail.

export const normalizeAadhaar = (value: string) => value.replace(/\s+/g, "");

export const isValidAadhaar = (value: string) =>
  /^\d{12}$/.test(normalizeAadhaar(value));

export const maskAadhaar = (value: string) =>
  `XXXX XXXX ${normalizeAadhaar(value).slice(-4)}`;

export const normalizeMobile = (value: string) => {
  const compact = value.replace(/[\s-]/g, "");
  return compact.startsWith(ABHA_COUNTRY_CODE)
    ? compact.slice(ABHA_COUNTRY_CODE.length)
    : compact;
};

export const isValidMobile = (value: string) =>
  /^[6-9]\d{9}$/.test(normalizeMobile(value));

/** Returns the `XX-XXXX-XXXX-XXXX` form, or null if it is not 14 digits */
export const normalizeAbhaNumber = (value: string) => {
  const digits = value.replace(/[\s-]/g, "");
  if (!/^\d{14}$/.test(digits)) {
    return null;
  }
  return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}-${digits.slice(10)}`;
};

/** Login accepts the address with or without the `@suffix` */
export const isValidAbhaAddressForLogin = (value: string) =>
  /^[^\s@]+(@[^\s@]+)?$/.test(value.trim());

/**
 * Rules for a new ABHA address (entered without the suffix). Returns the i18n
 * key of the first broken rule, or null when the address is valid.
 */
export const getNewAbhaAddressError = (value: string) => {
  if (value.includes("@")) {
    return "abha_address_rule_no_suffix";
  }
  if (value.length < 8 || value.length > 18) {
    return "abha_address_rule_length";
  }
  if (
    !/^[A-Za-z0-9._]+$/.test(value) ||
    (value.match(/\./g) ?? []).length > 1 ||
    (value.match(/_/g) ?? []).length > 1
  ) {
    return "abha_address_rule_characters";
  }
  if (/^[._]/.test(value) || /[._]$/.test(value)) {
    return "abha_address_rule_edges";
  }
  if (/^\d/.test(value)) {
    return "abha_address_rule_start";
  }
  return null;
};

/** Desk phone numbers are prefilled only when they are Indian (+91) numbers */
export const getDeskMobile = (phone?: string | null) => {
  if (!phone?.startsWith(ABHA_COUNTRY_CODE)) {
    return undefined;
  }
  const mobile = normalizeMobile(phone);
  return isValidMobile(mobile) ? mobile : undefined;
};

export const toIndianPhoneNumber = (mobile: string) =>
  `${ABHA_COUNTRY_CODE}${normalizeMobile(mobile)}`;

/** Route to CARE's existing patient verification page for a linked patient */
export const getLinkedPatientUrl = (
  facilityId: string,
  patient: LinkedPatient,
) => {
  const params = new URLSearchParams({
    phone_number: patient.phone_number,
    year_of_birth: String(patient.year_of_birth),
    partial_id: patient.partial_id,
  });
  return `/facility/${facilityId}/patients/home?${params.toString()}`;
};

export const getAbhaPhotoSrc = (photo?: string | null) =>
  photo ? `data:image/jpeg;base64,${photo}` : undefined;

export const blobToDataUrl = (blob: Blob) =>
  new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });

/** Same download pattern as `useFileManager` */
export const downloadBlob = (blob: Blob, fileName: string) => {
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  window.URL.revokeObjectURL(url);
  document.body.removeChild(anchor);
};

export type AbhaUiErrorCode = AbhaErrorCode | "network_error" | "unknown";

export interface AbhaUiError {
  code: AbhaUiErrorCode;
  message: string;
  /** Best-effort field name, used to show the error beside the input */
  field?: string;
  status?: number;
  /** Seconds to wait, with `resend_cooldown` */
  retryAfter?: number;
  linkedPatient?: LinkedPatient;
  /** When the error was received, used for the resend countdown */
  receivedAt: number;
}

const CODE_MESSAGE_KEYS: Partial<Record<AbhaErrorCode, string>> = {
  invalid_aadhaar: "abha_error_invalid_aadhaar",
  invalid_mobile: "abha_error_invalid_mobile",
  invalid_abha_number: "abha_error_invalid_abha_number",
  invalid_abha_address: "abha_error_invalid_abha_address",
  consent_required: "abha_error_consent_required",
  transaction_expired: "abha_error_transaction_expired",
  invalid_state: "abha_error_invalid_state",
  patient_already_has_abha: "abha_error_patient_already_has_abha",
  card_unavailable: "abha_error_card_unavailable",
  resend_limit_reached: "abha_error_resend_limit_reached",
  rate_limited: "abha_error_rate_limited",
  abdm_unavailable: "abha_error_abdm_unavailable",
  abdm_auth_failed: "abha_error_abdm_auth_failed",
  abdm_timeout: "abha_error_abdm_timeout",
  abdm_disabled: "abha_error_abdm_disabled",
};

/** Codes after which the journey cannot continue and must start again */
export const ABHA_RESTART_CODES: AbhaUiErrorCode[] = [
  "transaction_expired",
  "invalid_state",
];

interface ValidationErrorItem {
  type?: string;
  msg?: string | Record<string, string>;
  loc?: (string | number)[];
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isAbhaErrorItem = (value: unknown): value is AbhaErrorItem =>
  isRecord(value) && value.type === "abdm_error" && "code" in value;

const getValidationMessage = (item: ValidationErrorItem) => {
  if (typeof item.msg === "string") {
    return item.msg;
  }
  if (item.msg) {
    return Object.values(item.msg)[0];
  }
  return undefined;
};

/**
 * Normalises a failed ABHA call (contract §5.1 errors, CARE's validation
 * errors, DRF errors and network failures) into one shape for the UI.
 */
export function parseAbhaError(error: unknown, t: TFunction): AbhaUiError {
  const receivedAt = Date.now();

  if (!(error instanceof HTTPError)) {
    return {
      code: "network_error",
      message: t("abha_error_network"),
      receivedAt,
    };
  }

  const body = isRecord(error.cause) ? error.cause : undefined;
  const items = Array.isArray(body?.errors) ? (body.errors as unknown[]) : [];
  const abdmError = items.find(isAbhaErrorItem);

  if (abdmError) {
    const response = body as unknown as AbhaErrorResponse;
    const retryAfter = abdmError.retry_after ?? response.retry_after;
    const linkedPatient = abdmError.linked_patient ?? response.linked_patient;
    const code = abdmError.code;

    let message: string;
    if (code === "resend_cooldown") {
      message = retryAfter
        ? t("abha_error_resend_cooldown", { seconds: retryAfter })
        : t("abha_error_resend_cooldown_generic");
    } else if (code === "abha_already_linked") {
      message = linkedPatient
        ? t("abha_already_linked_to", {
            name: linkedPatient.name,
            partial_id: linkedPatient.partial_id,
          })
        : t("abha_error_abha_already_linked");
    } else {
      const key = CODE_MESSAGE_KEYS[code];
      message = key ? t(key) : abdmError.msg || t("something_went_wrong");
    }

    return {
      code,
      message,
      field: abdmError.field,
      status: error.status,
      retryAfter,
      linkedPatient,
      receivedAt,
    };
  }

  const validationError = items.find(isRecord) as
    | ValidationErrorItem
    | undefined;
  const validationMessage =
    validationError && getValidationMessage(validationError);
  const detail = typeof body?.detail === "string" ? body.detail : undefined;
  const loc = validationError?.loc;

  return {
    code: "unknown",
    message: validationMessage || detail || t("something_went_wrong"),
    field: loc?.length ? String(loc[loc.length - 1]) : undefined,
    status: error.status,
    receivedAt,
  };
}

import { Loader2Icon } from "lucide-react";
import { FormEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import RadioInput from "@/components/ui/RadioInput";

import { AbhaAuthMethod, AbhaIdentifierType } from "@/types/abdm/abha";

import { AbhaConsentPanel } from "./AbhaConsentPanel";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFact, AbhaFacts, AbhaTriedRoute } from "./useAbhaFacts";
import {
  ABHA_AUTH_METHOD_LABELS,
  ABHA_COUNTRY_CODE,
  ABHA_IDENTIFIER_LABELS,
  isValidAadhaar,
  isValidAbhaAddressForLogin,
  isValidMobile,
  normalizeAadhaar,
  normalizeAbhaNumber,
  normalizeMobile,
} from "./utils";

export interface AbhaIdentifyInput {
  type: AbhaIdentifierType;
  /** Normalised value, as sent to CARE */
  value: string;
  authMethod?: AbhaAuthMethod;
}

const IDENTIFIER_TYPES: AbhaIdentifierType[] = [
  "mobile",
  "aadhaar",
  "abha_number",
  "abha_address",
];

const AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

const PLACEHOLDERS: Record<AbhaIdentifierType, string> = {
  mobile: "abha_identifier_placeholder__mobile",
  aadhaar: "abha_identifier_placeholder__aadhaar",
  abha_number: "abha_identifier_placeholder__abha_number",
  abha_address: "abha_identifier_placeholder__abha_address",
};

/** Local validation (contract §5.1); nothing is sent when it fails */
const validate = (
  type: AbhaIdentifierType,
  value: string,
): { value: string } | { error: string } => {
  switch (type) {
    case "mobile":
      return isValidMobile(value)
        ? { value: normalizeMobile(value) }
        : { error: "abha_error_invalid_mobile" };
    case "aadhaar":
      return isValidAadhaar(value)
        ? { value: normalizeAadhaar(value) }
        : { error: "abha_error_invalid_aadhaar" };
    case "abha_number": {
      const abhaNumber = normalizeAbhaNumber(value);
      return abhaNumber
        ? { value: abhaNumber }
        : { error: "abha_error_invalid_abha_number" };
    }
    case "abha_address":
      return isValidAbhaAddressForLogin(value)
        ? { value: value.trim() }
        : { error: "abha_error_invalid_abha_address" };
  }
};

/**
 * Identify (screen 1): one screen for finding or creating an ABHA. It never
 * asks "login or create?"; creation is offered when no ABHA is found.
 */
export function AbhaIdentifyStep({
  facts,
  tried,
  initialType,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  facts: AbhaFacts;
  tried: AbhaTriedRoute[];
  initialType: AbhaIdentifierType;
  /** Server error for the identifier, shown under the input */
  error?: string;
  isPending: boolean;
  onSubmit: (input: AbhaIdentifyInput) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const inputId = `${id}-identifier`;
  const errorId = `${id}-error`;

  const [type, setType] = useState(initialType);
  const [values, setValues] = useState<Record<AbhaIdentifierType, string>>(
    () => ({
      mobile: facts.mobile?.value ?? "",
      aadhaar: "",
      abha_number: facts.abhaNumber?.value ?? "",
      abha_address: facts.abhaAddress?.value ?? "",
    }),
  );
  const [consented, setConsented] = useState(!!facts.consent);
  const [authMethod, setAuthMethod] = useState<AbhaAuthMethod>("aadhaar_otp");
  const [localError, setLocalError] = useState<string>();

  const value = values[type];
  const heldFacts: Record<AbhaIdentifierType, AbhaFact<string> | undefined> = {
    mobile: facts.mobile,
    aadhaar: undefined,
    abha_number: facts.abhaNumber,
    abha_address: facts.abhaAddress,
  };
  const heldFact = heldFacts[type];
  const needsConsent = type === "aadhaar" && !consented;
  const errorMessage = localError ?? error;

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    if (needsConsent || isPending) {
      return;
    }
    const result = validate(type, value);
    if ("error" in result) {
      setLocalError(t(result.error));
      return;
    }
    onSubmit({
      type,
      value: result.value,
      authMethod: type === "abha_number" ? authMethod : undefined,
    });
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-identify-step"
    >
      <AbhaStepHeading
        title={t("abha_identify_title")}
        description={t("abha_identify_description")}
      />

      <div className="flex flex-col gap-2">
        <Label>{t("abha_identify_with")}</Label>
        <RadioInput
          required
          value={type}
          disabled={isPending}
          onValueChange={(next) => {
            setType(next as AbhaIdentifierType);
            clearErrors();
          }}
          options={IDENTIFIER_TYPES.map((option) => ({
            value: option,
            label: t(ABHA_IDENTIFIER_LABELS[option]),
          }))}
        />
      </div>

      {type === "aadhaar" && (
        <AbhaConsentPanel checked={consented} onCheckedChange={setConsented} />
      )}

      <div className="flex flex-col gap-2">
        <Label htmlFor={inputId}>{t(ABHA_IDENTIFIER_LABELS[type])}</Label>
        <div className="flex items-center gap-2">
          {type === "mobile" && (
            <span className="rounded-md border border-gray-200 bg-gray-50 px-3 py-1.5 text-sm text-gray-700">
              {ABHA_COUNTRY_CODE}
            </span>
          )}
          <Input
            key={type}
            id={inputId}
            value={value}
            disabled={isPending || needsConsent}
            placeholder={t(PLACEHOLDERS[type])}
            autoComplete="off"
            inputMode={
              type === "abha_address" || type === "abha_number"
                ? "text"
                : "numeric"
            }
            aria-invalid={!!errorMessage}
            aria-describedby={errorMessage ? errorId : undefined}
            data-testid="abha-identifier-input"
            onChange={(event) => {
              setValues((current) => ({
                ...current,
                [type]: event.target.value,
              }));
              clearErrors();
            }}
          />
        </div>
        {heldFact && heldFact.value === value && (
          <AbhaProvenanceBadge source={heldFact.source} />
        )}
        <AbhaFieldError id={errorId} message={errorMessage} />
      </div>

      {type === "abha_number" && (
        <div className="flex flex-col gap-2">
          <Label>{t("abha_auth_method")}</Label>
          <RadioInput
            required
            value={authMethod}
            disabled={isPending}
            onValueChange={(next) => setAuthMethod(next as AbhaAuthMethod)}
            options={AUTH_METHODS.map((method) => ({
              value: method,
              label: t(ABHA_AUTH_METHOD_LABELS[method]),
            }))}
          />
        </div>
      )}

      {tried.length > 0 && (
        <div
          className="rounded-md bg-gray-50 p-3 text-sm text-gray-700"
          data-testid="abha-tried-routes"
        >
