import { useCallback, useReducer } from "react";

import { ABHA_CONSENT_VERSION, AbhaIdentifierType } from "@/types/abdm/abha";

/**
 * Page-scoped fact store for one ABHA journey ("never ask twice", contract
 * §6.2). It lives inside the journey component, so nothing survives into the
 * next journey or the next patient.
 */

export type AbhaFactSource =
  | "patient_search"
  | "desk"
  | "abha_profile"
  | "patient_record";

export interface AbhaFact<T> {
  value: T;
  source: AbhaFactSource;
}

export interface AbhaConsentFact {
  accepted: true;
  version: typeof ABHA_CONSENT_VERSION;
  at: string;
}

export interface AbhaFacts {
  /** 10 digits, without +91 */
  mobile?: AbhaFact<string>;
  /** Only the masked form ("XXXX XXXX 1234") is ever held */
  aadhaarMasked?: AbhaFact<string>;
  abhaNumber?: AbhaFact<string>;
  abhaAddress?: AbhaFact<string>;
  consent?: AbhaConsentFact;
}

export type AbhaFactKey = Exclude<keyof AbhaFacts, "consent">;

export type AbhaTriedReason = "no_account" | "not_found";

export interface AbhaTriedRoute {
  route: AbhaIdentifierType;
  reason: AbhaTriedReason;
}

interface AbhaFactsState {
  facts: AbhaFacts;
  tried: AbhaTriedRoute[];
}

type AbhaFactsAction =
  | {
      type: "set";
      key: AbhaFactKey;
      fact: AbhaFact<string>;
      /** An explicit edit on the step that owns the fact */
      override: boolean;
    }
  | { type: "consent"; at: string }
  | { type: "tried"; route: AbhaTriedRoute }
  | { type: "forget_source"; source: AbhaFactSource };

function reducer(
  state: AbhaFactsState,
  action: AbhaFactsAction,
): AbhaFactsState {
  switch (action.type) {
    case "set": {
      const current = state.facts[action.key];
      // Facts are write-once: a different value is refused unless the user
      // explicitly edited the field.
      if (current && (current.value === action.fact.value || !action.override))
        return state;
      return { ...state, facts: { ...state.facts, [action.key]: action.fact } };
    }
    case "consent": {
      if (state.facts.consent) return state;
      return {
        ...state,
        facts: {
          ...state.facts,
          consent: {
            accepted: true,
            version: ABHA_CONSENT_VERSION,
            at: action.at,
          },
        },
      };
    }
    case "tried": {
      const exists = state.tried.some(
        (tried) =>
          tried.route === action.route.route &&
          tried.reason === action.route.reason,
      );
      if (exists) return state;
      return { ...state, tried: [...state.tried, action.route] };
    }
    case "forget_source": {
      const facts = { ...state.facts };
      (["mobile", "aadhaarMasked", "abhaNumber", "abhaAddress"] as const)
        .filter((key) => facts[key]?.source === action.source)
        .forEach((key) => delete facts[key]);
      return { ...state, facts };
    }
  }
}

export function useAbhaFacts(initialFacts: AbhaFacts) {
  const [state, dispatch] = useReducer(reducer, {
    facts: initialFacts,
    tried: [],
  });

  const setFact = useCallback(
    (
      key: AbhaFactKey,
      value: string,
      source: AbhaFactSource,
      { override = false }: { override?: boolean } = {},
    ) => dispatch({ type: "set", key, fact: { value, source }, override }),
    [],
  );

  const recordConsent = useCallback(
    () => dispatch({ type: "consent", at: new Date().toISOString() }),
    [],
  );

  const addTried = useCallback(
    (route: AbhaTriedRoute) => dispatch({ type: "tried", route }),
    [],
  );

  const forgetSource = useCallback(
    (source: AbhaFactSource) => dispatch({ type: "forget_source", source }),
    [],
  );

  return {
    facts: state.facts,
    tried: state.tried,
    setFact,
    recordConsent,
    addTried,
    forgetSource,
  };
}

import mutate from "@/Utils/request/mutate";
import {
  AbhaCreateAddressRequest,
  AbhaCreateSendOtpRequest,
  AbhaJourney,
  AbhaSearchRequest,
  AbhaSelectAccountRequest,
  AbhaSendOtpRequest,
  AbhaTransactionRequest,
  AbhaVerifyOtpRequest,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";

import { abhaSilent } from "./utils";

/** Every journey step call; each one answers with the updated journey */
export type AbhaJourneyAction =
  | { type: "search"; body: AbhaSearchRequest }
  | { type: "send_otp"; body: AbhaSendOtpRequest }
  | { type: "create_send_otp"; body: AbhaCreateSendOtpRequest }
  | { type: "verify_otp"; body: AbhaVerifyOtpRequest }
  | { type: "resend_otp"; body: AbhaTransactionRequest }
  | { type: "select_account"; body: AbhaSelectAccountRequest }
  | { type: "skip_mobile_otp"; body: AbhaTransactionRequest }
  | { type: "create_address"; body: AbhaCreateAddressRequest };

export type AbhaJourneyActionType = AbhaJourneyAction["type"];

export function runAbhaJourneyAction(
  action: AbhaJourneyAction,
): Promise<AbhaJourney> {
  const options = { silent: abhaSilent };

  switch (action.type) {
    case "search":
      return mutate(abhaApi.search, options)(action.body);
    case "send_otp":
      return mutate(abhaApi.sendOtp, options)(action.body);
    case "create_send_otp":
      return mutate(abhaApi.createSendOtp, options)(action.body);
    case "verify_otp":
      return mutate(abhaApi.verifyOtp, options)(action.body);
    case "resend_otp":
      return mutate(abhaApi.resendOtp, options)(action.body);
    case "select_account":
      return mutate(abhaApi.selectAccount, options)(action.body);
    case "skip_mobile_otp":
      return mutate(abhaApi.skipMobileOtp, options)(action.body);
    case "create_address":
      return mutate(abhaApi.createAddress, options)(action.body);
  }
}

import { AbhaJourney, PatientAbha } from "@/types/abdm/abha";
import { PatientRead } from "@/types/emr/patient/patient";

import { AbhaFacts } from "./useAbhaFacts";

/**
 * - `register`: before the registration form; the result fills the form
 * - `link`: link an ABHA to an existing patient
 * - `reverify`: OTP for the ABHA already linked to a patient, to see the card
 */
export type AbhaJourneyMode = "register" | "link" | "reverify";

export interface AbhaJourneyResult {
  /** A `verified` journey */
  journey: AbhaJourney;
  facts: AbhaFacts;
  /** Set in `link` mode */
  patientAbha?: PatientAbha;
}

/** The existing patient, shown beside the ABHA profile before linking */
export type AbhaLinkTarget = Pick<
  PatientRead,
  "name" | "gender" | "date_of_birth" | "year_of_birth"
>;

