import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";

import { AbhaFactSource } from "./useAbhaFacts";

const SOURCE_LABELS: Record<AbhaFactSource, string> = {
  patient_search: "abha_source__patient_search",
  desk: "abha_source__desk",
  abha_profile: "abha_source__abha_profile",
  patient_record: "abha_source__patient_record",
};

/** Shows where a prefilled value came from */
export function AbhaProvenanceBadge({
  source,
  className,
}: {
  source: AbhaFactSource;
  className?: string;
}) {
  const { t } = useTranslation();

  return (
    <Badge
      variant="blue"
      size="xs"
      className={cn("w-fit font-normal", className)}
      data-testid="abha-provenance"
    >
      {t(SOURCE_LABELS[source])}
    </Badge>
  );
}
import { useId } from "react";
import { useTranslation } from "react-i18next";

import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";

/**
 * ABDM's Aadhaar consent (version 1.4). The text is shown exactly as written
 * and must be agreed to before an Aadhaar number can be entered or sent.
 */
export function AbhaConsentPanel({
  checked,
  onCheckedChange,
}: {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  const { t } = useTranslation();
  const id = useId();

  return (
    <div
      className="flex flex-col gap-3 rounded-md border border-gray-200 bg-gray-50 p-4"
      data-testid="abha-consent-panel"
