import { useMutation } from "@tanstack/react-query";
import { RotateCcwIcon } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import {
  AbhaAuthMethod,
  AbhaIdentifierType,
  AbhaJourney as AbhaJourneyResponse,
} from "@/types/abdm/abha";

import { AbhaAccountStep } from "./AbhaAccountStep";
import { AbhaAddressStep } from "./AbhaAddressStep";
import { AbhaConfirmIdentityStep } from "./AbhaConfirmIdentityStep";
import {
  AbhaCreateAadhaarInput,
  AbhaCreateAadhaarStep,
} from "./AbhaCreateAadhaarStep";
import { AbhaIdentifyInput, AbhaIdentifyStep } from "./AbhaIdentifyStep";
import { AbhaJourneyAction, runAbhaJourneyAction } from "./abhaJourneyActions";
import { AbhaMethodStep } from "./AbhaMethodStep";
import { AbhaNoAccountStep } from "./AbhaNoAccountStep";
import { AbhaOtpMobile, AbhaOtpStep } from "./AbhaOtpStep";
import { AbhaResultStep } from "./AbhaResultStep";
import { AbhaJourneyMode, AbhaJourneyResult, AbhaLinkTarget } from "./types";
import { AbhaFacts, useAbhaFacts } from "./useAbhaFacts";
import {
  ABHA_CONSENT,
  ABHA_RESTART_CODES,
  AbhaUiError,
  AbhaUiErrorCode,
  maskAadhaar,
  parseAbhaError,
} from "./utils";

/** Screens that are not a journey status of their own */
type AbhaLocalView = "identify" | "method" | "create_aadhaar";

type AbhaStepKind =
  | AbhaLocalView
  | "confirm_identity"
  | "otp"
  | "no_account"
  | "select_account"
  | "select_address"
  | "verified";

const ALL_AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

/** Errors that each step shows beside its own inputs; the rest go in a banner */
const INLINE_ERRORS: Partial<
  Record<AbhaStepKind, { fields: string[]; codes: AbhaUiErrorCode[] }>
> = {
  identify: {
    fields: ["identifier", "mobile", "aadhaar", "abha_number", "abha_address"],
    codes: [
      "invalid_mobile",
      "invalid_aadhaar",
      "invalid_abha_number",
      "invalid_abha_address",
      "consent_required",
    ],
  },
  otp: {
    fields: ["otp", "mobile"],
    codes: [
      "invalid_mobile",
      "resend_cooldown",
      "resend_limit_reached",
      "rate_limited",
    ],
  },
  create_aadhaar: {
    fields: ["aadhaar"],
    codes: ["invalid_aadhaar", "consent_required"],
  },
  select_address: {
    fields: ["abha_address"],
    codes: ["invalid_abha_address"],
  },
};

const isInlineError = (step: AbhaStepKind, error: AbhaUiError) => {
  const inline = INLINE_ERRORS[step];
  return (
    !!inline &&
    ((!!error.field && inline.fields.includes(error.field)) ||
      inline.codes.includes(error.code))
  );
};

const getStepKind = (
  view: AbhaLocalView | "journey",
  journey: AbhaJourneyResponse | null,
): AbhaStepKind => {
  if (view !== "journey" || !journey) {
    return view === "journey" ? "identify" : view;
  }
  return journey.status === "otp_sent" ? "otp" : journey.status;
};

/**
 * The ABHA journey (contract §6.3). One component for the three entry points:
 * registration, linking an existing patient and re-verifying a linked ABHA.
 * Each step talks to CARE only; CARE holds the ABDM transaction.
 */
export function AbhaJourney({
  mode,
  facilityId,
  patientId,
  initialFacts,
  linkTarget,
  onComplete,
  onExit,
}: {
  mode: AbhaJourneyMode;
  facilityId?: string;
  /** Required in `link` and `reverify` modes */
  patientId?: string;
  initialFacts: AbhaFacts;
  linkTarget?: AbhaLinkTarget;
  onComplete: (result: AbhaJourneyResult) => void;
  /** "Continue without ABHA" in register mode, "Cancel" otherwise */
  onExit: (facts: AbhaFacts) => void;
}) {
  const { t } = useTranslation();
  const { facts, tried, setFact, recordConsent, addTried, forgetSource } =
    useAbhaFacts(initialFacts);

  const initialView: AbhaLocalView =
    mode === "reverify" ? "method" : "identify";
  const [view, setView] = useState<AbhaLocalView | "journey">(initialView);
  const [journey, setJourney] = useState<AbhaJourneyResponse | null>(null);
  const [error, setError] = useState<AbhaUiError | null>(null);
  const [identifyType, setIdentifyType] =
    useState<AbhaIdentifierType>("mobile");

  // Journey-starting calls carry the context; later calls only the transaction
  const context = {
    facility: facilityId,
    patient: mode === "register" ? undefined : patientId,
  };

  const {
    mutate: run,
    isPending,
    variables,
    reset,
  } = useMutation({
    mutationFn: runAbhaJourneyAction,
    onMutate: () => setError(null),
    onSuccess: (next) => {
      setJourney(next);
      setView("journey");
      if (next.status === "no_account") {
        addTried({ route: next.identifier_type, reason: "no_account" });
      }
      if (next.status === "verified" && next.profile) {
        // Write-once: facts the desk already gave keep their value and source
        setFact("abhaNumber", next.profile.abha_number, "abha_profile");
        if (next.profile.abha_address) {
          setFact("abhaAddress", next.profile.abha_address, "abha_profile");
        }
        if (next.profile.mobile) {
          setFact("mobile", next.profile.mobile, "abha_profile");
        }
      }
    },
    onError: (failure, action: AbhaJourneyAction) => {
      const parsed = parseAbhaError(failure, t);
      setError(parsed);
      if (action.type === "search" && parsed.code === "ABDM-1211") {
        addTried({ route: "abha_address", reason: "not_found" });
      }
    },
  });

  const pendingAction = isPending ? variables?.type : undefined;
  const stepKind = getStepKind(view, journey);
  const stepKey =
    stepKind === "otp" ? `otp:${journey?.otp?.purpose ?? ""}` : stepKind;
  const inlineError =
    error && isInlineError(stepKind, error) ? error : undefined;
  const bannerError = error && !inlineError ? error : undefined;
  const mustRestart =
    !!bannerError && ABHA_RESTART_CODES.includes(bannerError.code);

  // Move focus to the new step's heading (not on the first render)
  const containerRef = useRef<HTMLDivElement>(null);
  const previousStepKey = useRef(stepKey);
  useEffect(() => {
    if (previousStepKey.current === stepKey) {
      return;
    }
    previousStepKey.current = stepKey;
    containerRef.current
      ?.querySelector<HTMLElement>("[data-abha-step-heading]")
      ?.focus();
  }, [stepKey]);

  const clearError = () => setError(null);

  const showLocalError = (message: string) =>
    setError({ code: "unknown", message, receivedAt: Date.now() });

  const restart = () => {
    reset();
    setError(null);
    setJourney(null);
    forgetSource("abha_profile");
    setView(initialView);
  };

  const backToIdentify = () => {
    reset();
    setError(null);
    setJourney(null);
    setView("identify");
  };

  const handleIdentify = ({ type, value, authMethod }: AbhaIdentifyInput) => {
    setIdentifyType(type);
    switch (type) {
      case "mobile":
        setFact("mobile", value, "desk", { override: true });
        break;
      case "aadhaar":
        setFact("aadhaarMasked", maskAadhaar(value), "desk", {
          override: true,
        });
        recordConsent();
        break;
      case "abha_number":
        setFact("abhaNumber", value, "desk", { override: true });
        break;
      case "abha_address":
        setFact("abhaAddress", value, "desk", { override: true });
        break;
    }

    if (type === "abha_address") {
      run({ type: "search", body: { abha_address: value, ...context } });
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: type,
        identifier: value,
        auth_method: authMethod,
        consent: type === "aadhaar" ? ABHA_CONSENT : undefined,
        ...context,
      },
    });
  };

  const sendAddressOtp = (authMethod: AbhaAuthMethod) => {
    if (!journey) {
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_address",
        transaction_id: journey.transaction_id,
        auth_method: authMethod,
      },
    });
  };

  const handleConfirmIdentity = () => {
    const methods = journey?.auth_methods ?? [];
    if (methods.length > 1) {
      setError(null);
      setView("method");
    } else if (methods.length === 1) {
      sendAddressOtp(methods[0]);
    } else {
      showLocalError(t("abha_error_no_auth_methods"));
    }
  };

  const handleMethod = (authMethod: AbhaAuthMethod) => {
    if (journey?.status === "confirm_identity") {
      sendAddressOtp(authMethod);
      return;
    }
    // Re-verify the ABHA number held on the patient record
    if (!facts.abhaNumber) {
      showLocalError(t("abha_error_invalid_abha_number"));
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_number",
        identifier: facts.abhaNumber.value,
        auth_method: authMethod,
        ...context,
      },
    });
  };

  const startCreate = (aadhaar?: string) => {
    if (!journey) {
      return;
    }
    run({
      type: "create_send_otp",
      body: {
        transaction_id: journey.transaction_id,
        aadhaar,
        consent: journey.consent_recorded ? undefined : ABHA_CONSENT,
      },
    });
  };

  const handleNoAccountCreate = () => {
    if (!journey) {
      return;
    }
    // Ask only for what the journey does not hold
    const needsAadhaar = journey.identifier_type !== "aadhaar";
    const needsConsent = !journey.consent_recorded && !facts.consent;
    if (needsAadhaar || needsConsent) {
      setError(null);
      setView("create_aadhaar");
      return;
    }
    startCreate();
  };

  const handleCreateAadhaar = ({ aadhaar }: AbhaCreateAadhaarInput) => {
    if (aadhaar) {
      setFact("aadhaarMasked", maskAadhaar(aadhaar), "desk", {
        override: true,
      });
    }
    recordConsent();
    startCreate(aadhaar);
  };

  const handleVerifyOtp = (
    otp: string,
    mobile: AbhaOtpMobile | undefined,
    onError: () => void,
  ) => {
    if (!journey) {
      return;
    }
    if (mobile) {
      setFact("mobile", mobile.value, "desk", { override: mobile.edited });
    }
    run(
      {
        type: "verify_otp",
        body: {
          transaction_id: journey.transaction_id,
          otp,
          mobile: mobile?.value,
        },
      },
      { onError },
    );
  };

  const renderStep = () => {
    switch (stepKind) {
      case "identify":
        return (
          <AbhaIdentifyStep
            facts={facts}
            tried={tried}
            initialType={identifyType}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={handleIdentify}
            onClearError={clearError}
          />
        );
      case "method": {
        const fromSearch = journey?.status === "confirm_identity";
        return (
          <AbhaMethodStep
            methods={fromSearch ? journey.auth_methods : ALL_AUTH_METHODS}
            identifierLabel={fromSearch ? t("abha_address") : t("abha_number")}
            identifier={
              fromSearch
                ? (journey.search_result?.abha_address ??
                  journey.masked_identifier)
                : facts.abhaNumber
            }
            isPending={isPending}
            onSubmit={handleMethod}
          />
        );
      }
      case "create_aadhaar":
        return (
          journey && (
            <AbhaCreateAadhaarStep
              facts={facts}
              needsAadhaar={journey.identifier_type !== "aadhaar"}
              needsConsent={!journey.consent_recorded && !facts.consent}
              error={inlineError?.message}
              isPending={isPending}
              onSubmit={handleCreateAadhaar}
              onClearError={clearError}
            />
          )
        );
    }

    if (!journey) {
      return null;
    }
    const transactionId = journey.transaction_id;

    switch (stepKind) {
      case "confirm_identity":
        return (
          <AbhaConfirmIdentityStep
            searchResult={journey.search_result}
            isPending={isPending}
            onConfirm={handleConfirmIdentity}
            onReject={backToIdentify}
          />
        );
      case "otp":
        return (
          journey.otp && (
            <AbhaOtpStep
              key={`${transactionId}-${journey.otp.purpose}`}
              otp={journey.otp}
              facts={facts}
              error={inlineError ?? null}
              pendingAction={pendingAction}
              onVerify={handleVerifyOtp}
              onResend={() =>
                run({
                  type: "resend_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onSkip={() =>
                run({
                  type: "skip_mobile_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onClearError={clearError}
            />
          )
        );
      case "no_account":
        return (
          <AbhaNoAccountStep
            journey={journey}
            isPending={isPending}
            onCreate={handleNoAccountCreate}
            onTryAnother={backToIdentify}
          />
        );
      case "select_account":
        return (
          <AbhaAccountStep
            accounts={journey.accounts ?? []}
            isPending={isPending}
            onSelect={(abhaNumber) =>
              run({
                type: "select_account",
                body: {
                  transaction_id: transactionId,
                  abha_number: abhaNumber,
                },
              })
            }
          />
        );
      case "select_address":
        return (
          <AbhaAddressStep
            key={transactionId}
            transactionId={transactionId}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={(address) =>
              run({
                type: "create_address",
                body: { transaction_id: transactionId, abha_address: address },
              })
            }
            onClearError={clearError}
          />
        );
      case "verified":
        return (
          <AbhaResultStep
            mode={mode}
            journey={journey}
            facilityId={facilityId}
            patientId={patientId}
            linkTarget={linkTarget}
            onContinue={() => onComplete({ journey, facts })}
            onLinked={(patientAbha) =>
              onComplete({ journey, facts, patientAbha })
            }
          />
        );
    }
  };

  return (
    <div
      ref={containerRef}
      className="flex flex-col gap-5"
      data-testid="abha-journey"
      data-step={stepKey}
    >
      {renderStep()}

      {bannerError && (
        <Alert variant="destructive" data-testid="abha-journey-error">
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{bannerError.message}</span>
            {mustRestart && (
              <Button variant="outline" size="sm" onClick={restart}>
                <RotateCcwIcon />
                {t("abha_start_again")}
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-gray-200 pt-4">
        <div>
          {stepKind !== initialView && !mustRestart && (
            <Button
              variant="ghost"
              size="sm"
              disabled={isPending}
              onClick={restart}
              data-testid="abha-start-again"
            >
              <RotateCcwIcon />
              {t("abha_start_again")}
            </Button>
          )}
        </div>
        <Button
          variant="outline"
          onClick={() => onExit(facts)}
          data-testid="abha-exit"
        >
          {mode === "register" ? t("abha_continue_without") : t("cancel")}
        </Button>
      </div>
    </div>
  );
}

