* Result (screen 7). Shows the verified ABHA with its card. An ABHA already
 * linked to another patient blocks continuing (TAGGING).
 */
export function AbhaResultStep({
  mode,
  journey,
  facilityId,
  patientId,
  linkTarget,
  onContinue,
  onLinked,
}: {
  mode: AbhaJourneyMode;
  journey: AbhaJourney;
  facilityId?: string;
  patientId?: string;
  linkTarget?: AbhaLinkTarget;
  /** Register mode fills the form; reverify mode closes the journey */
  onContinue: () => void;
  onLinked: (patientAbha: PatientAbha) => void;
}) {
  const { t } = useTranslation();
  const profile = journey.profile;
  const [cardOpen, setCardOpen] = useState(mode === "reverify");
  const [linkError, setLinkError] = useState<AbhaUiError | null>(null);

  const { mutate: link, isPending: isLinking } = useMutation({
    mutationFn: mutate(abhaApi.link, { silent: abhaSilent }),
    onMutate: () => setLinkError(null),
    onSuccess: onLinked,
    onError: (error) => setLinkError(parseAbhaError(error, t)),
  });

  const otherPatient: LinkedPatient | undefined =
    (journey.linked_patient && !journey.linked_patient.is_current_patient
      ? journey.linked_patient
      : undefined) ??
    (linkError?.code === "abha_already_linked"
      ? linkError.linkedPatient
      : undefined);
  const isBlocked = !!otherPatient;

  return (
    <div className="flex flex-col gap-5" data-testid="abha-result-step">
      <AbhaStepHeading
        title={profile?.is_new ? t("abha_created") : t("abha_verified")}
        description={journey.message ?? undefined}
      />

      {profile && <AbhaProfileSummary profile={profile} />}

      {otherPatient && (
        <AbhaLinkedPatientAlert
          patient={otherPatient}
          facilityId={facilityId}
        />
      )}

      {mode === "link" && profile && linkTarget && !isBlocked && (
        <AbhaLinkComparison patient={linkTarget} profile={profile} />
      )}

      {linkError && !otherPatient && (
        <Alert variant="destructive" data-testid="abha-link-error">
          <AlertDescription>{linkError.message}</AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          variant="outline"
          onClick={() => setCardOpen(true)}
          data-testid="abha-view-card"
        >
          <IdCardIcon />
          {t("abha_view_card")}
        </Button>

        {mode === "register" && !isBlocked && (
          <Button variant="primary" onClick={onContinue}>
            {t("continue")}
          </Button>
        )}

        {mode === "link" && !isBlocked && patientId && (
          <Button
            variant="primary"
            disabled={isLinking}
            onClick={() =>
              link({
                transaction_id: journey.transaction_id,
                patient: patientId,
              })
            }
          >
            {isLinking && <Loader2Icon className="animate-spin" />}
            {t("abha_link_confirm")}
          </Button>
        )}

        {mode === "reverify" && (
          <Button variant="primary" onClick={onContinue}>
            {t("done")}
          </Button>
        )}
      </div>

      <AbhaCardDialog
        transactionId={journey.transaction_id}
        abhaNumber={profile?.abha_number}
        open={cardOpen}
        onOpenChange={setCardOpen}
      />
    </div>
  );
}
