function AbhaLinkComparison({
  patient,
  profile,
}: {
  patient: AbhaLinkTarget;
  profile: AbhaProfile;
}) {
  const { t } = useTranslation();

  const rows = [
    { label: t("name"), patient: patient.name, abha: profile.name },
    {
      label: t("abha_birth_details"),
      patient: formatBirth(patient),
      abha: formatBirth(profile),
    },
    {
      label: t("sex"),
      patient: patient.gender && t(`GENDER__${patient.gender}`),
      abha: profile.gender && t(`GENDER__${profile.gender}`),
    },
  ];

  return (
    <div className="flex flex-col gap-2" data-testid="abha-link-comparison">
      <p className="text-sm text-gray-700">{t("abha_link_compare_hint")}</p>
      <div className="overflow-x-auto rounded-md border border-gray-200">
        <table className="w-full text-left text-sm">
          <thead className="bg-gray-50 text-xs text-gray-600">
            <tr>
              <th scope="col" className="px-3 py-2 font-medium">
                <span className="sr-only">{t("abha_link_field")}</span>
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abha_link_this_patient")}
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abha_link_abha_profile")}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.label} className="border-t border-gray-200">
                <th scope="row" className="px-3 py-2 font-medium text-gray-600">
                  {row.label}
                </th>
                <td className="px-3 py-2 text-gray-900">
                  {row.patient || "-"}
                </td>
                <td className="px-3 py-2 text-gray-900">{row.abha || "-"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * Result (screen 7). Shows the verified ABHA with its card. An ABHA already
 * linked to another patient blocks continuing (TAGGING).
 */
export function AbhaResultStep({
  mode,
  journey,
  facilityId,
  patientId,
  linkTarget,
  onContinue,
  onLinked,
}: {
  mode: AbhaJourneyMode;
  journey: AbhaJourney;
  facilityId?: string;
  patientId?: string;
  linkTarget?: AbhaLinkTarget;
  /** Register mode fills the form; reverify mode closes the journey */
  onContinue: () => void;
  onLinked: (patientAbha: PatientAbha) => void;
}) {
  const { t } = useTranslation();
  const profile = journey.profile;
  const [cardOpen, setCardOpen] = useState(mode === "reverify");
  const [linkError, setLinkError] = useState<AbhaUiError | null>(null);

  const { mutate: link, isPending: isLinking } = useMutation({
    mutationFn: mutate(abhaApi.link, { silent: abhaSilent }),
    onMutate: () => setLinkError(null),
    onSuccess: onLinked,
    onError: (error) => setLinkError(parseAbhaError(error, t)),
  });

  const otherPatient: LinkedPatient | undefined =
    (journey.linked_patient && !journey.linked_patient.is_current_patient
      ? journey.linked_patient
      : undefined) ??
    (linkError?.code === "abha_already_linked"
      ? linkError.linkedPatient
      : undefined);
  const isBlocked = !!otherPatient;

  return (
    <div className="flex flex-col gap-5" data-testid="abha-result-step">
      <AbhaStepHeading
        title={profile?.is_new ? t("abha_created") : t("abha_verified")}
        description={journey.message ?? undefined}
      />

      {profile && <AbhaProfileSummary profile={profile} />}

      {otherPatient && (
        <AbhaLinkedPatientAlert
          patient={otherPatient}
          facilityId={facilityId}
        />
      )}

      {mode === "link" && profile && linkTarget && !isBlocked && (
        <AbhaLinkComparison patient={linkTarget} profile={profile} />
      )}

      {linkError && !otherPatient && (
        <Alert variant="destructive" data-testid="abha-link-error">
          <AlertDescription>{linkError.message}</AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          variant="outline"
          onClick={() => setCardOpen(true)}
          data-testid="abha-view-card"
        >
          <IdCardIcon />
          {t("abha_view_card")}
        </Button>

        {mode === "register" && !isBlocked && (
          <Button variant="primary" onClick={onContinue}>
            {t("continue")}
          </Button>
        )}

        {mode === "link" && !isBlocked && patientId && (
          <Button
            variant="primary"
            disabled={isLinking}
            onClick={() =>
              link({
                transaction_id: journey.transaction_id,
                patient: patientId,
              })
            }
          >
            {isLinking && <Loader2Icon className="animate-spin" />}
            {t("abha_link_confirm")}
          </Button>
        )}

        {mode === "reverify" && (
          <Button variant="primary" onClick={onContinue}>
            {t("done")}
          </Button>
        )}
      </div>

      <AbhaCardDialog
        transactionId={journey.transaction_id}
        abhaNumber={profile?.abha_number}
        open={cardOpen}
        onOpenChange={setCardOpen}
      />
    </div>
  );
}

import { TFunction } from "i18next";
import { IdCardIcon, PlusIcon, XIcon } from "lucide-react";
import { useState } from "react";
import { useFormContext } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import mutate from "@/Utils/request/mutate";
import abhaApi from "@/types/abdm/abhaApi";
import { GenderChoices } from "@/types/emr/patient/patient";

import { AbhaJourney } from "./AbhaJourney";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaJourneyResult } from "./types";
import { AbhaFact, AbhaFacts } from "./useAbhaFacts";
import {
  abhaSilent,
  getDeskMobile,
  parseAbhaError,
  toIndianPhoneNumber,
} from "./utils";

/** The registration form fields the ABHA step reads and fills */
interface AbhaRegistrationFormValues {
  name: string;
  gender: GenderChoices;
  age_or_dob: "dob" | "age";
  date_of_birth?: string | null;
  age?: number | null;
  phone_number: string;
  emergency_phone_number?: string;
  emergency_phone_number_same_as_phone_number: boolean;
  address?: string;
  permanent_address?: string;
  permanent_address_same_as_address: boolean;
  pincode?: number;
}

export type AbhaPrefillField =
  | "name"
  | "gender"
  | "date_of_birth"
  | "age"
  | "phone_number"
  | "address"
  | "pincode";

/** Form values filled by the ABHA step, with where each one came from */
export type AbhaPrefill = Partial<
  Record<AbhaPrefillField, AbhaFact<string | number>>
>;

/** A verified ABHA to link once the patient is created */
export interface AbhaRegistrationLink {
  transactionId: string;
  abhaNumber: string | null;
  abhaAddress: string | null;
  kycVerified: boolean;
}

type AbhaSnapshot = Pick<
  AbhaRegistrationFormValues,
  | "name"
  | "gender"
  | "age_or_dob"
  | "date_of_birth"
  | "age"
  | "phone_number"
  | "emergency_phone_number"
  | "address"
  | "permanent_address"
  | "pincode"
>;

const MIN_AGE = 1;
const MAX_AGE = 120;

/**
 * State of the ABHA step on the registration page (contract §6.4). It is
 * shared with the form, which locks and badges the fields filled from ABHA.
 */
export function useAbhaRegistration(enabled: boolean) {
  const [journeyOpen, setJourneyOpen] = useState(enabled);
  const [link, setLink] = useState<AbhaRegistrationLink | null>(null);
  const [prefill, setPrefill] = useState<AbhaPrefill>({});

  return {
    enabled,
    journeyOpen: enabled && journeyOpen,
    link: enabled ? link : null,
    prefill: enabled ? prefill : {},
    setJourneyOpen,
    setLink,
    setPrefill,
  };
}

export type AbhaRegistrationState = ReturnType<typeof useAbhaRegistration>;

/**
 * Links the verified ABHA to the patient that was just created. A failure is
 * reported but never blocks or rolls back the registration.
 */
export async function linkAbhaAfterRegistration(
  link: AbhaRegistrationLink,
  patientId: string,
  t: TFunction,
) {
  try {
    await mutate(abhaApi.link, { silent: abhaSilent })({
      transaction_id: link.transactionId,
      patient: patientId,
    });
    toast.success(t("abha_linked_success"));
  } catch (error) {
    toast.error(
      t("abha_link_after_registration_failed", {
        reason: parseAbhaError(error, t).message,
      }),
    );
  }
}

/** Provenance badge for a form field, while it still holds the filled value */
export function AbhaPrefillBadge({
  fact,
  value,
}: {
  fact?: AbhaFact<string | number>;
  value: unknown;
}) {
  if (!fact || String(value ?? "") !== String(fact.value)) {
    return null;
  }
  return (
    <div>
      <AbhaProvenanceBadge source={fact.source} />
    </div>
  );
}

/**
 * The ABHA step on the registration page: the journey before the form, then
 * a summary of the ABHA that will be linked when the patient is saved.
 */
export function AbhaRegistration({
  abha,
  facilityId,
  searchedPhone,
}: {
  abha: AbhaRegistrationState;
  facilityId?: string;
  /** The `phone_number` the desk searched with before registering */
  searchedPhone?: string;
}) {
  const { t } = useTranslation();
  const form = useFormContext<AbhaRegistrationFormValues>();
  const [snapshot, setSnapshot] = useState<AbhaSnapshot | null>(null);
  const [journeyKey, setJourneyKey] = useState(0);

  const getInitialFacts = (): AbhaFacts => {
    const phone = form.getValues("phone_number");
    const mobile = getDeskMobile(phone);
    if (!mobile) {
      return {};
    }
    return {
      mobile: {
        value: mobile,
        source: phone === searchedPhone ? "patient_search" : "desk",
      },
    };
  };

  const setField = <K extends keyof AbhaRegistrationFormValues>(
    name: K,
    value: AbhaRegistrationFormValues[K],
  ) =>
    // Typed through the minimal interface above; the names match the form
    form.setValue(
      name as Parameters<typeof form.setValue>[0],
      value as Parameters<typeof form.setValue>[1],
      { shouldDirty: true, shouldValidate: form.formState.isSubmitted },
    );

  const setPhone = (phone: string) => {
    setField("phone_number", phone);
    if (form.getValues("emergency_phone_number_same_as_phone_number")) {
      setField("emergency_phone_number", phone);
    }
  };

  const handleComplete = ({ journey, facts }: AbhaJourneyResult) => {
    const profile = journey.profile;
    if (!profile) {
      abha.setJourneyOpen(false);
      return;
    }

    const values = form.getValues();
    setSnapshot({
      name: values.name,
      gender: values.gender,
      age_or_dob: values.age_or_dob,
      date_of_birth: values.date_of_birth,
      age: values.age,
      phone_number: values.phone_number,
      emergency_phone_number: values.emergency_phone_number,
      address: values.address,
      permanent_address: values.permanent_address,
      pincode: values.pincode,
    });

    const prefill: AbhaPrefill = {};
    const fromAbha = <T extends string | number>(value: T) => ({
      value,
      source: "abha_profile" as const,
    });

    setField("name", profile.name);
    prefill.name = fromAbha(profile.name);

    if (profile.gender) {
      setField("gender", profile.gender);
      prefill.gender = fromAbha(profile.gender);
    }

    if (profile.date_of_birth) {
      setField("age_or_dob", "dob");
      setField("date_of_birth", profile.date_of_birth);
      prefill.date_of_birth = fromAbha(profile.date_of_birth);
    } else if (profile.year_of_birth) {
      const age = new Date().getFullYear() - profile.year_of_birth;
      if (age >= MIN_AGE && age <= MAX_AGE) {
        setField("age_or_dob", "age");
        setField("age", age);
        prefill.age = fromAbha(age);
      }
    }

    // The desk's mobile wins over the one on the ABHA profile
    const mobile = facts.mobile ?? (profile.mobile && fromAbha(profile.mobile));
    if (mobile) {
      const phone = toIndianPhoneNumber(mobile.value);
      setPhone(phone);
      prefill.phone_number = { value: phone, source: mobile.source };
    }

    if (profile.address) {
      setField("address", profile.address);
      if (form.getValues("permanent_address_same_as_address")) {
        setField("permanent_address", profile.address);
      }
      prefill.address = fromAbha(profile.address);
    }

    if (profile.pincode && /^\d{6}$/.test(profile.pincode)) {
      const pincode = Number(profile.pincode);
      setField("pincode", pincode);
      prefill.pincode = fromAbha(pincode);
    }

    abha.setPrefill(prefill);
    abha.setLink({
      transactionId: journey.transaction_id,
      abhaNumber: profile.abha_number,
      abhaAddress: profile.abha_address,
      kycVerified: profile.kyc_verified,
    });
    abha.setJourneyOpen(false);
  };

  const handleExit = (facts: AbhaFacts) => {
    if (facts.mobile) {
      const phone = toIndianPhoneNumber(facts.mobile.value);
      setPhone(phone);
      abha.setPrefill({
        phone_number: { value: phone, source: facts.mobile.source },
      });
    }
    abha.setJourneyOpen(false);
  };

  const handleRemove = () => {
    // Undo only the values the desk has not edited since they were filled
    const prefill = abha.prefill;
    const isUnchanged = (field: AbhaPrefillField) =>
      prefill[field] !== undefined &&
      String(form.getValues(field) ?? "") === String(prefill[field]?.value);

    if (snapshot) {
      if (isUnchanged("name")) setField("name", snapshot.name);
      if (isUnchanged("gender")) setField("gender", snapshot.gender);
      if (isUnchanged("date_of_birth") || isUnchanged("age")) {
        setField("age_or_dob", snapshot.age_or_dob);
        setField("date_of_birth", snapshot.date_of_birth);
        setField("age", snapshot.age);
      }
      if (isUnchanged("phone_number")) setPhone(snapshot.phone_number);
      if (isUnchanged("address")) {
        setField("address", snapshot.address);
        if (form.getValues("permanent_address_same_as_address")) {
          setField("permanent_address", snapshot.address);
        }
      }
      if (isUnchanged("pincode")) setField("pincode", snapshot.pincode);
    }

    setSnapshot(null);
    abha.setPrefill({});
    abha.setLink(null);
  };

  const openJourney = () => {
    setJourneyKey((key) => key + 1);
    abha.setJourneyOpen(true);
  };

  if (abha.journeyOpen) {
    return (
      <div
        className="mb-6 flex flex-col gap-4 rounded-md bg-white p-6 shadow"
        data-testid="abha-registration-journey"
      >
        <div className="flex flex-col gap-1">
          <h5 className="text-lg font-semibold">
            {t("abha_registration_title")}
          </h5>
          <p className="text-sm text-gray-700">
            {t("abha_registration_description")}
          </p>
        </div>
        <AbhaJourney
          key={journeyKey}
          mode="register"
          facilityId={facilityId}
          initialFacts={getInitialFacts()}
          onComplete={handleComplete}
          onExit={handleExit}
        />
      </div>
    );
  }

  if (abha.link) {
    return (
      <div
        className="mb-6 flex flex-col gap-3 rounded-md border border-primary-200 bg-primary-50 p-4 sm:flex-row sm:items-center sm:justify-between"
        data-testid="abha-registration-summary"
      >
        <div className="flex items-start gap-3">
          <IdCardIcon className="mt-0.5 size-5 shrink-0 text-primary-700" />
          <div className="flex flex-col gap-1 text-sm">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-semibold text-gray-900">
                {t("abha_registration_title")}
              </span>
              <Badge
                variant={abha.link.kycVerified ? "green" : "yellow"}
                size="xs"
              >
                {abha.link.kycVerified
                  ? t("abha_kyc_verified")
                  : t("abha_kyc_not_verified")}
              </Badge>
            </div>
            {abha.link.abhaNumber && (
              <span data-testid="abha-registration-number">
                {t("abha_number")}: {abha.link.abhaNumber}
              </span>
            )}
            {abha.link.abhaAddress && (
              <span
                className="break-all"
                data-testid="abha-registration-address"
              >
                {t("abha_address")}: {abha.link.abhaAddress}
              </span>
            )}
            <span className="text-gray-600">{t("abha_will_be_linked")}</span>
          </div>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleRemove}
          data-testid="abha-registration-remove"
        >
          <XIcon />
          {t("abha_remove")}
        </Button>
      </div>
    );
  }

  return (
    <div
      className="mb-6 flex flex-col gap-3 rounded-md border border-gray-200 bg-white p-4 sm:flex-row sm:items-center sm:justify-between"
      data-testid="abha-registration-add"
    >
      <p className="text-sm text-gray-700">{t("abha_add_prompt")}</p>
      <Button type="button" variant="outline" size="sm" onClick={openJourney}>
        <PlusIcon />
        {t("abha_add")}
      </Button>
    </div>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { IdCardIcon, LinkIcon, RefreshCwIcon, UnlinkIcon } from "lucide-react";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Skeleton } from "@/components/ui/skeleton";

import ConfirmActionDialog from "@/components/Common/ConfirmActionDialog";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { formatDateTime, formatName } from "@/Utils/utils";
import { PatientAbhaLinked } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { PatientRead } from "@/types/emr/patient/patient";

import { AbhaJourney } from "./AbhaJourney";
import { AbhaKycBadge } from "./AbhaProfileSummary";
import { AbhaJourneyResult } from "./types";
import { AbhaFacts } from "./useAbhaFacts";
import { abhaSilent, getDeskMobile, parseAbhaError } from "./utils";

type AbhaSheetMode = "link" | "reverify";

const getPatientMobileFacts = (patient: PatientRead): AbhaFacts => {
  const mobile = getDeskMobile(patient.phone_number);
  return mobile ? { mobile: { value: mobile, source: "patient_record" } } : {};
};

function AbhaSectionDetail({
  label,
  testId,
  children,
}: {
  label: string;
  testId?: string;
  children: ReactNode;
}) {
  return (
    <div className="sm:col-span-1">
      <div className="text-sm leading-5 font-normal text-gray-500">{label}</div>
      <div
        className="mt-1 text-sm leading-5 font-semibold break-all text-gray-900"
        data-testid={testId}
      >
        {children}
      </div>
    </div>
  );
}

/**
 * ABHA section of the patient's Demography tab (contract §6.5): the linked
 * ABHA with re-verified card access and unlink, or "Link ABHA".
 */
export function AbhaSection({
  patient,
  facilityId,
  canWrite,
}: {
  patient: PatientRead;
  facilityId?: string;
  canWrite: boolean;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [sheetMode, setSheetMode] = useState<AbhaSheetMode | null>(null);
  const [confirmUnlink, setConfirmUnlink] = useState(false);

  const queryKey = ["patient", patient.id, "abha"];

  const abhaQuery = useQuery({
    queryKey,
    queryFn: query(abhaApi.getPatientAbha, {
      pathParams: { patientId: patient.id },
      silent: abhaSilent,
    }),
    retry: false,
  });

  const refreshPatient = () =>
    queryClient.invalidateQueries({ queryKey: ["patient", patient.id] });

  const { mutate: unlink, isPending: isUnlinking } = useMutation({
    mutationFn: mutate(abhaApi.unlinkPatientAbha, {
      pathParams: { patientId: patient.id },
      silent: abhaSilent,
    }),
    onSuccess: (result) => {
      queryClient.setQueryData(queryKey, result);
      refreshPatient();
      setConfirmUnlink(false);
      toast.success(t("abha_unlinked_success"));
    },
    onError: (error) => toast.error(parseAbhaError(error, t).message),
  });

  const handleComplete = ({ patientAbha }: AbhaJourneyResult) => {
    setSheetMode(null);
    if (patientAbha) {
      queryClient.setQueryData(queryKey, patientAbha);
      refreshPatient();
      toast.success(t("abha_linked_success"));
    }
  };

  const abha = abhaQuery.data;
  const linked: PatientAbhaLinked | undefined = abha?.linked ? abha : undefined;
  const queryError = abhaQuery.error
    ? parseAbhaError(abhaQuery.error, t)
    : null;

  const initialFacts: AbhaFacts =
    sheetMode === "reverify" && linked
      ? { abhaNumber: { value: linked.abha_number, source: "patient_record" } }
      : getPatientMobileFacts(patient);

  return (
    <div

            {t("abha_not_linked")}
          </p>
        )}

        {linked && (
          <div className="grid grid-cols-1 gap-x-4 gap-y-2 sm:grid-cols-2 md:gap-y-8">
            <AbhaSectionDetail
              label={t("abha_number")}
              testId="abha-section-number"
            >
              {linked.abha_number}
            </AbhaSectionDetail>
            <AbhaSectionDetail
              label={t("abha_address")}
              testId="abha-section-address"
            >
              {linked.abha_address || "-"}
            </AbhaSectionDetail>
            <AbhaSectionDetail label={t("abha_kyc_status")}>
              <AbhaKycBadge verified={linked.kyc_verified} />
            </AbhaSectionDetail>
            <AbhaSectionDetail label={t("abha_linked_on")}>
              {formatDateTime(linked.linked_on, "DD MMM YYYY, hh:mm A")}
            </AbhaSectionDetail>
            <AbhaSectionDetail label={t("abha_linked_by")}>
              {formatName(linked.linked_by)}
            </AbhaSectionDetail>
          </div>
        )}
      </div>

      <Sheet
        open={!!sheetMode}
        onOpenChange={(open) => !open && setSheetMode(null)}
      >
        <SheetContent
          className="w-full overflow-y-auto sm:max-w-2xl"
          data-testid="abha-section-sheet"
        >
          <SheetHeader className="mb-4 p-0">
            <SheetTitle>
              {sheetMode === "reverify" ? t("abha_view_card") : t("abha_link")}
            </SheetTitle>
            <SheetDescription>
              {sheetMode === "reverify"
                ? t("abha_reverify_description")
                : t("abha_link_description", { name: patient.name })}
            </SheetDescription>
          </SheetHeader>
          {sheetMode && (
            <AbhaJourney
              key={sheetMode}
              mode={sheetMode}
              facilityId={facilityId}
              patientId={patient.id}
              initialFacts={initialFacts}
              linkTarget={patient}
              onComplete={handleComplete}
              onExit={() => setSheetMode(null)}
            />
          )}
        </SheetContent>
      </Sheet>

      <ConfirmActionDialog
        open={confirmUnlink}
        onOpenChange={setConfirmUnlink}
        title={t("abha_unlink_title")}
        description={t("abha_unlink_description", {
          abha_number: linked?.abha_number,
          name: patient.name,
        })}
        confirmText={t("abha_unlink")}
        variant="destructive"
        disabled={isUnlinking}
        onConfirm={() => unlink(undefined)}
      />
    </div>
  );
}

