    method: HttpMethod.POST,
    TBody: Type<AbhaCreateSendOtpRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  verifyOtp: {
    path: "/api/v1/abdm/abha/verify_otp/",
    method: HttpMethod.POST,
    TBody: Type<AbhaVerifyOtpRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  resendOtp: {
    path: "/api/v1/abdm/abha/resend_otp/",
    method: HttpMethod.POST,
    TBody: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  selectAccount: {
    path: "/api/v1/abdm/abha/select_account/",
    method: HttpMethod.POST,
    TBody: Type<AbhaSelectAccountRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  skipMobileOtp: {
    path: "/api/v1/abdm/abha/create/skip_mobile_otp/",
    method: HttpMethod.POST,
    TBody: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaJourney>(),
  },
  addressSuggestions: {
    path: "/api/v1/abdm/abha/create/address_suggestions/",
    method: HttpMethod.GET,
    TQuery: Type<AbhaTransactionRequest>(),
    TRes: Type<AbhaAddressSuggestions>(),
  },
  createAddress: {
    path: "/api/v1/abdm/abha/create/address/",
    method: HttpMethod.POST,
    TBody: Type<AbhaCreateAddressRequest>(),
    TRes: Type<AbhaJourney>(),
  },
