import { faker } from "@faker-js/faker";
import type { Page, Route } from "@playwright/test";

/**
 * Fixtures and route mocks for the ABHA (ABDM Milestone 1) specs.
 *
 * The shapes follow CARE's ABHA HTTP contract: the journey endpoints under
 * `/api/v1/abdm/abha/` and the patient endpoints under
 * `/api/v1/patient/{id}/abha/`. Every one of those calls is answered here, so
 * the specs never reach ABDM. Update this file when the contract changes.
 */

/** The ABHA UI exists only in builds made with `REACT_ENABLE_ABDM=true` */
export const isAbdmEnabled = () => process.env.REACT_ENABLE_ABDM === "true";

export const ABDM_DISABLED_REASON =
  "ABHA is behind REACT_ENABLE_ABDM; build and run with REACT_ENABLE_ABDM=true";

/** The Aadhaar consent (version 1.4), exactly as the patient must see it */
export const ABHA_CONSENT_TERMS = "__ABHA_CONSENT_TERMS__";

export const ABHA_CONSENT = { accepted: true, version: "1.4" } as const;

export const TRANSACTION_ID = "6f1c2a4e-5b7d-4c8e-9a0b-1c2d3e4f5a6b";

type Gender = "male" | "female" | "transgender" | "non_binary";
type AuthMethod = "aadhaar_otp" | "mobile_otp";
type IdentifierType = "mobile" | "aadhaar" | "abha_number" | "abha_address";
type ErrorField =
  | "otp"
  | "identifier"
  | "aadhaar"
  | "mobile"
  | "abha_address"
  | "abha_number";

export interface LinkedPatientFixture {
  partial_id: string;
  name: string;
  gender: Gender | null;
  year_of_birth: number | null;
  phone_number: string | null;
  is_current_patient: boolean;
}

export interface OtpFixture {
  purpose: "login" | "aadhaar" | "mobile";
  sent_to: string | null;
  message: string | null;
  resend_available_at: string;
  resends_remaining: number;
  skippable: boolean;
}

export interface AccountFixture {
  abha_number: string;
  preferred_abha_address: string | null;
  name: string;
  gender: Gender | null;
  date_of_birth: string | null;
  year_of_birth: number | null;
  photo: string | null;
  kyc_verified: boolean;
  status: string | null;
  linked_patient: LinkedPatientFixture | null;
}

export interface ProfileFixture {
  abha_number: string | null;
  abha_address: string | null;
  abha_addresses: string[];
  name: string;
  first_name: string;
  middle_name: string;
  last_name: string;
  gender: Gender | null;
  abdm_gender: "M" | "F" | "O" | "T" | null;
  date_of_birth: string | null;
  year_of_birth: number | null;
  mobile: string | null;
  email: string | null;
  address: string | null;
  pincode: string | null;
  state_name: string | null;
  district_name: string | null;
  photo: string | null;
  kyc_verified: boolean;
  status: string | null;
  is_new: boolean;
  auth_method: AuthMethod | null;
}

export interface JourneyFixture {
  transaction_id: string;
  flow: "login" | "create";
  status:
    | "confirm_identity"
    | "otp_sent"
    | "no_account"
    | "select_account"
    | "select_address"
    | "verified";
  identifier_type: IdentifierType;
  masked_identifier: string | null;
  auth_methods: AuthMethod[];
  search_result: {
    abha_address: string;
    full_name: string;
    masked_mobile: string | null;
  } | null;
  otp: OtpFixture | null;
  accounts: AccountFixture[] | null;
  profile: ProfileFixture | null;
  linked_patient: LinkedPatientFixture | null;
  consent_recorded: boolean;
  message: string | null;
}

export interface PatientAbhaLinkedFixture {
  linked: true;
  abha_number: string;
  abha_address: string | null;
  kyc_verified: boolean | null;
  auth_method: AuthMethod | null;
  linked_on: string;
  linked_by: {
    id: string;
    username: string;
    first_name: string;
    last_name: string;
  } | null;
}

export type PatientAbhaFixture = PatientAbhaLinkedFixture | { linked: false };

export const secondsFromNow = (seconds: number) =>
  new Date(Date.now() + seconds * 1000).toISOString();

/** A valid Indian mobile number without +91, unique per call */
export const randomMobile = () =>
  `${faker.helpers.arrayElement([7, 8, 9])}${faker.string.numeric(9)}`;

export const maskMobile = (mobile: string) => `******${mobile.slice(-4)}`;

export function buildOtp(overrides: Partial<OtpFixture> = {}): OtpFixture {
  return {
    purpose: "login",
    sent_to: "******3210",
    message: null,
    resend_available_at: secondsFromNow(60),
    resends_remaining: 2,
    skippable: false,
    ...overrides,
  };
}

export function buildLinkedPatient(
  overrides: Partial<LinkedPatientFixture> = {},
): LinkedPatientFixture {
  return {
    partial_id: "ab12c",
    name: "Suresh Kumar",
    gender: "male",
    year_of_birth: 1985,
    phone_number: "+919812345678",
    is_current_patient: false,
    ...overrides,
  };
}

export function buildProfile(
  overrides: Partial<ProfileFixture> = {},
): ProfileFixture {
  return {
    abha_number: "91-1234-5678-9012",
    abha_address: "ramesh.kumar@sbx",
    abha_addresses: ["ramesh.kumar@sbx"],
    name: "Ramesh Kumar",
    first_name: "Ramesh",
    middle_name: "",
    last_name: "Kumar",
    gender: "male",
    abdm_gender: "M",
    date_of_birth: "1990-01-31",
    year_of_birth: 1990,
    mobile: "9876543210",
    email: null,
    address: "12, MG Road, Bengaluru",
    pincode: "560001",
    state_name: "KARNATAKA",
    district_name: "BENGALURU URBAN",
    photo: null,
    kyc_verified: true,
    status: "ACTIVE",
    is_new: false,
    auth_method: "mobile_otp",
    ...overrides,
  };
}

export function buildAccount(
  overrides: Partial<AccountFixture> = {},
): AccountFixture {
  return {
    abha_number: "91-1234-5678-9012",
    preferred_abha_address: "ramesh.kumar@sbx",
    name: "Ramesh Kumar",
    gender: "male",
    date_of_birth: "1990-01-31",
    year_of_birth: 1990,
    photo: null,
    kyc_verified: true,
    status: "ACTIVE",
    linked_patient: null,
    ...overrides,
  };
}

export function buildJourney(
  overrides: Partial<JourneyFixture> = {},
): JourneyFixture {
  return {
    transaction_id: TRANSACTION_ID,
    flow: "login",
    status: "otp_sent",
    identifier_type: "mobile",
    masked_identifier: "******3210",
    auth_methods: ["mobile_otp"],
    search_result: null,
    otp: null,
    accounts: null,
    profile: null,
    linked_patient: null,
    consent_recorded: false,
    message: null,
    ...overrides,
  };
}

export const otpSentJourney = (
  otp: Partial<OtpFixture> = {},
  journey: Partial<JourneyFixture> = {},
) => buildJourney({ status: "otp_sent", otp: buildOtp(otp), ...journey });

export const verifiedJourney = (
  profile: Partial<ProfileFixture> = {},
  journey: Partial<JourneyFixture> = {},
) =>
  buildJourney({
    status: "verified",
    profile: buildProfile(profile),
    ...journey,
  });

export function buildPatientAbha(
  overrides: Partial<PatientAbhaLinkedFixture> = {},
): PatientAbhaLinkedFixture {
  return {
    linked: true,
    abha_number: "91-1234-5678-9012",
    abha_address: "ramesh.kumar@sbx",
    kyc_verified: true,
    auth_method: "mobile_otp",
    linked_on: new Date().toISOString(),
    linked_by: {
      id: "5e0a6b4c-0d6c-4b8e-8f3a-2a1b3c4d5e6f",
      username: "care-doctor",
      first_name: "Care",
      last_name: "Doctor",
    },
    ...overrides,
  };
}

/** A 1×1 PNG standing in for the ABHA card */
const CARD_PNG = Buffer.from(
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",
  "base64",
);

export interface AbhaMockResponse {
  status?: number;
  json?: unknown;
  body?: Buffer;
  contentType?: string;
}

export const respond = (json: unknown, status = 200): AbhaMockResponse => ({
  status,
  json,
});

export const cardResponse = (): AbhaMockResponse => ({
  body: CARD_PNG,
  contentType: "image/png",
});

/** An ABHA error in the contract's format */
export const abhaError = (
  status: number,
  code: string,
  msg: string,
  field: ErrorField | null = null,
  extras: {
    retry_after?: number;
    linked_patient?: LinkedPatientFixture;
  } = {},
): AbhaMockResponse =>
  respond({ errors: [{ type: "abdm_error", code, msg, field, ...extras }] }, status);

/** HTTP method of each mocked endpoint; a call with another method is unmocked */
const ENDPOINT_METHODS = {
  search: "POST",
  sendOtp: "POST",
  createSendOtp: "POST",
  verifyOtp: "POST",
  resendOtp: "POST",
  selectAccount: "POST",
  skipMobileOtp: "POST",
  addressSuggestions: "GET",
  createAddress: "POST",
  card: "GET",
  link: "POST",
  getPatientAbha: "GET",
  unlinkPatientAbha: "POST",
} as const;

export type AbhaEndpoint = keyof typeof ENDPOINT_METHODS;

const JOURNEY_PATHS: Record<string, AbhaEndpoint> = {
  "search/": "search",
  "send_otp/": "sendOtp",
  "create/send_otp/": "createSendOtp",
  "verify_otp/": "verifyOtp",
  "resend_otp/": "resendOtp",
  "select_account/": "selectAccount",
  "create/skip_mobile_otp/": "skipMobileOtp",
  "create/address_suggestions/": "addressSuggestions",
  "create/address/": "createAddress",
  "card/": "card",
  "link/": "link",
};

const getEndpoint = (url: URL): AbhaEndpoint | undefined => {
  const journey = url.pathname.match(/\/api\/v1\/abdm\/abha\/(.*)$/);
  if (journey) {
    return JOURNEY_PATHS[journey[1]];
  }
  const patient = url.pathname.match(
    /\/api\/v1\/patient\/[^/]+\/abha\/(unlink\/)?$/,
  );
  if (patient) {
    return patient[1] ? "unlinkPatientAbha" : "getPatientAbha";
  }
  return undefined;
};

export interface AbhaRequest {
  endpoint: AbhaEndpoint;
  url: URL;
  body: Record<string, unknown> | null;
  /** 1 for the first call to this endpoint, 2 for the second, and so on */
  call: number;
}

export type AbhaHandlers = Partial<
  Record<
    AbhaEndpoint,
    (request: AbhaRequest) => AbhaMockResponse | Promise<AbhaMockResponse>
  >
>;

export interface AbhaMock {
  /** Every mocked call, in order */
  requests: AbhaRequest[];
  calls: (endpoint: AbhaEndpoint) => AbhaRequest[];
}

const unmockedCalls = new WeakMap<Page, string[]>();

/** ABHA calls that had no handler on this page; a spec should end with none */
export const getUnmockedAbhaCalls = (page: Page) =>
  unmockedCalls.get(page) ?? [];

/**
 * Answers every ABHA call on the page from `handlers`, recording each call.
 * A call without a handler gets a 500 and is listed by `getUnmockedAbhaCalls`.
 */
export async function mockAbha(
  page: Page,
  handlers: AbhaHandlers,
): Promise<AbhaMock> {
  const requests: AbhaRequest[] = [];
  const unmocked: string[] = [];
  unmockedCalls.set(page, unmocked);

  const handle = async (route: Route) => {
    const request = route.request();
    const url = new URL(request.url());
    const endpoint = getEndpoint(url);
    const handler =
      endpoint && request.method() === ENDPOINT_METHODS[endpoint]
        ? handlers[endpoint]
        : undefined;

    if (!endpoint || !handler) {
      const call = `${request.method()} ${url.pathname}${url.search}`;
      unmocked.push(call);
      await route.fulfill(
        abhaErrorFulfill(`No mock for ${call}`, "unmocked_abha_call"),
      );
      return;
    }

    let body: Record<string, unknown> | null = null;
    try {
      body = request.postDataJSON();
    } catch {
      body = null;
    }
    const recorded: AbhaRequest = {
      endpoint,
      url,
      body,
      call: requests.filter((r) => r.endpoint === endpoint).length + 1,
    };
    requests.push(recorded);

    const response = await handler(recorded);
    await route.fulfill(
      response.body
        ? {
            status: response.status ?? 200,
            body: response.body,
            contentType: response.contentType ?? "application/octet-stream",
          }
        : { status: response.status ?? 200, json: response.json ?? {} },
    );
  };

  await page.route("**/api/v1/abdm/abha/**", handle);
  await page.route("**/api/v1/patient/*/abha/**", handle);

  return {
    requests,
    calls: (endpoint) => requests.filter((r) => r.endpoint === endpoint),
  };
}

const abhaErrorFulfill = (msg: string, code: string) => ({
  status: 500,
  json: { errors: [{ type: "abdm_error", code, msg, field: null }] },
});

result.output:
import { useMutation } from "@tanstack/react-query";
import { RotateCcwIcon } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import {
  AbhaAuthMethod,
  AbhaIdentifierType,
  AbhaJourney as AbhaJourneyResponse,
} from "@/types/abdm/abha";

import { AbhaAccountStep } from "./AbhaAccountStep";
import { AbhaAddressStep } from "./AbhaAddressStep";
import { AbhaConfirmIdentityStep } from "./AbhaConfirmIdentityStep";
import {
  AbhaCreateAadhaarInput,
  AbhaCreateAadhaarStep,
} from "./AbhaCreateAadhaarStep";
import { AbhaIdentifyInput, AbhaIdentifyStep } from "./AbhaIdentifyStep";
import { AbhaJourneyAction, runAbhaJourneyAction } from "./abhaJourneyActions";
import { AbhaMethodStep } from "./AbhaMethodStep";
import { AbhaNoAccountStep } from "./AbhaNoAccountStep";
import { AbhaOtpMobile, AbhaOtpStep } from "./AbhaOtpStep";
import { AbhaResultStep } from "./AbhaResultStep";
import { AbhaJourneyMode, AbhaJourneyResult, AbhaLinkTarget } from "./types";
import { AbhaFacts, useAbhaFacts } from "./useAbhaFacts";
import {
  ABHA_CONSENT,
  ABHA_RESTART_CODES,
  AbhaUiError,
  AbhaUiErrorCode,
  maskAadhaar,
  parseAbhaError,
} from "./utils";

/** Screens that are not a journey status of their own */
type AbhaLocalView = "identify" | "method" | "create_aadhaar";

type AbhaStepKind =
  | AbhaLocalView
  | "confirm_identity"
  | "otp"
  | "no_account"
  | "select_account"
  | "select_address"
  | "verified";

const ALL_AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

/** Errors that each step shows beside its own inputs; the rest go in a banner */
const INLINE_ERRORS: Partial<
  Record<AbhaStepKind, { fields: string[]; codes: AbhaUiErrorCode[] }>
> = {
  identify: {
    fields: ["identifier", "mobile", "aadhaar", "abha_number", "abha_address"],
    codes: [
      "invalid_mobile",
      "invalid_aadhaar",
      "invalid_abha_number",
      "invalid_abha_address",
      "consent_required",
    ],
  },
  otp: {
    fields: ["otp", "mobile"],
    codes: [
      "invalid_mobile",
      "resend_cooldown",
      "resend_limit_reached",
      "rate_limited",
    ],
  },
  create_aadhaar: {
    fields: ["aadhaar"],
    codes: ["invalid_aadhaar", "consent_required"],
  },
  select_address: {
    fields: ["abha_address"],
    codes: ["invalid_abha_address"],
  },
};

const isInlineError = (step: AbhaStepKind, error: AbhaUiError) => {
  const inline = INLINE_ERRORS[step];
  return (
    !!inline &&
    ((!!error.field && inline.fields.includes(error.field)) ||
      inline.codes.includes(error.code))
  );
};

const getStepKind = (
  view: AbhaLocalView | "journey",
  journey: AbhaJourneyResponse | null,
): AbhaStepKind => {
  if (view !== "journey" || !journey) {
    return view === "journey" ? "identify" : view;
  }
  return journey.status === "otp_sent" ? "otp" : journey.status;
};

/**
 * The ABHA journey (contract §6.3). One component for the three entry points:
 * registration, linking an existing patient and re-verifying a linked ABHA.
 * Each step talks to CARE only; CARE holds the ABDM transaction.
 */
export function AbhaJourney({
  mode,
  facilityId,
  patientId,
  initialFacts,
  linkTarget,
  onComplete,
  onExit,
}: {
  mode: AbhaJourneyMode;
  facilityId?: string;
  /** Required in `link` and `reverify` modes */
  patientId?: string;
  initialFacts: AbhaFacts;
  linkTarget?: AbhaLinkTarget;
  onComplete: (result: AbhaJourneyResult) => void;
  /** "Continue without ABHA" in register mode, "Cancel" otherwise */
  onExit: (facts: AbhaFacts) => void;
}) {
  const { t } = useTranslation();
  const { facts, tried, setFact, recordConsent, addTried, forgetSource } =
    useAbhaFacts(initialFacts);

  const initialView: AbhaLocalView =
    mode === "reverify" ? "method" : "identify";
  const [view, setView] = useState<AbhaLocalView | "journey">(initialView);
  const [journey, setJourney] = useState<AbhaJourneyResponse | null>(null);
  const [error, setError] = useState<AbhaUiError | null>(null);
  const [identifyType, setIdentifyType] =
    useState<AbhaIdentifierType>("mobile");

  // Journey-starting calls carry the context; later calls only the transaction
  const context = {
    facility: facilityId,
    patient: mode === "register" ? undefined : patientId,
  };

  const {
    mutate: run,
    isPending,
    variables,
    reset,
  } = useMutation({
    mutationFn: runAbhaJourneyAction,
    onMutate: () => setError(null),
    onSuccess: (next) => {
      setJourney(next);
      setView("journey");
      if (next.status === "no_account") {
        addTried({ route: next.identifier_type, reason: "no_account" });
      }
      if (next.status === "verified" && next.profile) {
        // Write-once: facts the desk already gave keep their value and source
        if (next.profile.abha_number) {
          setFact("abhaNumber", next.profile.abha_number, "abha_profile");
        }
        if (next.profile.abha_address) {
          setFact("abhaAddress", next.profile.abha_address, "abha_profile");
        }
        if (next.profile.mobile) {
          setFact("mobile", next.profile.mobile, "abha_profile");
        }
      }
    },
    onError: (failure, action: AbhaJourneyAction) => {
      const parsed = parseAbhaError(failure, t);
      setError(parsed);
      if (action.type === "search" && parsed.code === "ABDM-1211") {
        addTried({ route: "abha_address", reason: "not_found" });
      }
    },
  });

  const pendingAction = isPending ? variables?.type : undefined;
  const stepKind = getStepKind(view, journey);
  const stepKey =
    stepKind === "otp" ? `otp:${journey?.otp?.purpose ?? ""}` : stepKind;
  const inlineError =
    error && isInlineError(stepKind, error) ? error : undefined;
  const bannerError = error && !inlineError ? error : undefined;
  const mustRestart =
    !!bannerError && ABHA_RESTART_CODES.includes(bannerError.code);

  // Move focus to the new step's heading (not on the first render)
  const containerRef = useRef<HTMLDivElement>(null);
  const previousStepKey = useRef(stepKey);
  useEffect(() => {
    if (previousStepKey.current === stepKey) {
      return;
    }
    previousStepKey.current = stepKey;
    containerRef.current
      ?.querySelector<HTMLElement>("[data-abha-step-heading]")
      ?.focus();
  }, [stepKey]);

  const clearError = () => setError(null);

  const showLocalError = (message: string) =>
    setError({ code: "unknown", message, receivedAt: Date.now() });

  const restart = () => {
    reset();
    setError(null);
    setJourney(null);
    forgetSource("abha_profile");
    setView(initialView);
  };

  const backToIdentify = () => {
    reset();
    setError(null);
    setJourney(null);
    setView("identify");
  };

  const handleIdentify = ({ type, value, authMethod }: AbhaIdentifyInput) => {
    setIdentifyType(type);
    switch (type) {
      case "mobile":
        setFact("mobile", value, "desk", { override: true });
        break;
      case "aadhaar":
        setFact("aadhaarMasked", maskAadhaar(value), "desk", {
          override: true,
        });
        recordConsent();
        break;
      case "abha_number":
        setFact("abhaNumber", value, "desk", { override: true });
        break;
      case "abha_address":
        setFact("abhaAddress", value, "desk", { override: true });
        break;
    }

    if (type === "abha_address") {
      run({ type: "search", body: { abha_address: value, ...context } });
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: type,
        identifier: value,
        auth_method: authMethod,
        consent: type === "aadhaar" ? ABHA_CONSENT : undefined,
        ...context,
      },
    });
  };

  const sendAddressOtp = (authMethod: AbhaAuthMethod) => {
    if (!journey) {
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_address",
        transaction_id: journey.transaction_id,
        auth_method: authMethod,
      },
    });
  };

  const handleConfirmIdentity = () => {
    const methods = journey?.auth_methods ?? [];
    if (methods.length > 1) {
      setError(null);
      setView("method");
    } else if (methods.length === 1) {
      sendAddressOtp(methods[0]);
    } else {
      showLocalError(t("abha_error_no_auth_methods"));
    }
  };

  const handleMethod = (authMethod: AbhaAuthMethod) => {
    if (journey?.status === "confirm_identity") {
      sendAddressOtp(authMethod);
      return;
    }
    // Re-verify the ABHA number held on the patient record
    if (!facts.abhaNumber) {
      showLocalError(t("abha_error_invalid_abha_number"));
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_number",
        identifier: facts.abhaNumber.value,
        auth_method: authMethod,
        ...context,
      },
    });
  };

  const startCreate = (aadhaar?: string) => {
    if (!journey) {
      return;
    }
    run({
      type: "create_send_otp",
      body: {
        transaction_id: journey.transaction_id,
        aadhaar,
        consent: journey.consent_recorded ? undefined : ABHA_CONSENT,
      },
    });
  };

  const handleNoAccountCreate = () => {
    if (!journey) {
      return;
    }
    // Ask only for what the journey does not hold
    const needsAadhaar = journey.identifier_type !== "aadhaar";
    const needsConsent = !journey.consent_recorded && !facts.consent;
    if (needsAadhaar || needsConsent) {
      setError(null);
      setView("create_aadhaar");
      return;
    }
    startCreate();
  };

  const handleCreateAadhaar = ({ aadhaar }: AbhaCreateAadhaarInput) => {
    if (aadhaar) {
      setFact("aadhaarMasked", maskAadhaar(aadhaar), "desk", {
        override: true,
      });
    }
    recordConsent();
    startCreate(aadhaar);
  };

  const handleVerifyOtp = (
    otp: string,
    mobile: AbhaOtpMobile | undefined,
    onError: () => void,
  ) => {
    if (!journey) {
      return;
    }
    if (mobile) {
      setFact("mobile", mobile.value, "desk", { override: mobile.edited });
    }
    run(
      {
        type: "verify_otp",
        body: {
          transaction_id: journey.transaction_id,
          otp,
          mobile: mobile?.value,
        },
      },
      { onError },
    );
  };

  const renderStep = () => {
    switch (stepKind) {
      case "identify":
        return (
          <AbhaIdentifyStep
            facts={facts}
            tried={tried}
            initialType={identifyType}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={handleIdentify}
            onClearError={clearError}
          />
        );
      case "method": {
        const fromSearch = journey?.status === "confirm_identity";
        return (
          <AbhaMethodStep
            methods={fromSearch ? journey.auth_methods : ALL_AUTH_METHODS}
            identifierLabel={fromSearch ? t("abha_address") : t("abha_number")}
            identifier={
              fromSearch
                ? (journey.search_result?.abha_address ??
                  journey.masked_identifier ??
                  undefined)
                : facts.abhaNumber
            }
            isPending={isPending}
            onSubmit={handleMethod}
          />
        );
      }
      case "create_aadhaar":
        return (
          journey && (
            <AbhaCreateAadhaarStep
              facts={facts}
              needsAadhaar={journey.identifier_type !== "aadhaar"}
              needsConsent={!journey.consent_recorded && !facts.consent}
              error={inlineError?.message}
              isPending={isPending}
              onSubmit={handleCreateAadhaar}
              onClearError={clearError}
            />
          )
        );
    }

    if (!journey) {
      return null;
    }
    const transactionId = journey.transaction_id;

    switch (stepKind) {
      case "confirm_identity":
        return (
          <AbhaConfirmIdentityStep
            searchResult={journey.search_result}
            isPending={isPending}
            onConfirm={handleConfirmIdentity}
            onReject={backToIdentify}
          />
        );
      case "otp":
        return (
          journey.otp && (
            <AbhaOtpStep
              key={`${transactionId}-${journey.otp.purpose}`}
              otp={journey.otp}
              facts={facts}
              error={inlineError ?? null}
              pendingAction={pendingAction}
              onVerify={handleVerifyOtp}
              onResend={() =>
                run({
                  type: "resend_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onSkip={() =>
                run({
                  type: "skip_mobile_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onClearError={clearError}
            />
          )
        );
      case "no_account":
        return (
          <AbhaNoAccountStep
            journey={journey}
            isPending={isPending}
            onCreate={handleNoAccountCreate}
            onTryAnother={backToIdentify}
          />
        );
      case "select_account":
        return (
          <AbhaAccountStep
            accounts={journey.accounts ?? []}
            isPending={isPending}
            onSelect={(abhaNumber) =>
              run({
                type: "select_account",
                body: {
                  transaction_id: transactionId,
                  abha_number: abhaNumber,
                },
              })
            }
          />
        );
      case "select_address":
        return (
          <AbhaAddressStep
            key={transactionId}
            transactionId={transactionId}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={(address) =>
              run({
                type: "create_address",
                body: { transaction_id: transactionId, abha_address: address },
              })
            }
            onClearError={clearError}
          />
        );
      case "verified":
        return (
          <AbhaResultStep
            mode={mode}
            journey={journey}
            facilityId={facilityId}
            patientId={patientId}
            linkTarget={linkTarget}
            onContinue={() => onComplete({ journey, facts })}
            onLinked={(patientAbha) =>
              onComplete({ journey, facts, patientAbha })
            }
          />
        );
    }
  };

  return (
    <div
      ref={containerRef}
      className="flex flex-col gap-5"
      data-testid="abha-journey"
      data-step={stepKey}
    >
      {renderStep()}

      {bannerError && (
        <Alert variant="destructive" data-testid="abha-journey-error">
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{bannerError.message}</span>
            {mustRestart && (
              <Button variant="outline" size="sm" onClick={restart}>
                <RotateCcwIcon />
                {t("abha_start_again")}
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-gray-200 pt-4">
        <div>
          {stepKind !== initialView && !mustRestart && (
            <Button
              variant="ghost"
              size="sm"
              disabled={isPending}
              onClick={restart}
              data-testid="abha-start-again"
            >
              <RotateCcwIcon />
              {t("abha_start_again")}
            </Button>
          )}
        </div>
        <Button
          variant="outline"
          onClick={() => onExit(facts)}
          data-testid="abha-exit"
        >
          {mode === "register" ? t("abha_continue_without") : t("cancel")}
        </Button>
      </div>
    </div>
  );
}

import { Loader2Icon } from "lucide-react";
import { SyntheticEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import RadioInput from "@/components/ui/RadioInput";

import { AbhaAuthMethod, AbhaIdentifierType } from "@/types/abdm/abha";

import { AbhaConsentPanel } from "./AbhaConsentPanel";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFact, AbhaFacts, AbhaTriedRoute } from "./useAbhaFacts";
import {
  ABHA_AUTH_METHOD_LABELS,
  ABHA_COUNTRY_CODE,
  ABHA_IDENTIFIER_LABELS,
  isValidAadhaar,
  isValidAbhaAddressForLogin,
  isValidMobile,
  normalizeAadhaar,
  normalizeAbhaNumber,
  normalizeMobile,
} from "./utils";

export interface AbhaIdentifyInput {
  type: AbhaIdentifierType;
  /** Normalised value, as sent to CARE */
  value: string;
  authMethod?: AbhaAuthMethod;
}

const IDENTIFIER_TYPES: AbhaIdentifierType[] = [
  "mobile",
  "aadhaar",
  "abha_number",
  "abha_address",
];

const AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

const PLACEHOLDERS: Record<AbhaIdentifierType, string> = {
  mobile: "abha_identifier_placeholder__mobile",
  aadhaar: "abha_identifier_placeholder__aadhaar",
  abha_number: "abha_identifier_placeholder__abha_number",
  abha_address: "abha_identifier_placeholder__abha_address",
};

/** Local validation (contract §5.1); nothing is sent when it fails */
const validate = (
  type: AbhaIdentifierType,
  value: string,
): { value: string } | { error: string } => {
  switch (type) {
    case "mobile":
      return isValidMobile(value)
        ? { value: normalizeMobile(value) }
        : { error: "abha_error_invalid_mobile" };
    case "aadhaar":
      return isValidAadhaar(value)
        ? { value: normalizeAadhaar(value) }
        : { error: "abha_error_invalid_aadhaar" };
    case "abha_number": {
      const abhaNumber = normalizeAbhaNumber(value);
      return abhaNumber
        ? { value: abhaNumber }
        : { error: "abha_error_invalid_abha_number" };
    }
    case "abha_address":
      return isValidAbhaAddressForLogin(value)
        ? { value: value.trim() }
        : { error: "abha_error_invalid_abha_address" };
  }
};

/**
 * Identify (screen 1): one screen for finding or creating an ABHA. It never
 * asks "login or create?"; creation is offered when no ABHA is found.
 */
export function AbhaIdentifyStep({
  facts,
  tried,
  initialType,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  facts: AbhaFacts;
  tried: AbhaTriedRoute[];
  initialType: AbhaIdentifierType;
  /** Server error for the identifier, shown under the input */
  error?: string;
  isPending: boolean;
  onSubmit: (input: AbhaIdentifyInput) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const inputId = `${id}-identifier`;
  const errorId = `${id}-error`;

  const [type, setType] = useState(initialType);
  const [values, setValues] = useState<Record<AbhaIdentifierType, string>>(
    () => ({
      mobile: facts.mobile?.value ?? "",
      aadhaar: "",
      abha_number: facts.abhaNumber?.value ?? "",
      abha_address: facts.abhaAddress?.value ?? "",
    }),
  );
  const [consented, setConsented] = useState(!!facts.consent);
  const [authMethod, setAuthMethod] = useState<AbhaAuthMethod>("aadhaar_otp");
  const [localError, setLocalError] = useState<string>();

  const value = values[type];
  const heldFacts: Record<AbhaIdentifierType, AbhaFact<string> | undefined> = {
    mobile: facts.mobile,
    aadhaar: undefined,
    abha_number: facts.abhaNumber,
    abha_address: facts.abhaAddress,
  };
  const heldFact = heldFacts[type];
  const needsConsent = type === "aadhaar" && !consented;
  const errorMessage = localError ?? error;

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleSubmit = (event: SyntheticEvent) => {
    event.preventDefault();
    if (needsConsent || isPending) {
      return;
    }
    const result = validate(type, value);
    if ("error" in result) {
      setLocalError(t(result.error));
      return;
    }
    onSubmit({
      type,
      value: result.value,
      authMethod: type === "abha_number" ? authMethod : undefined,
    });
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-identify-step"
    >
      <AbhaStepHeading
        title={t("abha_identify_title")}
        description={t("abha_identify_description")}
      />

      <div className="flex flex-col gap-2">
        <Label id={`${id}-type-label`}>{t("abha_identify_with")}</Label>
        <RadioInput
          required
          aria-labelledby={`${id}-type-label`}
          value={type}
          disabled={isPending}
          onValueChange={(next) => {
            setType(next as AbhaIdentifierType);
            clearErrors();
          }}
          options={IDENTIFIER_TYPES.map((option) => ({
            value: option,
            label: t(ABHA_IDENTIFIER_LABELS[option]),
          }))}
        />
      </div>

      {type === "aadhaar" && (
        <AbhaConsentPanel checked={consented} onCheckedChange={setConsented} />
      )}

      <div className="flex flex-col gap-2">
        <Label htmlFor={inputId}>{t(ABHA_IDENTIFIER_LABELS[type])}</Label>
        <div className="flex items-center gap-2">
          {type === "mobile" && (
            <span className="rounded-md border border-gray-200 bg-gray-50 px-3 py-1.5 text-sm text-gray-700">
              {ABHA_COUNTRY_CODE}
            </span>
          )}
          <Input
            key={type}
            id={inputId}
            value={value}
            disabled={isPending || needsConsent}
            placeholder={t(PLACEHOLDERS[type])}
            autoComplete="off"
            inputMode={
              type === "abha_address" || type === "abha_number"
                ? "text"
                : "numeric"
            }
            aria-invalid={!!errorMessage}
            aria-describedby={errorMessage ? errorId : undefined}
            data-testid="abha-identifier-input"
            onChange={(event) => {
              setValues((current) => ({
                ...current,
                [type]: event.target.value,
              }));
              clearErrors();
            }}
          />
        </div>
        {heldFact && heldFact.value === value && (
          <AbhaProvenanceBadge source={heldFact.source} />
        )}
        <AbhaFieldError id={errorId} message={errorMessage} />
      </div>

      {type === "abha_number" && (
        <div className="flex flex-col gap-2">
          <Label id={`${id}-method-label`}>{t("abha_auth_method")}</Label>
          <RadioInput
            required
            aria-labelledby={`${id}-method-label`}
            value={authMethod}
            disabled={isPending}
            onValueChange={(next) => setAuthMethod(next as AbhaAuthMethod)}
            options={AUTH_METHODS.map((method) => ({
              value: method,
              label: t(ABHA_AUTH_METHOD_LABELS[method]),
            }))}
          />
        </div>
      )}

      {tried.length > 0 && (
        <div
          className="rounded-md bg-gray-50 p-3 text-sm text-gray-700"
          data-testid="abha-tried-routes"
        >
          <p className="font-medium">{t("abha_already_tried")}</p>
          <ul className="list-inside list-disc">
            {tried.map((route) => (
              <li key={`${route.route}-${route.reason}`}>
                {t(`abha_tried__${route.reason}`, {
                  identifier: t(ABHA_IDENTIFIER_LABELS[route.route]),
                })}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="flex justify-end">
        <Button
          type="submit"
          variant="primary"
          disabled={isPending || needsConsent}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {type === "abha_address" ? t("search") : t("send_otp")}
        </Button>
      </div>
    </form>
  );
}

import { REGEXP_ONLY_DIGITS } from "input-otp";
import { Loader2Icon } from "lucide-react";
import { SyntheticEvent, useEffect, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";

import { AbhaOtp } from "@/types/abdm/abha";

import { AbhaJourneyActionType } from "./abhaJourneyActions";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFacts } from "./useAbhaFacts";
import {
  ABHA_COUNTRY_CODE,
  ABHA_OTP_LENGTH,
  AbhaUiError,
  AbhaUiErrorCode,
  isValidMobile,
  normalizeMobile,
} from "./utils";

export interface AbhaOtpMobile {
  /** 10 digits, without +91 */
  value: string;
  /** The desk changed a mobile the journey already held */
  edited: boolean;
}

const RESEND_ERROR_CODES: AbhaUiErrorCode[] = [
  "resend_cooldown",
  "resend_limit_reached",
  "rate_limited",
];

/**
 * OTP (screen 3), for every purpose. The identifier is never asked again
 * here; for the Aadhaar OTP during creation, the communication mobile is
 * asked once if the journey holds none.
 */
export function AbhaOtpStep({
  otp,
  facts,
  error,
  pendingAction,
  onVerify,
  onResend,
  onSkip,
  onClearError,
}: {
  otp: AbhaOtp;
  facts: AbhaFacts;
  /** Inline error for this step (OTP, mobile or resend) */
  error: AbhaUiError | null;
  pendingAction?: AbhaJourneyActionType;
  onVerify: (
    code: string,
    mobile: AbhaOtpMobile | undefined,
    onError: () => void,
  ) => void;
  onResend: () => void;
  onSkip: () => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const heldMobile = facts.mobile;

  const [code, setCode] = useState("");
  const [editingMobile, setEditingMobile] = useState(false);
  const [mobile, setMobile] = useState(heldMobile?.value ?? "");
  const [localError, setLocalError] = useState<{
    field: "otp" | "mobile";
    message: string;
  }>();
  const [now, setNow] = useState(() => Date.now());

  const isPending = !!pendingAction;
  const asksMobile = otp.purpose === "aadhaar";
  const showMobileInput = asksMobile && (!heldMobile || editingMobile);

  // Every server error lands in one slot; the OTP slot takes the rest
  const errorSlot = !error
    ? undefined
    : RESEND_ERROR_CODES.includes(error.code)
      ? "resend"
      : asksMobile &&
          (error.field === "mobile" || error.code === "invalid_mobile")
        ? "mobile"
        : "otp";
  const fieldError = (field: "otp" | "mobile") =>
    localError?.field === field
      ? localError.message
      : errorSlot === field
        ? error?.message
        : undefined;
  const otpError = fieldError("otp");
  const mobileError = fieldError("mobile");
  const resendError = errorSlot === "resend" ? error?.message : undefined;

  // The countdown follows `resend_available_at`, or `retry_after` from a 429
  const cooldownUntil = Math.max(
    Date.parse(otp.resend_available_at) || 0,
    error?.code === "resend_cooldown" && error.retryAfter
      ? error.receivedAt + error.retryAfter * 1000
      : 0,
  );
  const secondsLeft = Math.max(0, Math.ceil((cooldownUntil - now) / 1000));
  const isCountingDown = secondsLeft > 0;
  const resendsExhausted =
    otp.resends_remaining <= 0 || error?.code === "resend_limit_reached";

  useEffect(() => {
    if (!isCountingDown) {
      return;
    }
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [isCountingDown]);

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleVerify = (event: SyntheticEvent) => {
    event.preventDefault();
    if (isPending) {
      return;
    }
    if (code.length !== ABHA_OTP_LENGTH) {
      setLocalError({ field: "otp", message: t("abha_error_otp_length") });
      return;
    }

    let otpMobile: AbhaOtpMobile | undefined;
    if (showMobileInput) {
      if (!isValidMobile(mobile)) {
        setLocalError({
          field: "mobile",
          message: t("abha_error_invalid_mobile"),
        });
        return;
      }
      otpMobile = { value: normalizeMobile(mobile), edited: !!heldMobile };
      setEditingMobile(false);
    } else if (asksMobile && heldMobile) {
      otpMobile = { value: heldMobile.value, edited: false };
    }

    onVerify(code, otpMobile, () => setCode(""));
  };

  const description =
    otp.message ??
    (otp.sent_to
      ? t("abha_otp_sent_to", { destination: otp.sent_to })
      : t("abha_otp_sent"));

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleVerify}
      noValidate
      data-testid="abha-otp-step"
      data-purpose={otp.purpose}
    >
      <AbhaStepHeading
        title={t(`abha_otp_title__${otp.purpose}`)}
        description={description}
      />

      <div className="flex flex-col gap-2">
        <Label htmlFor={`${id}-otp`}>{t("abha_otp_label")}</Label>
        <InputOTP
          id={`${id}-otp`}
          maxLength={ABHA_OTP_LENGTH}
          pattern={REGEXP_ONLY_DIGITS}
          value={code}
          disabled={isPending}
          autoComplete="one-time-code"
          aria-invalid={!!otpError}
          aria-describedby={otpError ? `${id}-otp-error` : undefined}
          data-testid="abha-otp-input"
          onChange={(value) => {
            setCode(value);
            clearErrors();
          }}
        >
          <InputOTPGroup>
            {Array.from({ length: ABHA_OTP_LENGTH }, (_, index) => (
              <InputOTPSlot
                key={index}
                index={index}
                aria-invalid={!!otpError}
                className="size-10"
              />
            ))}
          </InputOTPGroup>
        </InputOTP>
        <AbhaFieldError id={`${id}-otp-error`} message={otpError} />
      </div>

      {asksMobile && (
        <div
          className="flex flex-col gap-2"
          data-testid="abha-communication-mobile"
        >
          {showMobileInput ? (
            <>
              <Label htmlFor={`${id}-mobile`}>
                {t("abha_communication_mobile")}
              </Label>
              <div className="flex items-center gap-2">
                <span className="rounded-md border border-gray-200 bg-gray-50 px-3 py-1.5 text-sm text-gray-700">
                  {ABHA_COUNTRY_CODE}
                </span>
                <Input
                  id={`${id}-mobile`}
                  value={mobile}
                  inputMode="numeric"
                  autoComplete="off"
                  disabled={isPending}
                  placeholder={t("abha_identifier_placeholder__mobile")}
                  aria-invalid={!!mobileError}
                  aria-describedby={`${id}-mobile-help`}
                  data-testid="abha-communication-mobile-input"
                  onChange={(event) => {
                    setMobile(event.target.value);
                    clearErrors();
                  }}
                />
              </div>
              <p id={`${id}-mobile-help`} className="text-xs text-gray-500">
                {t("abha_communication_mobile_help")}
              </p>
            </>
          ) : (
            heldMobile && (
              <>
                <span className="text-sm font-medium text-gray-900">
                  {t("abha_communication_mobile")}
                </span>
                <div className="flex flex-wrap items-center gap-2">
                  <span
                    className="text-sm font-semibold text-gray-900"
                    data-testid="abha-held-mobile"
                  >
                    {`${ABHA_COUNTRY_CODE} ${heldMobile.value}`}
                  </span>
                  <AbhaProvenanceBadge source={heldMobile.source} />
                  <Button
                    type="button"
                    variant="link"
                    className="h-auto p-0 text-primary-700"
                    disabled={isPending}
                    onClick={() => {
                      setMobile(heldMobile.value);
                      setEditingMobile(true);
                    }}
                  >
                    {t("change")}
                  </Button>
                </div>
              </>
            )
          )}
          <AbhaFieldError message={mobileError} />
        </div>
      )}

      <div
        className="flex flex-col items-start gap-1"
        data-testid="abha-resend"
      >
        {resendsExhausted ? (
          <p className="text-sm text-gray-600">
            {t("abha_otp_no_resends_left")}
          </p>
        ) : (
          <div className="flex flex-wrap items-center gap-3">
            <Button
              type="button"
              variant="link"
              className="h-auto p-0 text-primary-700"
              disabled={isPending || isCountingDown}
              data-testid="abha-resend-otp"
              onClick={() => {
                setNow(Date.now());
                setCode("");
                clearErrors();
                onResend();
              }}
            >
              {pendingAction === "resend_otp" && (
                <Loader2Icon className="animate-spin" />
              )}
              {isCountingDown
                ? t("resend_otp_timer", { time: secondsLeft })
                : t("resend_otp")}
            </Button>
            <span className="text-xs text-gray-500">
              {t("abha_otp_resends_remaining", {
                count: otp.resends_remaining,
              })}
            </span>
          </div>
        )}
        <AbhaFieldError message={resendError} />
      </div>

      <div className="flex flex-wrap justify-end gap-2">
        {otp.skippable && (
          <Button
            type="button"
            variant="outline"
            disabled={isPending}
            onClick={onSkip}
          >
            {pendingAction === "skip_mobile_otp" && (
              <Loader2Icon className="animate-spin" />
            )}
            {t("abha_skip_mobile_verification")}
          </Button>
        )}
        <Button type="submit" variant="primary" disabled={isPending}>
          {pendingAction === "verify_otp" && (
            <Loader2Icon className="animate-spin" />
          )}
          {t("verify_otp")}
        </Button>
      </div>
    </form>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Loader2Icon, RefreshCwIcon } from "lucide-react";
import { SyntheticEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Skeleton } from "@/components/ui/skeleton";

import query from "@/Utils/request/query";
import abhaApi from "@/types/abdm/abhaApi";

import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { abhaSilent, getNewAbhaAddressError, parseAbhaError } from "./utils";

const CUSTOM = "__custom__";

const ADDRESS_RULES = [
  "abha_address_rule_length",
  "abha_address_rule_characters",
  "abha_address_rule_edges",
  "abha_address_rule_start",
  "abha_address_rule_no_suffix",
];

/**
 * Choose an address (screen 6): suggestions from ABDM plus a free field.
 * A taken address shows its error and keeps the suggestions on screen.
 */
export function AbhaAddressStep({
  transactionId,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  transactionId: string;
  /** Server error for the address */
  error?: string;
  isPending: boolean;
  /** The address without the suffix */
  onSubmit: (address: string) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const customId = `${id}-custom`;
  const errorId = `${id}-error`;
  const rulesId = `${id}-rules`;

  const suggestionsQuery = useQuery({
    queryKey: ["abha", "address-suggestions", transactionId],
    queryFn: query(abhaApi.addressSuggestions, {
      queryParams: { transaction_id: transactionId },
      silent: abhaSilent,
    }),
    retry: false,
    staleTime: Infinity,
  });

  const suggestions = suggestionsQuery.data?.suggestions ?? [];
  const suffix = suggestionsQuery.data?.suffix ?? "";

  const [choice, setChoice] = useState<string>();
  const [custom, setCustom] = useState("");
  const [localError, setLocalError] = useState<string>();

  const selected = choice ?? suggestions[0] ?? CUSTOM;
  const isCustom = selected === CUSTOM;
  const errorMessage = localError ?? error;
  const suggestionsError = suggestionsQuery.error
    ? parseAbhaError(suggestionsQuery.error, t)
    : null;

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleSubmit = (event: SyntheticEvent) => {
    event.preventDefault();
    if (isPending) {
      return;
    }
    if (!isCustom) {
      onSubmit(selected);
      return;
    }
    const address = custom.trim();
    const ruleError = getNewAbhaAddressError(address);
    if (ruleError) {
      setLocalError(t(ruleError));
      return;
    }
    onSubmit(address);
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-address-step"
    >
      <AbhaStepHeading
        title={t("abha_address_title")}
        description={t("abha_address_description")}
      />

      {suggestionsQuery.isLoading && (
        <div className="flex flex-col gap-2">
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
        </div>
      )}

      {suggestionsError && (
        <Alert variant="destructive">
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{suggestionsError.message}</span>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => suggestionsQuery.refetch()}
            >
              <RefreshCwIcon />
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}

      {!suggestionsQuery.isLoading && (
        <RadioGroup
          value={selected}
          onValueChange={(value) => {
            setChoice(value);
            clearErrors();
          }}
          disabled={isPending}
          aria-label={t("abha_address_title")}
          className="gap-2"
          data-testid="abha-address-options"
        >
          {suggestions.map((suggestion) => {
            const itemId = `${id}-${suggestion}`;
            return (
              <label
                key={suggestion}
                htmlFor={itemId}
                className={cn(
                  "flex cursor-pointer items-center gap-3 rounded-md border p-3 text-sm",
                  selected === suggestion
                    ? "border-primary-500 bg-primary-50"
                    : "border-gray-200 bg-white hover:border-primary-300",
                )}
                data-testid="abha-address-suggestion"
              >
                <RadioGroupItem id={itemId} value={suggestion} />
                <span className="break-all font-medium text-gray-900">
                  {suggestion}
                  <span className="text-gray-500">{suffix}</span>
                </span>
              </label>
            );
          })}

          <div
            className={cn(
              "flex flex-col gap-3 rounded-md border p-3",
              isCustom
                ? "border-primary-500 bg-primary-50"
                : "border-gray-200 bg-white",
            )}
          >
            <label
              htmlFor={`${id}-custom-option`}
              className="flex cursor-pointer items-center gap-3 text-sm font-medium text-gray-900"
            >
              <RadioGroupItem id={`${id}-custom-option`} value={CUSTOM} />
              {t("abha_address_custom")}
            </label>

            <div className="flex flex-col gap-2">
              <Label htmlFor={customId} className="sr-only">
                {t("abha_address_custom")}
              </Label>
              <div className="flex items-center gap-2">
                <Input
                  id={customId}
                  value={custom}
                  autoComplete="off"
                  disabled={isPending}
                  placeholder={t("abha_address_custom_placeholder")}
                  aria-invalid={isCustom && !!errorMessage}
                  aria-describedby={cn(rulesId, errorMessage && errorId)}
                  data-testid="abha-address-custom-input"
                  onFocus={() => setChoice(CUSTOM)}
                  onChange={(event) => {
                    setChoice(CUSTOM);
                    setCustom(event.target.value);
                    clearErrors();
                  }}
                />
                {suffix && (
                  <span
                    className="shrink-0 text-sm font-medium text-gray-700"
                    data-testid="abha-address-suffix"
                  >
                    {suffix}
                  </span>
                )}
              </div>
              <ul
                id={rulesId}
                className="list-inside list-disc text-xs text-gray-600"
                data-testid="abha-address-rules"
              >
                {ADDRESS_RULES.map((rule) => (
                  <li key={rule}>{t(rule)}</li>
                ))}
              </ul>
            </div>
          </div>
        </RadioGroup>
      )}

      <AbhaFieldError id={errorId} message={errorMessage} />

      <div className="flex justify-end">
        <Button
          type="submit"
          variant="primary"
          disabled={isPending || suggestionsQuery.isLoading}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("abha_create_address")}
        </Button>
      </div>
    </form>
  );
}

import { useMutation } from "@tanstack/react-query";
import { IdCardIcon, Loader2Icon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import mutate from "@/Utils/request/mutate";
import { formatDateTime } from "@/Utils/utils";
import {
  AbhaJourney,
  AbhaProfile,
  LinkedPatient,
  PatientAbha,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";

import { AbhaCardDialog } from "./AbhaCardDialog";
import { AbhaLinkedPatientAlert } from "./AbhaLinkedPatientAlert";
import { AbhaProfileSummary } from "./AbhaProfileSummary";
import { AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaJourneyMode, AbhaLinkTarget } from "./types";
import { abhaSilent, AbhaUiError, parseAbhaError } from "./utils";

interface BirthDetails {
  date_of_birth?: string | null;
  year_of_birth?: number | null;
}

const formatBirth = ({ date_of_birth, year_of_birth }: BirthDetails) =>
  date_of_birth
    ? formatDateTime(date_of_birth, "DD MMM YYYY")
    : year_of_birth
      ? String(year_of_birth)
      : undefined;

/** The existing patient beside the ABHA profile, for the desk to confirm */
function AbhaLinkComparison({
  patient,
  profile,
}: {
  patient: AbhaLinkTarget;
  profile: AbhaProfile;
}) {
  const { t } = useTranslation();

  const rows = [
    { label: t("name"), patient: patient.name, abha: profile.name },
    {
      label: t("abha_birth_details"),
      patient: formatBirth(patient),
      abha: formatBirth(profile),
    },
    {
      label: t("sex"),
      patient: patient.gender && t(`GENDER__${patient.gender}`),
      abha: profile.gender && t(`GENDER__${profile.gender}`),
    },
  ];

  return (
    <div className="flex flex-col gap-2" data-testid="abha-link-comparison">
      <p className="text-sm text-gray-700">{t("abha_link_compare_hint")}</p>
      <div className="overflow-x-auto rounded-md border border-gray-200">
        <table className="w-full text-left text-sm">
          <thead className="bg-gray-50 text-xs text-gray-600">
            <tr>
              <th scope="col" className="px-3 py-2 font-medium">
                <span className="sr-only">{t("abha_link_field")}</span>
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abha_link_this_patient")}
              </th>
              <th scope="col" className="px-3 py-2 font-medium">
                {t("abha_link_abha_profile")}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.label} className="border-t border-gray-200">
                <th scope="row" className="px-3 py-2 font-medium text-gray-600">
                  {row.label}
                </th>
                <td className="px-3 py-2 text-gray-900">
                  {row.patient || "-"}
                </td>
                <td className="px-3 py-2 text-gray-900">{row.abha || "-"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * Result (screen 7). Shows the verified ABHA with its card. An ABHA already
 * linked to another patient blocks continuing (TAGGING).
 */
export function AbhaResultStep({
  mode,
  journey,
  facilityId,
  patientId,
  linkTarget,
  onContinue,
  onLinked,
}: {
  mode: AbhaJourneyMode;
  journey: AbhaJourney;
  facilityId?: string;
  patientId?: string;
  linkTarget?: AbhaLinkTarget;
  /** Register mode fills the form; reverify mode closes the journey */
  onContinue: () => void;
  onLinked: (patientAbha: PatientAbha) => void;
}) {
  const { t } = useTranslation();
  const profile = journey.profile;
  const [cardOpen, setCardOpen] = useState(mode === "reverify");
  const [linkError, setLinkError] = useState<AbhaUiError | null>(null);

  const { mutate: link, isPending: isLinking } = useMutation({
    mutationFn: mutate(abhaApi.link, { silent: abhaSilent }),
    onMutate: () => setLinkError(null),
    onSuccess: onLinked,
    onError: (error) => setLinkError(parseAbhaError(error, t)),
  });

  const otherPatient: LinkedPatient | undefined =
    (journey.linked_patient && !journey.linked_patient.is_current_patient
      ? journey.linked_patient
      : undefined) ??
    (linkError?.code === "abha_already_linked"
      ? linkError.linkedPatient
      : undefined);
  const isBlocked = !!otherPatient;

  return (
    <div className="flex flex-col gap-5" data-testid="abha-result-step">
      <AbhaStepHeading
        title={profile?.is_new ? t("abha_created") : t("abha_verified")}
        description={journey.message ?? undefined}
      />

      {profile && <AbhaProfileSummary profile={profile} />}

      {otherPatient && (
        <AbhaLinkedPatientAlert
          patient={otherPatient}
          facilityId={facilityId}
        />
      )}

      {mode === "link" && profile && linkTarget && !isBlocked && (
        <AbhaLinkComparison patient={linkTarget} profile={profile} />
      )}

      {linkError && !otherPatient && (
        <Alert variant="destructive" data-testid="abha-link-error">
          <AlertDescription>{linkError.message}</AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap justify-end gap-2">
        <Button
          variant="outline"
          onClick={() => setCardOpen(true)}
          data-testid="abha-view-card"
        >
          <IdCardIcon />
          {t("abha_view_card")}
        </Button>

        {mode === "register" && !isBlocked && (
          <Button variant="primary" onClick={onContinue}>
            {t("continue")}
          </Button>
        )}

        {mode === "link" && !isBlocked && patientId && (
          <Button
            variant="primary"
            disabled={isLinking}
            onClick={() =>
              link({
                transaction_id: journey.transaction_id,
                patient: patientId,
              })
            }
          >
            {isLinking && <Loader2Icon className="animate-spin" />}
            {t("abha_link_confirm")}
          </Button>
        )}

        {mode === "reverify" && (
          <Button variant="primary" onClick={onContinue}>
            {t("done")}
          </Button>
        )}
      </div>

      <AbhaCardDialog
        transactionId={journey.transaction_id}
        abhaNumber={profile?.abha_number}
        open={cardOpen}
        onOpenChange={setCardOpen}
      />
    </div>
  );
}

import { Loader2Icon } from "lucide-react";
import { SyntheticEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { AbhaConsentPanel } from "./AbhaConsentPanel";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFacts } from "./useAbhaFacts";
import { ABHA_COUNTRY_CODE, isValidAadhaar, normalizeAadhaar } from "./utils";

export interface AbhaCreateAadhaarInput {
  /** Normalised, only when the journey holds no Aadhaar */
  aadhaar?: string;
}

/**
 * Create with Aadhaar, after "No ABHA found". It asks only for the facts the
 * journey does not hold: the Aadhaar number and, if not yet given, consent.
 */
export function AbhaCreateAadhaarStep({
  facts,
  needsAadhaar,
  needsConsent,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  facts: AbhaFacts;
  needsAadhaar: boolean;
  needsConsent: boolean;
  /** Server error for the Aadhaar number */
  error?: string;
  isPending: boolean;
  onSubmit: (input: AbhaCreateAadhaarInput) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const inputId = `${id}-aadhaar`;
  const errorId = `${id}-error`;

  const [aadhaar, setAadhaar] = useState("");
  const [consented, setConsented] = useState(!needsConsent);
  const [localError, setLocalError] = useState<string>();

  const errorMessage = localError ?? error;
  const blocked = !consented;

  const handleSubmit = (event: SyntheticEvent) => {
    event.preventDefault();
    if (blocked || isPending) {
      return;
    }
    if (!needsAadhaar) {
      onSubmit({});
      return;
    }
    if (!isValidAadhaar(aadhaar)) {
      setLocalError(t("abha_error_invalid_aadhaar"));
      return;
    }
    onSubmit({ aadhaar: normalizeAadhaar(aadhaar) });
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-create-aadhaar-step"
    >
      <AbhaStepHeading
        title={t("abha_create_title")}
        description={t("abha_create_description")}
      />

      {needsConsent && (
        <AbhaConsentPanel checked={consented} onCheckedChange={setConsented} />
      )}

      {needsAadhaar && (
        <div className="flex flex-col gap-2">
          <Label htmlFor={inputId}>{t("abha_identifier__aadhaar")}</Label>
          <Input
            id={inputId}
            value={aadhaar}
            inputMode="numeric"
            autoComplete="off"
            disabled={isPending || blocked}
            placeholder={t("abha_identifier_placeholder__aadhaar")}
            aria-invalid={!!errorMessage}
            aria-describedby={errorMessage ? errorId : undefined}
            data-testid="abha-aadhaar-input"
            onChange={(event) => {
              setAadhaar(event.target.value);
              setLocalError(undefined);
              onClearError();
            }}
          />
          <AbhaFieldError id={errorId} message={errorMessage} />
        </div>
      )}
      {!needsAadhaar && <AbhaFieldError message={errorMessage} />}

      {facts.mobile && (
        <div
          className="flex flex-col gap-1"
          data-testid="abha-create-held-mobile"
        >
          <span className="text-sm font-medium text-gray-900">
            {t("abha_communication_mobile")}
          </span>
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-sm font-semibold text-gray-900">
              {`${ABHA_COUNTRY_CODE} ${facts.mobile.value}`}
            </span>
            <AbhaProvenanceBadge source={facts.mobile.source} />
          </div>
          <p className="text-xs text-gray-500">
            {t("abha_communication_mobile_held")}
          </p>
        </div>
      )}

      <div className="flex justify-end">
        <Button type="submit" variant="primary" disabled={isPending || blocked}>
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("send_otp")}
        </Button>
      </div>
    </form>
  );
}

