            {abha && !abha.linked && (
              <Button
                variant="outline"
                onClick={() => setSheetMode("link")}
                data-testid="abha-section-link"
              >
                <LinkIcon />
                {t("abha_link")}
              </Button>
            )}
          </div>
        )}
