import { useQuery } from "@tanstack/react-query";
import { DownloadIcon, RefreshCwIcon } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";

import query from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";
import abhaApi from "@/types/abdm/abhaApi";

import {
  abhaSilent,
  blobToDataUrl,
  downloadBlob,
  parseAbhaError,
} from "./utils";

/** Shows the ABHA card PNG of a verified journey, with a download action */
export function AbhaCardDialog({
  transactionId,
  abhaNumber,
  open,
  onOpenChange,
}: {
  transactionId: string;
  abhaNumber?: string | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const { t } = useTranslation();

  const cardQuery = useQuery({
    queryKey: ["abha", "card", transactionId],
    queryFn: async ({ signal }) => {
      const blob = await query(abhaApi.card, {
        queryParams: { transaction_id: transactionId },
        headers: { Accept: "image/png" },
        silent: abhaSilent,
      })({ signal });
      if (!(blob instanceof Blob)) {
        throw new HTTPError({
          message: "Invalid ABHA card response",
          status: 200,
          silent: true,
        });
      }
      return { blob, src: await blobToDataUrl(blob) };
    },
    enabled: open,
    retry: false,
    staleTime: Infinity,
  });

  const error = cardQuery.error ? parseAbhaError(cardQuery.error, t) : null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl" data-testid="abha-card-dialog">
        <DialogHeader>
          <DialogTitle>{t("abha_card")}</DialogTitle>
          <DialogDescription>{abhaNumber}</DialogDescription>
        </DialogHeader>

        {cardQuery.isLoading && (
          <Skeleton className="aspect-[1.6] w-full rounded-md" />
        )}

        {error && (
          <Alert variant="destructive">
            <AlertDescription>{error.message}</AlertDescription>
          </Alert>
        )}

        {cardQuery.data && (
          <img
            src={cardQuery.data.src}
            alt={t("abha_card")}
            className="w-full rounded-md border border-gray-200"
          />
        )}

        <DialogFooter>
          {error && (
            <Button variant="outline" onClick={() => cardQuery.refetch()}>
              <RefreshCwIcon />
              {t("try_again")}
            </Button>
          )}
          <Button
            variant="primary"
            disabled={!cardQuery.data}
            onClick={() =>
              cardQuery.data &&
              downloadBlob(
                cardQuery.data.blob,
                `abha-card-${abhaNumber ?? transactionId}.png`,
              )
            }
          >
            <DownloadIcon />
            {t("download")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

