import { faker } from "@faker-js/faker";
import { expect, Locator, Page, test } from "@playwright/test";
import {
  ABDM_DISABLED_REASON,
  ABHA_CONSENT,
  ABHA_CONSENT_AGREE,
  ABHA_CONSENT_TERMS,
  ABHA_OTP,
  abhaError,
  buildAccount,
  buildJourney,
  buildLinkedPatient,
  buildPatientAbha,
  cardResponse,
  getUnmockedAbhaCalls,
  isAbdmEnabled,
  linkedPatientUrl,
  maskMobile,
  mockAbha,
  otpSentJourney,
  randomMobile,
  respond,
  secondsFromNow,
  submitAbhaOtp,
  TRANSACTION_ID,
  verifiedJourney,
} from "tests/helper/abha";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

const AADHAAR_OTP_MESSAGE =
  "OTP sent to Aadhaar registered mobile number ending with ******1234";

/** Short enough to wait out in a test; CARE sends 60 seconds */
const RESEND_COOLDOWN_SECONDS = 3;

/**
 * Opens patient registration. `mobile` is passed the way patient search
 * passes it, as `?phone_number=+91…`.
 */
async function openRegistration(
  page: Page,
  facilityId: string,
  mobile?: string,
) {
  const query = mobile
    ? `?${new URLSearchParams({ phone_number: `+91${mobile}` })}`
    : "";
  await page.goto(`/facility/${facilityId}/patient/create${query}`);
  await expect(page.getByTestId("abha-registration-journey")).toBeVisible();
  return page.getByTestId("abha-journey");
}

/** Mobile login: Identify → OTP → Result */
async function verifyWithMobile(journey: Locator) {
  await journey.getByRole("button", { name: "Send OTP", exact: true }).click();
  await submitAbhaOtp(journey);
  const result = journey.getByTestId("abha-result-step");
  await expect(result).toBeVisible();
  return result;
}

const formItem = (page: Page, field: Locator) =>
  page.locator('[data-slot="form-item"]').filter({ has: field });

/** Picks the first option at every level of the cascading geo organization */
async function selectGeoOrganization(page: Page) {
  const additionalDetails = page.getByRole("button", {
    name: "Additional Details",
  });
  if (
    (await additionalDetails.textContent())?.toLowerCase().includes("optional")
  ) {
    await additionalDetails.click();
  }

  const region = page.getByRole("region", { name: "Additional Details" });
  for (let level = 0; level < 10; level++) {
    const combobox = region.getByRole("combobox").nth(level);
    try {
      await combobox.waitFor({ state: "visible", timeout: 3000 });
    } catch {
      break;
    }
    await combobox.click();
    await page.getByRole("option").first().click();
  }
}

/** Registers the patient and returns the id CARE gave it */
async function registerPatient(page: Page) {
  await selectGeoOrganization(page);
  const created = page.waitForResponse(
    (response) =>
      response.request().method() === "POST" &&
      new URL(response.url()).pathname === "/api/v1/patient/",
  );
  await page.getByRole("button", { name: /register patient/i }).click();
  const response = await created;
  expect(response.ok()).toBe(true);
  const patient: { id: string } = await response.json();
  return patient.id;
}

test.describe("ABHA in patient registration", () => {
  test.skip(!isAbdmEnabled(), ABDM_DISABLED_REASON);

  let facilityId: string;

  test.beforeEach(() => {
    facilityId = getFacilityId();
  });

  test.afterEach(({ page }) => {
    expect(getUnmockedAbhaCalls(page)).toEqual([]);
  });

  test("refuses an invalid mobile or Aadhaar number without calling CARE", async ({
    page,
  }) => {
    const abha = await mockAbha(page, {});
    const journey = await openRegistration(page, facilityId);
    const identify = journey.getByTestId("abha-identify-step");
    const input = identify.getByTestId("abha-identifier-input");
    const sendOtp = identify.getByRole("button", {
      name: "Send OTP",
      exact: true,
    });
    const error = identify.getByTestId("abha-field-error");

    await test.step("Mobile number (VRFY_ABHA_301)", async () => {
      await expect(
        identify.getByRole("radio", { name: "Mobile Number", exact: true }),
      ).toBeChecked();
      for (const mobile of ["98765", "5876543210", "98765432101"]) {
        await input.fill(mobile);
        await sendOtp.click();
        await expect(error).toHaveText("Enter a valid 10-digit mobile number");
      }
    });

    await test.step("Aadhaar number (CRT_ABHA_104, VRFY_ABHA_401)", async () => {
      await identify
        .getByRole("radio", { name: "Aadhaar Number", exact: true })
        .click();
      await identify
        .getByRole("checkbox", { name: ABHA_CONSENT_AGREE })
        .check();
      for (const aadhaar of ["23456789012", "2345678901234"]) {
        await input.fill(aadhaar);
        await sendOtp.click();
        await expect(error).toHaveText("Enter a valid 12-digit Aadhaar number");
      }
    });

    expect(abha.requests).toEqual([]);
  });

  test("asks for consent before an Aadhaar number, and never asks for it twice", async ({
    page,
  }) => {
    const mobile = randomMobile();
    const aadhaarJourney = {
      identifier_type: "aadhaar" as const,
      masked_identifier: "XXXX XXXX 0123",
      auth_methods: ["aadhaar_otp" as const],
      consent_recorded: true,
    };
    const abha = await mockAbha(page, {
      sendOtp: () =>
        respond(buildJourney({ status: "no_account", ...aadhaarJourney })),
      createSendOtp: () =>
        respond(
          otpSentJourney(
            { purpose: "aadhaar", message: AADHAAR_OTP_MESSAGE },
            { flow: "create", ...aadhaarJourney },
          ),
        ),
      verifyOtp: () => respond(verifiedJourney({ mobile })),
    });
    const journey = await openRegistration(page, facilityId);
    const identify = journey.getByTestId("abha-identify-step");
    const input = identify.getByTestId("abha-identifier-input");
    const sendOtp = identify.getByRole("button", {
      name: "Send OTP",
      exact: true,
    });

    await test.step("The consent is shown word for word (CRT_ABHA_102)", async () => {
      await identify
        .getByRole("radio", { name: "Aadhaar Number", exact: true })
        .click();
      const consent = identify.getByTestId("abha-consent-panel");
      await expect(
        consent.getByRole("heading", { name: "Terms and Conditions" }),
      ).toBeVisible();
      await expect(
        consent.getByRole("region", { name: "Terms and Conditions" }),
      ).toHaveText(ABHA_CONSENT_TERMS);
    });

    await test.step("The Aadhaar number is locked until the patient agrees", async () => {
      await expect(input).toBeDisabled();
      await expect(sendOtp).toBeDisabled();
      await identify
        .getByRole("checkbox", { name: ABHA_CONSENT_AGREE })
        .check();
      await expect(input).toBeEnabled();
      await input.fill("2345 6789 0123");
      await sendOtp.click();
    });

    await test.step("No ABHA found for the Aadhaar number (VRFY_ABHA_403)", async () => {
      const noAccount = journey.getByTestId("abha-no-account-step");
      await expect(
        noAccount.getByRole("heading", { name: "No ABHA found" }),
      ).toBeVisible();
      await expect(noAccount).toContainText(
        "No ABHA was found for the Aadhaar number XXXX XXXX 0123.",
      );
      expect(abha.calls("sendOtp")[0].body).toEqual({
        identifier_type: "aadhaar",
        identifier: "234567890123",
        consent: ABHA_CONSENT,
        facility: facilityId,
      });
      await noAccount
        .getByRole("button", { name: "Create ABHA with Aadhaar" })
        .click();
    });

    await test.step("Creation reuses the Aadhaar number and consent (CRT_ABHA_105)", async () => {
      const otpStep = journey.getByTestId("abha-otp-step");
      await expect(otpStep).toHaveAttribute("data-purpose", "aadhaar");
      await expect(otpStep).toContainText(AADHAAR_OTP_MESSAGE);
      expect(abha.calls("createSendOtp")[0].body).toEqual({
        transaction_id: TRANSACTION_ID,
      });

      const resend = otpStep.getByTestId("abha-resend-otp");
      await expect(resend).toBeDisabled();
      await expect(resend).toHaveText(/^Resend OTP in (60|59|58) seconds$/);
    });

    await test.step("The communication mobile is asked once, on the OTP step", async () => {
      const otpStep = journey.getByTestId("abha-otp-step");
      const mobileInput = otpStep.getByTestId(
        "abha-communication-mobile-input",
      );
      await mobileInput.fill("12345");
      await submitAbhaOtp(journey);
      await expect(otpStep.getByTestId("abha-field-error")).toHaveText(
        "Enter a valid 10-digit mobile number",
      );
      expect(abha.calls("verifyOtp")).toHaveLength(0);

      await mobileInput.fill(mobile);
      await otpStep.getByRole("button", { name: "Verify OTP" }).click();
      await expect(
        journey.getByRole("heading", { name: "ABHA verified" }),
      ).toBeVisible();
      expect(abha.calls("verifyOtp")[0].body).toEqual({
        transaction_id: TRANSACTION_ID,
        otp: ABHA_OTP,
        mobile,
      });
    });
  });

  test("creates an ABHA for a mobile number that has none (CRT_ABHA_101)", async ({
    page,
  }) => {
