      const name = page.getByRole("textbox", { name: /name.*\*/i });
      await expect(name).toHaveValue(profile.name);
      await expect(name).not.toBeEditable();
      await expect(
        formItem(page, name).getByTestId("abha-provenance"),
      ).toHaveText("From ABHA profile");

      const female = page.getByRole("radio", { name: "Female", exact: true });
      await expect(female).toBeChecked();
      await expect(female).toBeDisabled();

      for (const [placeholder, value] of [
        ["DD", "31"],
        ["MM", "01"],
        ["YYYY", "1990"],
      ]) {
        const field = page.getByPlaceholder(placeholder, { exact: true });
        await expect(field).toHaveValue(value);
        await expect(field).toBeDisabled();
      }
      await expect(page.getByRole("tab", { name: "Age" })).toBeDisabled();
    });

    await test.step("The phone number stays editable", async () => {
      const phone = page.getByRole("textbox", { name: /phone number.*\*/i });
      await expect(phone).toBeEditable();
      await expect(
        formItem(page, phone).getByTestId("abha-provenance"),
      ).toHaveText("From patient search");
    });

    await test.step("The ABHA is linked once the patient is registered", async () => {
      const patientId = await registerPatient(page);
      await expectToast(page, "ABHA linked to the patient");
      await expect(page).toHaveURL(
        new RegExp(`/facility/${facilityId}/patients/home`),
      );
      expect(abha.calls("link").map((call) => call.body)).toEqual([
        { transaction_id: TRANSACTION_ID, patient: patientId },
      ]);
    });
  });

  test("registers the patient even when linking the ABHA fails", async ({
    page,
  }) => {
    const mobile = randomMobile();
    const abha = await mockAbha(page, {
      sendOtp: () => respond(otpSentJourney({ sent_to: maskMobile(mobile) })),
      verifyOtp: () =>
        respond(
          verifiedJourney({ name: faker.person.fullName(), mobile, pincode: null }),
        ),
      link: () =>
        abhaError(502, "abdm_unavailable", "ABDM is not reachable", null),
    });
    const journey = await openRegistration(page, facilityId, mobile);
    const result = await verifyWithMobile(journey);
    await result.getByRole("button", { name: "Continue", exact: true }).click();
    await expect(page.getByTestId("abha-registration-summary")).toBeVisible();

    await page
      .getByRole("spinbutton", { name: "PIN Code" })
      .fill(faker.string.numeric({ length: 6, allowLeadingZeros: false }));
    const patientId = await registerPatient(page);
    await expectToast(
      page,
      "The patient was registered, but the ABHA could not be linked: ABDM is unavailable right now. Please try again in a while.",
    );
    await expect(page).toHaveURL(
      new RegExp(`/facility/${facilityId}/patients/home`),
    );
    expect(abha.calls("link")[0].body).toEqual({
      transaction_id: TRANSACTION_ID,
      patient: patientId,
    });
  });
});

