import { useMutation } from "@tanstack/react-query";
import { RotateCcwIcon } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import {
  AbhaAuthMethod,
  AbhaIdentifierType,
  AbhaJourney as AbhaJourneyResponse,
} from "@/types/abdm/abha";

import { AbhaAccountStep } from "./AbhaAccountStep";
import { AbhaAddressStep } from "./AbhaAddressStep";
import { AbhaConfirmIdentityStep } from "./AbhaConfirmIdentityStep";
import {
  AbhaCreateAadhaarInput,
  AbhaCreateAadhaarStep,
} from "./AbhaCreateAadhaarStep";
import { AbhaIdentifyInput, AbhaIdentifyStep } from "./AbhaIdentifyStep";
import { AbhaJourneyAction, runAbhaJourneyAction } from "./abhaJourneyActions";
import { AbhaMethodStep } from "./AbhaMethodStep";
import { AbhaNoAccountStep } from "./AbhaNoAccountStep";
import { AbhaOtpMobile, AbhaOtpStep } from "./AbhaOtpStep";
import { AbhaResultStep } from "./AbhaResultStep";
import { AbhaJourneyMode, AbhaJourneyResult, AbhaLinkTarget } from "./types";
import { AbhaFacts, useAbhaFacts } from "./useAbhaFacts";
import {
  ABHA_CONSENT,
  ABHA_RESTART_CODES,
  AbhaUiError,
  AbhaUiErrorCode,
  maskAadhaar,
  parseAbhaError,
} from "./utils";

/** Screens that are not a journey status of their own */
type AbhaLocalView = "identify" | "method" | "create_aadhaar";

type AbhaStepKind =
  | AbhaLocalView
  | "confirm_identity"
  | "otp"
  | "no_account"
  | "select_account"
  | "select_address"
  | "verified";

const ALL_AUTH_METHODS: AbhaAuthMethod[] = ["aadhaar_otp", "mobile_otp"];

/** Errors that each step shows beside its own inputs; the rest go in a banner */
const INLINE_ERRORS: Partial<
  Record<AbhaStepKind, { fields: string[]; codes: AbhaUiErrorCode[] }>
> = {
  identify: {
    fields: ["identifier", "mobile", "aadhaar", "abha_number", "abha_address"],
    codes: [
      "invalid_mobile",
      "invalid_aadhaar",
      "invalid_abha_number",
      "invalid_abha_address",
      "consent_required",
    ],
  },
  otp: {
    fields: ["otp", "mobile"],
    codes: [
      "invalid_mobile",
      "resend_cooldown",
      "resend_limit_reached",
      "rate_limited",
    ],
  },
  create_aadhaar: {
    fields: ["aadhaar"],
    codes: ["invalid_aadhaar", "consent_required"],
  },
  select_address: {
    fields: ["abha_address"],
    codes: ["invalid_abha_address"],
  },
};

const isInlineError = (step: AbhaStepKind, error: AbhaUiError) => {
  const inline = INLINE_ERRORS[step];
  return (
    !!inline &&
    ((!!error.field && inline.fields.includes(error.field)) ||
      inline.codes.includes(error.code))
  );
};

const getStepKind = (
  view: AbhaLocalView | "journey",
  journey: AbhaJourneyResponse | null,
): AbhaStepKind => {
  if (view !== "journey" || !journey) {
    return view === "journey" ? "identify" : view;
  }
  return journey.status === "otp_sent" ? "otp" : journey.status;
};

/**
 * The ABHA journey (contract §6.3). One component for the three entry points:
 * registration, linking an existing patient and re-verifying a linked ABHA.
 * Each step talks to CARE only; CARE holds the ABDM transaction.
 */
export function AbhaJourney({
  mode,
  facilityId,
  patientId,
  initialFacts,
  linkTarget,
  onComplete,
  onExit,
}: {
  mode: AbhaJourneyMode;
  facilityId?: string;
  /** Required in `link` and `reverify` modes */
  patientId?: string;
  initialFacts: AbhaFacts;
  linkTarget?: AbhaLinkTarget;
  onComplete: (result: AbhaJourneyResult) => void;
  /** "Continue without ABHA" in register mode, "Cancel" otherwise */
  onExit: (facts: AbhaFacts) => void;
}) {
  const { t } = useTranslation();
  const { facts, tried, setFact, recordConsent, addTried, forgetSource } =
    useAbhaFacts(initialFacts);

  const initialView: AbhaLocalView =
    mode === "reverify" ? "method" : "identify";
  const [view, setView] = useState<AbhaLocalView | "journey">(initialView);
  const [journey, setJourney] = useState<AbhaJourneyResponse | null>(null);
  const [error, setError] = useState<AbhaUiError | null>(null);
  const [identifyType, setIdentifyType] =
    useState<AbhaIdentifierType>("mobile");

  // Journey-starting calls carry the context; later calls only the transaction
  const context = {
    facility: facilityId,
    patient: mode === "register" ? undefined : patientId,
  };

  const {
    mutate: run,
    isPending,
    variables,
    reset,
  } = useMutation({
    mutationFn: runAbhaJourneyAction,
    onMutate: () => setError(null),
    onSuccess: (next) => {
      setJourney(next);
      setView("journey");
      if (next.status === "no_account") {
        addTried({ route: next.identifier_type, reason: "no_account" });
      }
      if (next.status === "verified" && next.profile) {
        // Write-once: facts the desk already gave keep their value and source
        if (next.profile.abha_number) {
          setFact("abhaNumber", next.profile.abha_number, "abha_profile");
        }
        if (next.profile.abha_address) {
          setFact("abhaAddress", next.profile.abha_address, "abha_profile");
        }
        if (next.profile.mobile) {
          setFact("mobile", next.profile.mobile, "abha_profile");
        }
      }
    },
    onError: (failure, action: AbhaJourneyAction) => {
      const parsed = parseAbhaError(failure, t);
      setError(parsed);
      if (action.type === "search" && parsed.code === "ABDM-1211") {
        addTried({ route: "abha_address", reason: "not_found" });
      }
    },
  });

  const pendingAction = isPending ? variables?.type : undefined;
  const stepKind = getStepKind(view, journey);
  const stepKey =
    stepKind === "otp" ? `otp:${journey?.otp?.purpose ?? ""}` : stepKind;
  const inlineError =
    error && isInlineError(stepKind, error) ? error : undefined;
  const bannerError = error && !inlineError ? error : undefined;
  const mustRestart =
    !!bannerError && ABHA_RESTART_CODES.includes(bannerError.code);

  // Move focus to the new step's heading (not on the first render)
  const containerRef = useRef<HTMLDivElement>(null);
  const previousStepKey = useRef(stepKey);
  useEffect(() => {
    if (previousStepKey.current === stepKey) {
      return;
    }
    previousStepKey.current = stepKey;
    containerRef.current
      ?.querySelector<HTMLElement>("[data-abha-step-heading]")
      ?.focus();
  }, [stepKey]);

  const clearError = () => setError(null);

  const showLocalError = (message: string) =>
    setError({ code: "unknown", message, receivedAt: Date.now() });

  const restart = () => {
    reset();
    setError(null);
    setJourney(null);
    forgetSource("abha_profile");
    setView(initialView);
  };

  const backToIdentify = () => {
    reset();
    setError(null);
    setJourney(null);
    setView("identify");
  };

  const handleIdentify = ({ type, value, authMethod }: AbhaIdentifyInput) => {
    setIdentifyType(type);
    switch (type) {
      case "mobile":
        setFact("mobile", value, "desk", { override: true });
        break;
      case "aadhaar":
        setFact("aadhaarMasked", maskAadhaar(value), "desk", {
          override: true,
        });
        recordConsent();
        break;
      case "abha_number":
        setFact("abhaNumber", value, "desk", { override: true });
        break;
      case "abha_address":
        setFact("abhaAddress", value, "desk", { override: true });
        break;
    }

    if (type === "abha_address") {
      run({ type: "search", body: { abha_address: value, ...context } });
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: type,
        identifier: value,
        auth_method: authMethod,
        consent: type === "aadhaar" ? ABHA_CONSENT : undefined,
        ...context,
      },
    });
  };

  const sendAddressOtp = (authMethod: AbhaAuthMethod) => {
    if (!journey) {
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_address",
        transaction_id: journey.transaction_id,
        auth_method: authMethod,
      },
    });
  };

  const handleConfirmIdentity = () => {
    const methods = journey?.auth_methods ?? [];
    if (methods.length > 1) {
      setError(null);
      setView("method");
    } else if (methods.length === 1) {
      sendAddressOtp(methods[0]);
    } else {
      showLocalError(t("abha_error_no_auth_methods"));
    }
  };

  const handleMethod = (authMethod: AbhaAuthMethod) => {
    if (journey?.status === "confirm_identity") {
      sendAddressOtp(authMethod);
      return;
    }
    // Re-verify the ABHA number held on the patient record
    if (!facts.abhaNumber) {
      showLocalError(t("abha_error_invalid_abha_number"));
      return;
    }
    run({
      type: "send_otp",
      body: {
        identifier_type: "abha_number",
        identifier: facts.abhaNumber.value,
        auth_method: authMethod,
        ...context,
      },
    });
  };

  const startCreate = (aadhaar?: string) => {
    if (!journey) {
      return;
    }
    run({
      type: "create_send_otp",
      body: {
        transaction_id: journey.transaction_id,
        aadhaar,
        consent: journey.consent_recorded ? undefined : ABHA_CONSENT,
      },
    });
  };

  const handleNoAccountCreate = () => {
    if (!journey) {
      return;
    }
    // Ask only for what the journey does not hold
    const needsAadhaar = journey.identifier_type !== "aadhaar";
    const needsConsent = !journey.consent_recorded && !facts.consent;
    if (needsAadhaar || needsConsent) {
      setError(null);
      setView("create_aadhaar");
      return;
    }
    startCreate();
  };

  const handleCreateAadhaar = ({ aadhaar }: AbhaCreateAadhaarInput) => {
    if (aadhaar) {
      setFact("aadhaarMasked", maskAadhaar(aadhaar), "desk", {
        override: true,
      });
    }
    recordConsent();
    startCreate(aadhaar);
  };

  const handleVerifyOtp = (
    otp: string,
    mobile: AbhaOtpMobile | undefined,
    onError: () => void,
  ) => {
    if (!journey) {
      return;
    }
    if (mobile) {
      setFact("mobile", mobile.value, "desk", { override: mobile.edited });
    }
    run(
      {
        type: "verify_otp",
        body: {
          transaction_id: journey.transaction_id,
          otp,
          mobile: mobile?.value,
        },
      },
      { onError },
    );
  };

  const renderStep = () => {
    switch (stepKind) {
      case "identify":
        return (
          <AbhaIdentifyStep
            facts={facts}
            tried={tried}
            initialType={identifyType}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={handleIdentify}
            onClearError={clearError}
          />
        );
      case "method": {
        const fromSearch = journey?.status === "confirm_identity";
        return (
          <AbhaMethodStep
            methods={fromSearch ? journey.auth_methods : ALL_AUTH_METHODS}
            identifierLabel={fromSearch ? t("abha_address") : t("abha_number")}
            identifier={
              fromSearch
                ? (journey.search_result?.abha_address ??
                  journey.masked_identifier ??
                  undefined)
                : facts.abhaNumber
            }
            isPending={isPending}
            onSubmit={handleMethod}
          />
        );
      }
      case "create_aadhaar":
        return (
          journey && (
            <AbhaCreateAadhaarStep
              facts={facts}
              needsAadhaar={journey.identifier_type !== "aadhaar"}
              needsConsent={!journey.consent_recorded && !facts.consent}
              error={inlineError?.message}
              isPending={isPending}
              onSubmit={handleCreateAadhaar}
              onClearError={clearError}
            />
          )
        );
    }

    if (!journey) {
      return null;
    }
    const transactionId = journey.transaction_id;

    switch (stepKind) {
      case "confirm_identity":
        return (
          <AbhaConfirmIdentityStep
            searchResult={journey.search_result}
            isPending={isPending}
            onConfirm={handleConfirmIdentity}
            onReject={backToIdentify}
          />
        );
      case "otp":
        return (
          journey.otp && (
            <AbhaOtpStep
              key={`${transactionId}-${journey.otp.purpose}`}
              otp={journey.otp}
              facts={facts}
              error={inlineError ?? null}
              pendingAction={pendingAction}
              onVerify={handleVerifyOtp}
              onResend={() =>
                run({
                  type: "resend_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onSkip={() =>
                run({
                  type: "skip_mobile_otp",
                  body: { transaction_id: transactionId },
                })
              }
              onClearError={clearError}
            />
          )
        );
      case "no_account":
        return (
          <AbhaNoAccountStep
            journey={journey}
            isPending={isPending}
            onCreate={handleNoAccountCreate}
            onTryAnother={backToIdentify}
          />
        );
      case "select_account":
        return (
          <AbhaAccountStep
            accounts={journey.accounts ?? []}
            isPending={isPending}
            onSelect={(abhaNumber) =>
              run({
                type: "select_account",
                body: {
                  transaction_id: transactionId,
                  abha_number: abhaNumber,
                },
              })
            }
          />
        );
      case "select_address":
        return (
          <AbhaAddressStep
            key={transactionId}
            transactionId={transactionId}
            error={inlineError?.message}
            isPending={isPending}
            onSubmit={(address) =>
              run({
                type: "create_address",
                body: { transaction_id: transactionId, abha_address: address },
              })
            }
            onClearError={clearError}
          />
        );
      case "verified":
        return (
          <AbhaResultStep
            mode={mode}
            journey={journey}
            facilityId={facilityId}
            patientId={patientId}
            linkTarget={linkTarget}
            onContinue={() => onComplete({ journey, facts })}
            onLinked={(patientAbha) =>
              onComplete({ journey, facts, patientAbha })
            }
          />
        );
    }
  };

  return (
    <div
      ref={containerRef}
      className="flex flex-col gap-5"
      data-testid="abha-journey"
      data-step={stepKey}
    >
      {renderStep()}

      {bannerError && (
        <Alert variant="destructive" data-testid="abha-journey-error">
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{bannerError.message}</span>
            {mustRestart && (
              <Button variant="outline" size="sm" onClick={restart}>
                <RotateCcwIcon />
                {t("abha_start_again")}
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}

      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-gray-200 pt-4">
        <div>
          {stepKind !== initialView && !mustRestart && (
            <Button
              variant="ghost"
              size="sm"
              disabled={isPending}
              onClick={restart}
              data-testid="abha-start-again"
            >
              <RotateCcwIcon />
              {t("abha_start_again")}
            </Button>
          )}
        </div>
        <Button
          variant="outline"
          onClick={() => onExit(facts)}
          data-testid="abha-exit"
        >
          {mode === "register" ? t("abha_continue_without") : t("cancel")}
        </Button>
      </div>
    </div>
  );
}

import { useCallback, useReducer } from "react";

import { ABHA_CONSENT_VERSION, AbhaIdentifierType } from "@/types/abdm/abha";

/**
 * Page-scoped fact store for one ABHA journey ("never ask twice", contract
 * §6.2). It lives inside the journey component, so nothing survives into the
 * next journey or the next patient.
 */

export type AbhaFactSource =
  "patient_search" | "desk" | "abha_profile" | "patient_record";

export interface AbhaFact<T> {
  value: T;
  source: AbhaFactSource;
}

export interface AbhaConsentFact {
  accepted: true;
  version: typeof ABHA_CONSENT_VERSION;
  at: string;
}

export interface AbhaFacts {
  /** 10 digits, without +91 */
  mobile?: AbhaFact<string>;
  /** Only the masked form ("XXXX XXXX 1234") is ever held */
  aadhaarMasked?: AbhaFact<string>;
  abhaNumber?: AbhaFact<string>;
  abhaAddress?: AbhaFact<string>;
  consent?: AbhaConsentFact;
}

export type AbhaFactKey = Exclude<keyof AbhaFacts, "consent">;

export type AbhaTriedReason = "no_account" | "not_found";

export interface AbhaTriedRoute {
  route: AbhaIdentifierType;
  reason: AbhaTriedReason;
}

interface AbhaFactsState {
  facts: AbhaFacts;
  tried: AbhaTriedRoute[];
}

type AbhaFactsAction =
  | {
      type: "set";
      key: AbhaFactKey;
      fact: AbhaFact<string>;
      /** An explicit edit on the step that owns the fact */
      override: boolean;
    }
  | { type: "consent"; at: string }
  | { type: "tried"; route: AbhaTriedRoute }
  | { type: "forget_source"; source: AbhaFactSource };

function reducer(
  state: AbhaFactsState,
  action: AbhaFactsAction,
): AbhaFactsState {
  switch (action.type) {
    case "set": {
      const current = state.facts[action.key];
      // Facts are write-once: a different value is refused unless the user
      // explicitly edited the field.
      if (current && (current.value === action.fact.value || !action.override))
        return state;
      return { ...state, facts: { ...state.facts, [action.key]: action.fact } };
    }
    case "consent": {
      if (state.facts.consent) return state;
      return {
        ...state,
        facts: {
          ...state.facts,
          consent: {
            accepted: true,
            version: ABHA_CONSENT_VERSION,
            at: action.at,
          },
        },
      };
    }
    case "tried": {
      const exists = state.tried.some(
        (tried) =>
          tried.route === action.route.route &&
          tried.reason === action.route.reason,
      );
      if (exists) return state;
      return { ...state, tried: [...state.tried, action.route] };
    }
    case "forget_source": {
      const facts = { ...state.facts };
      (["mobile", "aadhaarMasked", "abhaNumber", "abhaAddress"] as const)
        .filter((key) => facts[key]?.source === action.source)
        .forEach((key) => delete facts[key]);
      return { ...state, facts };
    }
  }
}

export function useAbhaFacts(initialFacts: AbhaFacts) {
  const [state, dispatch] = useReducer(reducer, {
    facts: initialFacts,
    tried: [],
  });

  const setFact = useCallback(
    (
      key: AbhaFactKey,
      value: string,
      source: AbhaFactSource,
      { override = false }: { override?: boolean } = {},
    ) => dispatch({ type: "set", key, fact: { value, source }, override }),
    [],
  );

  const recordConsent = useCallback(
    () => dispatch({ type: "consent", at: new Date().toISOString() }),
    [],
  );

  const addTried = useCallback(
    (route: AbhaTriedRoute) => dispatch({ type: "tried", route }),
    [],
  );

  const forgetSource = useCallback(
    (source: AbhaFactSource) => dispatch({ type: "forget_source", source }),
    [],
  );

  return {
    facts: state.facts,
    tried: state.tried,
    setFact,
    recordConsent,
    addTried,
    forgetSource,
  };
}

import { TFunction } from "i18next";

import { HTTPError } from "@/Utils/request/types";
import {
  ABHA_CONSENT_VERSION,
  AbhaAuthMethod,
  AbhaConsent,
  AbhaErrorCode,
  AbhaErrorItem,
  AbhaErrorResponse,
  AbhaIdentifierType,
  LinkedPatient,
} from "@/types/abdm/abha";

export const ABHA_CONSENT: AbhaConsent = {
  accepted: true,
  version: ABHA_CONSENT_VERSION,
};

export const ABHA_OTP_LENGTH = 6;

/**
 * Errors land on the active journey step instead of a global toast. 401s still
 * go to the global handler so an expired session redirects as usual.
 */
export const abhaSilent = (res: Response) => res.status !== 401;

export const ABHA_COUNTRY_CODE = "+91";

export const ABHA_IDENTIFIER_LABELS: Record<AbhaIdentifierType, string> = {
  mobile: "abha_identifier__mobile",
  aadhaar: "abha_identifier__aadhaar",
  abha_number: "abha_identifier__abha_number",
  abha_address: "abha_identifier__abha_address",
};

export const ABHA_AUTH_METHOD_LABELS: Record<AbhaAuthMethod, string> = {
  aadhaar_otp: "abha_auth_method__aadhaar_otp",
  mobile_otp: "abha_auth_method__mobile_otp",
};

// Local validation, shared with the backend (contract §5.1). Nothing is sent
// to CARE when these fail.

export const normalizeAadhaar = (value: string) => value.replace(/\s+/g, "");

export const isValidAadhaar = (value: string) =>
  /^\d{12}$/.test(normalizeAadhaar(value));

export const maskAadhaar = (value: string) =>
  `XXXX XXXX ${normalizeAadhaar(value).slice(-4)}`;

export const normalizeMobile = (value: string) => {
  const compact = value.replace(/[\s-]/g, "");
  return compact.startsWith(ABHA_COUNTRY_CODE)
    ? compact.slice(ABHA_COUNTRY_CODE.length)
    : compact;
};

export const isValidMobile = (value: string) =>
  /^[6-9]\d{9}$/.test(normalizeMobile(value));

/** Returns the `XX-XXXX-XXXX-XXXX` form, or null if it is not 14 digits */
export const normalizeAbhaNumber = (value: string) => {
  const digits = value.replace(/[\s-]/g, "");
  if (!/^\d{14}$/.test(digits)) {
    return null;
  }
  return `${digits.slice(0, 2)}-${digits.slice(2, 6)}-${digits.slice(6, 10)}-${digits.slice(10)}`;
};

/** Login accepts the address with or without the `@suffix` */
export const isValidAbhaAddressForLogin = (value: string) =>
  /^[^\s@]+(@[^\s@]+)?$/.test(value.trim());

/**
 * Rules for a new ABHA address (entered without the suffix). Returns the i18n
 * key of the first broken rule, or null when the address is valid.
 */
export const getNewAbhaAddressError = (value: string) => {
  if (value.includes("@")) {
    return "abha_address_rule_no_suffix";
  }
  if (value.length < 8 || value.length > 18) {
    return "abha_address_rule_length";
  }
  if (
    !/^[A-Za-z0-9._]+$/.test(value) ||
    (value.match(/\./g) ?? []).length > 1 ||
    (value.match(/_/g) ?? []).length > 1
  ) {
    return "abha_address_rule_characters";
  }
  if (/^[._]/.test(value) || /[._]$/.test(value)) {
    return "abha_address_rule_edges";
  }
  if (/^\d/.test(value)) {
    return "abha_address_rule_start";
  }
  return null;
};

/** Desk phone numbers are prefilled only when they are Indian (+91) numbers */
export const getDeskMobile = (phone?: string | null) => {
  if (!phone?.startsWith(ABHA_COUNTRY_CODE)) {
    return undefined;
  }
  const mobile = normalizeMobile(phone);
  return isValidMobile(mobile) ? mobile : undefined;
};

export const toIndianPhoneNumber = (mobile: string) =>
  `${ABHA_COUNTRY_CODE}${normalizeMobile(mobile)}`;

/**
 * Route to CARE's existing patient verification page for a linked patient.
 * The page needs the phone number and year of birth, so there is no route
 * when either is unknown.
 */
export const getLinkedPatientUrl = (
  facilityId: string,
  patient: LinkedPatient,
) => {
  if (!patient.phone_number || !patient.year_of_birth) {
    return undefined;
  }
  const params = new URLSearchParams({
    phone_number: patient.phone_number,
    year_of_birth: String(patient.year_of_birth),
    partial_id: patient.partial_id,
  });
  return `/facility/${facilityId}/patients/home?${params.toString()}`;
};

export const getAbhaPhotoSrc = (photo?: string | null) =>
  photo ? `data:image/jpeg;base64,${photo}` : undefined;

export const blobToDataUrl = (blob: Blob) =>
  new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });

/** Same download pattern as `useFileManager` */
export const downloadBlob = (blob: Blob, fileName: string) => {
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  window.URL.revokeObjectURL(url);
  document.body.removeChild(anchor);
};

export type AbhaUiErrorCode = AbhaErrorCode | "network_error" | "unknown";

export interface AbhaUiError {
  code: AbhaUiErrorCode;
  message: string;
  /** Best-effort field name, used to show the error beside the input */
  field?: string;
  status?: number;
  /** Seconds to wait, with `resend_cooldown` */
  retryAfter?: number;
  linkedPatient?: LinkedPatient;
  /** When the error was received, used for the resend countdown */
  receivedAt: number;
}

const CODE_MESSAGE_KEYS: Partial<Record<AbhaErrorCode, string>> = {
  invalid_aadhaar: "abha_error_invalid_aadhaar",
  invalid_mobile: "abha_error_invalid_mobile",
  invalid_abha_number: "abha_error_invalid_abha_number",
  invalid_abha_address: "abha_error_invalid_abha_address",
  consent_required: "abha_error_consent_required",
  transaction_expired: "abha_error_transaction_expired",
  invalid_state: "abha_error_invalid_state",
  patient_already_has_abha: "abha_error_patient_already_has_abha",
  card_unavailable: "abha_error_card_unavailable",
  resend_limit_reached: "abha_error_resend_limit_reached",
  rate_limited: "abha_error_rate_limited",
  abdm_unavailable: "abha_error_abdm_unavailable",
  abdm_auth_failed: "abha_error_abdm_auth_failed",
  abdm_timeout: "abha_error_abdm_timeout",
  abdm_disabled: "abha_error_abdm_disabled",
};

/** Codes after which the journey cannot continue and must start again */
export const ABHA_RESTART_CODES: AbhaUiErrorCode[] = [
  "transaction_expired",
  "invalid_state",
];

interface ValidationErrorItem {
  type?: string;
  msg?: string | Record<string, string>;
  loc?: (string | number)[];
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isAbhaErrorItem = (value: unknown): value is AbhaErrorItem =>
  isRecord(value) && value.type === "abdm_error" && "code" in value;

const getValidationMessage = (item: ValidationErrorItem) => {
  if (typeof item.msg === "string") {
    return item.msg;
  }
  if (item.msg) {
    return Object.values(item.msg)[0];
  }
  return undefined;
};

/**
 * Normalises a failed ABHA call (contract §5.1 errors, CARE's validation
 * errors, DRF errors and network failures) into one shape for the UI.
 */
export function parseAbhaError(error: unknown, t: TFunction): AbhaUiError {
  const receivedAt = Date.now();

  if (!(error instanceof HTTPError)) {
    return {
      code: "network_error",
      message: t("abha_error_network"),
      receivedAt,
    };
  }

  const body = isRecord(error.cause) ? error.cause : undefined;
  const items = Array.isArray(body?.errors) ? (body.errors as unknown[]) : [];
  const abdmError = items.find(isAbhaErrorItem);

  if (abdmError) {
    const response = body as unknown as AbhaErrorResponse;
    const retryAfter = abdmError.retry_after ?? response.retry_after;
    const linkedPatient = abdmError.linked_patient ?? response.linked_patient;
    const code = abdmError.code;

    let message: string;
    if (code === "resend_cooldown") {
      message = retryAfter
        ? t("abha_error_resend_cooldown", { seconds: retryAfter })
        : t("abha_error_resend_cooldown_generic");
    } else if (code === "abha_already_linked") {
      message = linkedPatient
        ? t("abha_already_linked_title", {
            name: linkedPatient.name,
            partial_id: linkedPatient.partial_id,
          })
        : t("abha_error_abha_already_linked");
    } else {
      const key = CODE_MESSAGE_KEYS[code];
      message = key ? t(key) : abdmError.msg || t("something_went_wrong");
    }

    return {
      code,
      message,
      field: abdmError.field ?? undefined,
      status: error.status,
      retryAfter,
      linkedPatient,
      receivedAt,
    };
  }

  const validationError = items.find(isRecord) as
    ValidationErrorItem | undefined;
  const validationMessage =
    validationError && getValidationMessage(validationError);
  const detail = typeof body?.detail === "string" ? body.detail : undefined;
  const loc = validationError?.loc;

  return {
    code: "unknown",
    message: validationMessage || detail || t("something_went_wrong"),
    field: loc?.length ? String(loc[loc.length - 1]) : undefined,
    status: error.status,
    receivedAt,
  };
}

import { Loader2Icon } from "lucide-react";
import { useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

import { Avatar } from "@/components/Common/Avatar";

import { AbhaAccount } from "@/types/abdm/abha";

import { AbhaKycBadge } from "./AbhaProfileSummary";
import { AbhaStepHeading } from "./AbhaStepHeading";
import { getAbhaPhotoSrc } from "./utils";

/** Choose an account (screen 4); one mobile can hold up to 6 ABHAs */
export function AbhaAccountStep({
  accounts,
  isPending,
  onSelect,
}: {
  accounts: AbhaAccount[];
  isPending: boolean;
  onSelect: (abhaNumber: string) => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const [selected, setSelected] = useState(accounts[0]?.abha_number ?? "");

  return (
    <div className="flex flex-col gap-5" data-testid="abha-account-step">
      <AbhaStepHeading
        title={t("abha_account_title")}
        description={t("abha_account_description", { count: accounts.length })}
      />

      <RadioGroup
        value={selected}
        onValueChange={setSelected}
        disabled={isPending}
        aria-label={t("abha_account_title")}
        className="gap-2"
      >
        {accounts.map((account) => {
          const itemId = `${id}-${account.abha_number}`;
          const linkedPatient = account.linked_patient;
          return (
            <label
              key={account.abha_number}
              htmlFor={itemId}
              className={cn(
                "flex cursor-pointer items-start gap-3 rounded-md border p-3",
                selected === account.abha_number
                  ? "border-primary-500 bg-primary-50"
                  : "border-gray-200 bg-white hover:border-primary-300",
              )}
              data-testid="abha-account-option"
            >
              <RadioGroupItem
                id={itemId}
                value={account.abha_number}
                className="mt-1"
              />
              <Avatar
                name={account.name}
                imageUrl={getAbhaPhotoSrc(account.photo)}
                className="size-12 shrink-0"
              />
              <div className="flex min-w-0 flex-1 flex-col gap-1 text-sm">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-semibold text-gray-900">
                    {account.name}
                  </span>
                  <AbhaKycBadge verified={account.kyc_verified} />
                </div>
                <span className="text-gray-900">{account.abha_number}</span>
                {account.preferred_abha_address && (
                  <span className="break-all text-gray-700">
                    {account.preferred_abha_address}
                  </span>
                )}
                <span className="text-gray-600">
                  {[
                    account.gender && t(`GENDER__${account.gender}`),
                    account.year_of_birth &&
                      t("abha_year_of_birth_value", {
                        year: account.year_of_birth,
                      }),
                  ]
                    .filter(Boolean)
                    .join(" · ")}
                </span>
                {linkedPatient && (
                  <Badge
                    variant={
                      linkedPatient.is_current_patient ? "green" : "yellow"
                    }
                    size="xs"
                    className="w-fit"
                    data-testid="abha-account-linked"
                  >
                    {linkedPatient.is_current_patient
                      ? t("abha_linked_to_this_patient")
                      : t("abha_already_linked_to", {
                          name: linkedPatient.name,
                          partial_id: linkedPatient.partial_id,
                        })}
                  </Badge>
                )}
              </div>
            </label>
          );
        })}
      </RadioGroup>

      <div className="flex justify-end">
        <Button
          variant="primary"
          disabled={isPending || !selected}
          onClick={() => onSelect(selected)}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("continue")}
        </Button>
      </div>
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Loader2Icon, RefreshCwIcon } from "lucide-react";
import { SyntheticEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Skeleton } from "@/components/ui/skeleton";

import query from "@/Utils/request/query";
import abhaApi from "@/types/abdm/abhaApi";

import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { abhaSilent, getNewAbhaAddressError, parseAbhaError } from "./utils";

const CUSTOM = "__custom__";

const ADDRESS_RULES = [
  "abha_address_rule_length",
  "abha_address_rule_characters",
  "abha_address_rule_edges",
  "abha_address_rule_start",
  "abha_address_rule_no_suffix",
];

/**
 * Choose an address (screen 6): suggestions from ABDM plus a free field.
 * A taken address shows its error and keeps the suggestions on screen.
 */
export function AbhaAddressStep({
  transactionId,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  transactionId: string;
  /** Server error for the address */
  error?: string;
  isPending: boolean;
  /** The address without the suffix */
  onSubmit: (address: string) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const customId = `${id}-custom`;
  const errorId = `${id}-error`;
  const rulesId = `${id}-rules`;

  const suggestionsQuery = useQuery({
    queryKey: ["abha", "address-suggestions", transactionId],
    queryFn: query(abhaApi.addressSuggestions, {
      queryParams: { transaction_id: transactionId },
      silent: abhaSilent,
    }),
    retry: false,
    staleTime: Infinity,
  });

  const suggestions = suggestionsQuery.data?.suggestions ?? [];
  const suffix = suggestionsQuery.data?.suffix ?? "";

  const [choice, setChoice] = useState<string>();
  const [custom, setCustom] = useState("");
  const [localError, setLocalError] = useState<string>();

  const selected = choice ?? suggestions[0] ?? CUSTOM;
  const isCustom = selected === CUSTOM;
  const errorMessage = localError ?? error;
  const suggestionsError = suggestionsQuery.error
    ? parseAbhaError(suggestionsQuery.error, t)
    : null;

  const clearErrors = () => {
    setLocalError(undefined);
    onClearError();
  };

  const handleSubmit = (event: SyntheticEvent) => {
    event.preventDefault();
    if (isPending) {
      return;
    }
    if (!isCustom) {
      onSubmit(selected);
      return;
    }
    const address = custom.trim();
    const ruleError = getNewAbhaAddressError(address);
    if (ruleError) {
      setLocalError(t(ruleError));
      return;
    }
    onSubmit(address);
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-address-step"
    >
      <AbhaStepHeading
        title={t("abha_address_title")}
        description={t("abha_address_description")}
      />

      {suggestionsQuery.isLoading && (
        <div className="flex flex-col gap-2">
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
        </div>
      )}

      {suggestionsError && (
        <Alert variant="destructive">
          <AlertDescription className="flex flex-wrap items-center justify-between gap-2">
            <span>{suggestionsError.message}</span>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => suggestionsQuery.refetch()}
            >
              <RefreshCwIcon />
              {t("try_again")}
            </Button>
          </AlertDescription>
        </Alert>
      )}

      {!suggestionsQuery.isLoading && (
        <RadioGroup
          value={selected}
          onValueChange={(value) => {
            setChoice(value);
            clearErrors();
          }}
          disabled={isPending}
          aria-label={t("abha_address_title")}
          className="gap-2"
          data-testid="abha-address-options"
        >
          {suggestions.map((suggestion) => {
            const itemId = `${id}-${suggestion}`;
            return (
              <label
                key={suggestion}
                htmlFor={itemId}
                className={cn(
                  "flex cursor-pointer items-center gap-3 rounded-md border p-3 text-sm",
                  selected === suggestion
                    ? "border-primary-500 bg-primary-50"
                    : "border-gray-200 bg-white hover:border-primary-300",
                )}
                data-testid="abha-address-suggestion"
              >
                <RadioGroupItem id={itemId} value={suggestion} />
                <span className="break-all font-medium text-gray-900">
                  {suggestion}
                  <span className="text-gray-500">{suffix}</span>
                </span>
              </label>
            );
          })}

          <div
            className={cn(
              "flex flex-col gap-3 rounded-md border p-3",
              isCustom
                ? "border-primary-500 bg-primary-50"
                : "border-gray-200 bg-white",
            )}
          >
            <label
              htmlFor={`${id}-custom-option`}
              className="flex cursor-pointer items-center gap-3 text-sm font-medium text-gray-900"
            >
              <RadioGroupItem id={`${id}-custom-option`} value={CUSTOM} />
              {t("abha_address_custom")}
            </label>

            <div className="flex flex-col gap-2">
              <Label htmlFor={customId} className="sr-only">
                {t("abha_address_custom")}
              </Label>
              <div className="flex items-center gap-2">
                <Input
                  id={customId}
                  value={custom}
                  autoComplete="off"
                  disabled={isPending}
                  placeholder={t("abha_address_custom_placeholder")}
                  aria-invalid={isCustom && !!errorMessage}
                  aria-describedby={cn(rulesId, errorMessage && errorId)}
                  data-testid="abha-address-custom-input"
                  onFocus={() => setChoice(CUSTOM)}
                  onChange={(event) => {
                    setChoice(CUSTOM);
                    setCustom(event.target.value);
                    clearErrors();
                  }}
                />
                {suffix && (
                  <span
                    className="shrink-0 text-sm font-medium text-gray-700"
                    data-testid="abha-address-suffix"
                  >
                    {suffix}
                  </span>
                )}
              </div>
              <ul
                id={rulesId}
                className="list-inside list-disc text-xs text-gray-600"
                data-testid="abha-address-rules"
              >
                {ADDRESS_RULES.map((rule) => (
                  <li key={rule}>{t(rule)}</li>
                ))}
              </ul>
            </div>
          </div>
        </RadioGroup>
      )}

      <AbhaFieldError id={errorId} message={errorMessage} />

      <div className="flex justify-end">
        <Button
          type="submit"
          variant="primary"
          disabled={isPending || suggestionsQuery.isLoading}
        >
          {isPending && <Loader2Icon className="animate-spin" />}
          {t("abha_create_address")}
        </Button>
      </div>
    </form>
  );
}

import { Loader2Icon } from "lucide-react";
import { SyntheticEvent, useId, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { AbhaConsentPanel } from "./AbhaConsentPanel";
import { AbhaProvenanceBadge } from "./AbhaProvenanceBadge";
import { AbhaFieldError, AbhaStepHeading } from "./AbhaStepHeading";
import { AbhaFacts } from "./useAbhaFacts";
import { ABHA_COUNTRY_CODE, isValidAadhaar, normalizeAadhaar } from "./utils";

export interface AbhaCreateAadhaarInput {
  /** Normalised, only when the journey holds no Aadhaar */
  aadhaar?: string;
}

/**
 * Create with Aadhaar, after "No ABHA found". It asks only for the facts the
 * journey does not hold: the Aadhaar number and, if not yet given, consent.
 */
export function AbhaCreateAadhaarStep({
  facts,
  needsAadhaar,
  needsConsent,
  error,
  isPending,
  onSubmit,
  onClearError,
}: {
  facts: AbhaFacts;
  needsAadhaar: boolean;
  needsConsent: boolean;
  /** Server error for the Aadhaar number */
  error?: string;
  isPending: boolean;
  onSubmit: (input: AbhaCreateAadhaarInput) => void;
  onClearError: () => void;
}) {
  const { t } = useTranslation();
  const id = useId();
  const inputId = `${id}-aadhaar`;
  const errorId = `${id}-error`;

  const [aadhaar, setAadhaar] = useState("");
  const [consented, setConsented] = useState(!needsConsent);
  const [localError, setLocalError] = useState<string>();

  const errorMessage = localError ?? error;
  const blocked = !consented;

  const handleSubmit = (event: SyntheticEvent) => {
    event.preventDefault();
    if (blocked || isPending) {
      return;
    }
    if (!needsAadhaar) {
      onSubmit({});
      return;
    }
    if (!isValidAadhaar(aadhaar)) {
      setLocalError(t("abha_error_invalid_aadhaar"));
      return;
    }
    onSubmit({ aadhaar: normalizeAadhaar(aadhaar) });
  };

  return (
    <form
      className="flex flex-col gap-5"
      onSubmit={handleSubmit}
      noValidate
      data-testid="abha-create-aadhaar-step"
    >
      <AbhaStepHeading
        title={t("abha_create_title")}
        description={t("abha_create_description")}
      />

      {needsConsent && (
        <AbhaConsentPanel checked={consented} onCheckedChange={setConsented} />
      )}

      {needsAadhaar && (
        <div className="flex flex-col gap-2">
          <Label htmlFor={inputId}>{t("abha_identifier__aadhaar")}</Label>
          <Input
            id={inputId}
            value={aadhaar}
            inputMode="numeric"
            autoComplete="off"
            disabled={isPending || blocked}
            placeholder={t("abha_identifier_placeholder__aadhaar")}
            aria-invalid={!!errorMessage}
            aria-describedby={errorMessage ? errorId : undefined}
            data-testid="abha-aadhaar-input"
            onChange={(event) => {
              setAadhaar(event.target.value);
              setLocalError(undefined);
              onClearError();
            }}
          />
          <AbhaFieldError id={errorId} message={errorMessage} />
        </div>
      )}
      {!needsAadhaar && <AbhaFieldError message={errorMessage} />}

      {facts.mobile && (
        <div
          className="flex flex-col gap-1"
          data-testid="abha-create-held-mobile"
        >
          <span className="text-sm font-medium text-gray-900">
            {t("abha_communication_mobile")}
          </span>
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-sm font-semibold text-gray-900">
              {`${ABHA_COUNTRY_CODE} ${facts.mobile.value}`}
            </span>
            <AbhaProvenanceBadge source={facts.mobile.source} />
          </div>
