test.use({ storageState: "tests/.auth/user.json" });

const AADHAAR_OTP_MESSAGE =
  "OTP sent to Aadhaar registered mobile number ending with ******1234";

/** Short enough to wait out in a test; CARE sends 60 seconds */
const RESEND_COOLDOWN_SECONDS = 3;

/**
 * Opens patient registration. `mobile` is passed the way patient search
 * passes it, as `?phone_number=+91…`.
 */
async function openRegistration(
  page: Page,
  facilityId: string,
  mobile?: string,
) {
  const query = mobile
    ? `?${new URLSearchParams({ phone_number: `+91${mobile}` })}`
    : "";
  await page.goto(`/facility/${facilityId}/patient/create${query}`);
  await expect(page.getByTestId("abha-registration-journey")).toBeVisible();
  return page.getByTestId("abha-journey");
}

/** Mobile login: Identify → OTP → Result */
async function verifyWithMobile(journey: Locator) {
  await journey.getByRole("button", { name: "Send OTP", exact: true }).click();
  await submitAbhaOtp(journey);
  const result = journey.getByTestId("abha-result-step");
  await expect(result).toBeVisible();
  return result;
}

const formItem = (page: Page, field: Locator) =>
  page.locator('[data-slot="form-item"]').filter({ has: field });

/** Picks the first option at each level of the cascading geo organization */
async function selectGeoOrganization(page: Page) {
  const additionalDetails = page.getByRole("button", {
    name: "Additional Details",
  });
  if (
    (await additionalDetails.textContent())?.toLowerCase().includes("optional")
  ) {
    await additionalDetails.click();
  }

  const comboboxes = page
    .getByRole("region", { name: "Additional Details" })
    .getByRole("combobox");
  await comboboxes.first().waitFor({ state: "visible" });

  let previousCount = 0;
  for (let level = 0; level < 10; level++) {
    const count = await comboboxes.count();
    if (count === previousCount) {
      break;
    }
    await comboboxes.nth(count - 1).click();
    await page.getByRole("option").first().click();
    previousCount = count;
    try {
      await comboboxes.nth(count).waitFor({ state: "visible", timeout: 3000 });
    } catch {
      break;
    }
  }
}

/** Registers the patient and returns the id CARE gave it */
async function registerPatient(page: Page) {
  await selectGeoOrganization(page);
  const created = page.waitForResponse(
    (response) =>
      response.request().method() === "POST" &&
      new URL(response.url()).pathname === "/api/v1/patient/",
  );
  await page.getByRole("button", { name: /register patient/i }).click();
  const response = await created;
  expect(response.ok()).toBe(true);
  const patient: { id: string } = await response.json();
  return patient.id;
}

