        `An OTP has been sent to ${maskMobile(mobile)}.`,
      );
    });

    await test.step("Resend waits for the countdown", async () => {
      await expect(resend).toBeDisabled();
      await expect(resend).toHaveText(countdown);
      await expect(resendArea).toContainText("2 resends left");
      await expect(resend).toBeEnabled();
      await expect(resend).toHaveText("Resend OTP");
      await resend.click();
      await expect(resendArea).toContainText("1 resend left");
      await expect(resend).toBeDisabled();
    });

    await test.step("A 429 shows how long to wait", async () => {
      await expect(resend).toBeEnabled();
      await resend.click();
      await expect(resendArea.getByTestId("abha-field-error")).toHaveText(
        `Please wait ${RESEND_COOLDOWN_SECONDS} seconds before requesting another OTP.`,
      );
      await expect(resend).toBeDisabled();
      await expect(resend).toHaveText(countdown);
    });

    await test.step("No resend is offered after the last one", async () => {
      await expect(resend).toBeEnabled();
      await resend.click();
      await expect(resendArea).toHaveText("No resends left");
      await expect(resend).toHaveCount(0);
      expect(abha.calls("resendOtp").map((call) => call.body)).toEqual([
