import { expect, Page, test } from "@playwright/test";
import {
  ABDM_DISABLED_REASON,
  abhaError,
  buildLinkedPatient,
  buildPatientAbha,
  cardResponse,
  getUnmockedAbhaCalls,
  isAbdmEnabled,
  linkedPatientUrl,
  mockAbha,
  otpSentJourney,
  PatientAbhaFixture,
  randomMobile,
  respond,
  submitAbhaOtp,
  TRANSACTION_ID,
  verifiedJourney,
} from "tests/helper/abha";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

interface PatientRecord {
  id: string;
  name: string;
  phone_number: string;
}

/** The patient's phone, as the journey prefills it: +91 numbers only */
const getRecordMobile = (phone: string) =>
  phone.match(/^\+91([6-9]\d{9})$/)?.[1];

/** Opens the patient's Demography tab and returns the patient CARE sent */
async function openDemography(
  page: Page,
  facilityId: string,
  patientId: string,
) {
  const patientResponse = page.waitForResponse(
    (response) =>
      response.request().method() === "GET" &&
      new URL(response.url()).pathname === `/api/v1/patient/${patientId}/`,
  );
  await page.goto(`/facility/${facilityId}/patient/${patientId}/demography`);
  const patient: PatientRecord = await (await patientResponse).json();
  const section = page.getByTestId("patient-abha-section");
  await expect(section).toBeVisible();
  return { patient, section };
}

test.describe("ABHA on the patient's Demography tab", () => {
  test.skip(!isAbdmEnabled(), ABDM_DISABLED_REASON);

  let facilityId: string;
  let patientId: string;

  test.beforeEach(() => {
    facilityId = getFacilityId();
    patientId = getPatientId();
  });

  test.afterEach(({ page }) => {
    expect(getUnmockedAbhaCalls(page)).toEqual([]);
  });

  test("links an ABHA to a patient after comparing the details", async ({
    page,
  }) => {
    const linked = buildPatientAbha();
