  try {
    console.log("🔄 Restoring database from snapshot...");
    const output = execFileSync("bash", [scriptPath, "restore"], {
      stdio: "pipe",
      timeout: 30000,
      encoding: "utf-8",
    });
    if (output) console.log(output.trim());
    console.log("✅ Database restored to clean state");
  } catch (error) {
    const stderr =
