          setField("permanent_address", snapshot.address);
        }
      }
      if (isUnchanged("pincode")) setField("pincode", snapshot.pincode);
    }

    setSnapshot(null);
    abha.setPrefill({});
    abha.setLink(null);
  };

  const openJourney = () => {
    setJourneyKey((key) => key + 1);
    abha.setJourneyOpen(true);
  };

  if (abha.journeyOpen) {
    return (
      <div
        className="mb-6 flex flex-col gap-4 rounded-md bg-white p-6 shadow"
        data-testid="abha-registration-journey"
      >
        <div className="flex flex-col gap-1">
          <h5 className="text-lg font-semibold">
            {t("abha_registration_title")}
          </h5>
          <p className="text-sm text-gray-700">
            {t("abha_registration_description")}
          </p>
        </div>
        <AbhaJourney
          key={journeyKey}
          mode="register"
          facilityId={facilityId}
          initialFacts={getInitialFacts()}
          onComplete={handleComplete}
          onExit={handleExit}
        />
      </div>
    );
  }

  if (abha.link) {
    return (
      <div
        className="mb-6 flex flex-col gap-3 rounded-md border border-primary-200 bg-primary-50 p-4 sm:flex-row sm:items-center sm:justify-between"
        data-testid="abha-registration-summary"
      >
        <div className="flex items-start gap-3">
          <IdCardIcon className="mt-0.5 size-5 shrink-0 text-primary-700" />
          <div className="flex flex-col gap-1 text-sm">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-semibold text-gray-900">
                {t("abha_registration_title")}
              </span>
              <Badge
                variant={abha.link.kycVerified ? "green" : "yellow"}
                size="xs"
              >
                {abha.link.kycVerified
                  ? t("abha_kyc_verified")
                  : t("abha_kyc_not_verified")}
              </Badge>
            </div>
            {abha.link.abhaNumber && (
              <span data-testid="abha-registration-number">
                {t("abha_number")}: {abha.link.abhaNumber}
              </span>
            )}
            {abha.link.abhaAddress && (
              <span
                className="break-all"
                data-testid="abha-registration-address"
              >
                {t("abha_address")}: {abha.link.abhaAddress}
              </span>
            )}
            <span className="text-gray-600">{t("abha_will_be_linked")}</span>
          </div>
        </div>
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={handleRemove}
          data-testid="abha-registration-remove"
        >
          <XIcon />
          {t("abha_remove")}
        </Button>
      </div>
    );
  }

  return (
    <div
      className="mb-6 flex flex-col gap-3 rounded-md border border-gray-200 bg-white p-4 sm:flex-row sm:items-center sm:justify-between"
      data-testid="abha-registration-add"
    >
      <p className="text-sm text-gray-700">{t("abha_add_prompt")}</p>
      <Button type="button" variant="outline" size="sm" onClick={openJourney}>
        <PlusIcon />
        {t("abha_add")}
      </Button>
    </div>
  );
}

