// THROWAWAY real-stack check (no page.route). Do not commit; delete after use.
import { expect, Locator, Page, test } from "@playwright/test";
import * as fs from "fs";
import { ABHA_CONSENT_AGREE, submitAbhaOtp } from "tests/helper/abha";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

const LOG =
  "/Users/jacob/.copilot/session-state/b135e26f-37b6-4cbc-87b8-fd253a161bf4/files/logs/realstack-traffic.jsonl";

function recordTraffic(page: Page, scenario: string) {
  page.on("response", async (response) => {
    const url = new URL(response.url());
    if (!/\/api\/v1\/(abdm\/abha\/|patient\/[^/]+\/abha\/)/.test(url.pathname))
      return;
    const request = response.request();
    const type = response.headers()["content-type"] ?? "";
    let body: unknown;
    try {
      body = type.includes("json")
        ? await response.json()
        : `<${type} ${(await response.body()).length} bytes>`;
    } catch (e) {
      body = `<unreadable: ${e}>`;
    }
    fs.appendFileSync(
      LOG,
      JSON.stringify({
        scenario,
        method: request.method(),
        path: url.pathname + url.search,
        request: request.postDataJSON?.() ?? null,
        status: response.status(),
        cacheControl: response.headers()["cache-control"],
        body,
      }) + "\n",
    );
  });
}

const formItem = (page: Page, field: Locator) =>
  page.locator('[data-slot="form-item"]').filter({ has: field });

async function selectGeoOrganization(page: Page) {
  const additionalDetails = page.getByRole("button", {
    name: "Additional Details",
  });
  if (
    (await additionalDetails.textContent())?.toLowerCase().includes("optional")
  ) {
    await additionalDetails.click();
  }
  const comboboxes = page
    .getByRole("region", { name: "Additional Details" })
    .getByRole("combobox");
  await comboboxes.first().waitFor({ state: "visible" });
  let previousCount = 0;
  for (let level = 0; level < 10; level++) {
    const count = await comboboxes.count();
    if (count === previousCount) break;
    await comboboxes.nth(count - 1).click();
    await page.getByRole("option").first().click();
    previousCount = count;
    try {
      await comboboxes.nth(count).waitFor({ state: "visible", timeout: 3000 });
    } catch {
      break;
    }
  }
}

/** Completes the remaining required fields, registers and returns the new patient's id */
async function registerPatient(page: Page) {
  const address = page.getByRole("textbox", { name: "Address" });
  if (!(await address.inputValue())) {
    await address.fill("12 Real Stack Road");
  }
  await selectGeoOrganization(page);
  const created = page.waitForResponse(
    (response) =>
      response.request().method() === "POST" &&
      new URL(response.url()).pathname === "/api/v1/patient/",
  );
  await page.getByRole("button", { name: /register patient/i }).click();
  const response = await created;
  expect(response.ok(), await response.text()).toBe(true);
  return ((await response.json()) as { id: string }).id;
}

async function expectLinkedOnDemography(
  page: Page,
  facilityId: string,
  patientId: string,
  abhaNumber: string,
) {
  await page.goto(`/facility/${facilityId}/patient/${patientId}/demography`);
  const section = page.getByTestId("patient-abha-section");
  await expect(section.getByTestId("abha-section-number")).toHaveText(
    abhaNumber,
  );
  return section;
}

test.describe("real stack as admin", () => {
  test.use({ storageState: "tests/.auth/user.json" });
  test.describe.configure({ mode: "default" });

  test("(a)+(c) Demography: wrong OTP, verify by mobile, link, card, unlink", async ({
    page,
  }) => {
    recordTraffic(page, "a");
    const facilityId = getFacilityId();
    const patientId = getPatientId();
    await page.goto(`/facility/${facilityId}/patient/${patientId}/demography`);
    const section = page.getByTestId("patient-abha-section");
    await expect(section.getByTestId("abha-not-linked")).toBeVisible();

    await section.getByTestId("abha-section-link").click();
    const sheet = page.getByTestId("abha-section-sheet");
    const journey = sheet.getByTestId("abha-journey");
    const identify = journey.getByTestId("abha-identify-step");
    await identify
      .getByRole("radio", { name: "Mobile Number", exact: true })
      .click();
    await identify.getByTestId("abha-identifier-input").fill("9999999991");
    await identify
      .getByRole("button", { name: "Send OTP", exact: true })
      .click();

    const otpStep = journey.getByTestId("abha-otp-step");
    await expect(otpStep).toBeVisible();
    console.log("OTP description:", await otpStep.innerText());

    // (c) wrong OTP is shown on the OTP field and clears it
    await submitAbhaOtp(journey, "000000");
    const otpError = otpStep.getByTestId("abha-field-error");
    await expect(otpError).toBeVisible();
    console.log("Wrong OTP message:", await otpError.innerText());
    await expect(journey.getByTestId("abha-journey-error")).toHaveCount(0);
    await expect(otpStep.getByTestId("abha-otp-input")).toHaveValue("");

    await submitAbhaOtp(journey);
    const result = journey.getByTestId("abha-result-step");
    const account = journey.getByTestId("abha-account-step");
    await expect(result.or(account)).toBeVisible();
    if (await account.isVisible()) {
      await account.getByRole("button", { name: "Continue", exact: true }).click();
    }
    await expect(result.getByTestId("abha-profile-number")).toHaveText(
      "91-1111-1111-1111",
    );
    await expect(result.getByTestId("abha-profile-address")).toHaveText(
      "ravi.kumar@sbx",
    );
    await expect(result.getByTestId("abha-link-comparison")).toBeVisible();
    await result.getByRole("button", { name: "Link to this patient" }).click();
    await expectToast(page, "ABHA linked to the patient");
    await expect(sheet).toBeHidden();
    await expect(section.getByTestId("abha-section-number")).toHaveText(
      "91-1111-1111-1111",
    );

    await page.reload();
    await expect(section.getByTestId("abha-section-number")).toHaveText(
      "91-1111-1111-1111",
    );
    await expect(section.getByTestId("abha-section-address")).toHaveText(
      "ravi.kumar@sbx",
    );
    console.log("Section after reload:", await section.innerText());

    // Card through re-verification
    await section.getByTestId("abha-section-view-card").click();
    const method = journey.getByTestId("abha-method-step");
    await expect(method.getByTestId("abha-method-identifier")).toHaveText(
      "91-1111-1111-1111",
    );
    await method
      .getByRole("radio", {
        name: "OTP on the mobile number linked with ABHA",
        exact: true,
      })
      .click();
    await method.getByRole("button", { name: "Send OTP", exact: true }).click();
    await submitAbhaOtp(journey);
    const card = page.getByTestId("abha-card-dialog");
    const image = card.getByRole("img", { name: "ABHA Card" });
    await expect(image).toBeVisible();
    await expect
      .poll(() =>
        image.evaluate((element: HTMLImageElement) => element.naturalWidth),
      )
      .toBeGreaterThan(0);
    console.log(
      "Card image size:",
      await image.evaluate(
        (element: HTMLImageElement) =>
          `${element.naturalWidth}x${element.naturalHeight}`,
      ),
    );
    const download = page.waitForEvent("download");
    await card.getByRole("button", { name: "Download" }).click();
    console.log("Card download:", (await download).suggestedFilename());
    await page.keyboard.press("Escape");
    await expect(card).toBeHidden();
    await journey.getByRole("button", { name: "Done", exact: true }).click();
    await expect(sheet).toBeHidden();

    // Unlink
    await section.getByTestId("abha-section-unlink").click();
    await page
      .getByRole("alertdialog")
      .getByRole("button", { name: /^Unlink ABHA/ })
      .click();
    await expectToast(page, "ABHA unlinked");
    await expect(section.getByTestId("abha-not-linked")).toBeVisible();
    await page.reload();
    await expect(section.getByTestId("abha-not-linked")).toBeVisible();
  });

  test("(b) Registration: create via Aadhaar, pick an address, register, linked", async ({
    page,
  }) => {
    recordTraffic(page, "b");
    const facilityId = getFacilityId();
    await page.goto(`/facility/${facilityId}/patient/create`);
    const journey = page.getByTestId("abha-journey");
    const identify = journey.getByTestId("abha-identify-step");
    await identify
      .getByRole("radio", { name: "Aadhaar Number", exact: true })
      .click();
    await identify
      .getByTestId("abha-consent-panel")
      .getByRole("checkbox", { name: ABHA_CONSENT_AGREE })
      .check();
    await identify.getByTestId("abha-identifier-input").fill("9999 4444 4444");
    await identify
      .getByRole("button", { name: "Send OTP", exact: true })
      .click();

    const noAccount = journey.getByTestId("abha-no-account-step");
    const otpStep = journey.getByTestId("abha-otp-step");
    await expect(noAccount.or(otpStep)).toBeVisible();
    if (await otpStep.isVisible()) {
      console.log("Aadhaar login OTP step:", await otpStep.innerText());
      await submitAbhaOtp(journey);
    }
    await expect(noAccount).toBeVisible();
    console.log("No-account step:", await noAccount.innerText());
    await noAccount
      .getByRole("button", { name: "Create ABHA with Aadhaar" })
      .click();

    await expect(otpStep).toBeVisible();
    console.log("Enrol OTP step:", await otpStep.innerText());
    await otpStep
      .getByTestId("abha-communication-mobile-input")
      .fill("9999999994");
    await submitAbhaOtp(journey);

    const addressStep = journey.getByTestId("abha-address-step");
    await expect(addressStep).toBeVisible();
    const suggestions = addressStep.getByTestId("abha-address-suggestion");
    console.log("Suggestions:", await suggestions.allInnerTexts());
    // A taken address first, to see the real refusal
    await addressStep.getByTestId("abha-address-custom-input").fill("taken.addr");
    await addressStep
      .getByRole("button", { name: "Create ABHA address" })
      .click();
    const addressError = addressStep.getByTestId("abha-field-error");
    await expect(addressError).toBeVisible();
    console.log("Taken address message:", await addressError.innerText());

    await suggestions.first().click();
    await addressStep
      .getByRole("button", { name: "Create ABHA address" })
      .click();
    const result = journey.getByTestId("abha-result-step");
    await expect(
      result.getByRole("heading", { name: "ABHA created" }),
    ).toBeVisible();
    await expect(result.getByTestId("abha-profile-number")).toHaveText(
      "91-4444-4444-4444",
    );
    const abhaAddress = await result
      .getByTestId("abha-profile-address")
      .innerText();
    console.log("Created ABHA:", await result.innerText());
    await result.getByRole("button", { name: "Continue", exact: true }).click();

    const summary = page.getByTestId("abha-registration-summary");
    await expect(summary.getByTestId("abha-registration-number")).toContainText(
      "91-4444-4444-4444",
    );
    await expect(
      summary.getByTestId("abha-registration-address"),
    ).toContainText(abhaAddress);
    const name = page.getByRole("textbox", { name: /name.*\*/i });
    await expect(name).not.toBeEditable();
    console.log("Prefilled name:", await name.inputValue());
    await expect(page.getByRole("radio", { name: "Female", exact: true })).toBeChecked();
    const phone = page.getByRole("textbox", { name: /phone number.*\*/i });
    await expect(phone).toHaveValue("+919999999994");
    console.log(
      "Phone provenance:",
      await formItem(page, phone).getByTestId("abha-provenance").innerText(),
    );

    const patientId = await registerPatient(page);
    await expectToast(page, "ABHA linked to the patient");
    const section = await expectLinkedOnDemography(
      page,
      facilityId,
      patientId,
      "91-4444-4444-4444",
    );
    console.log("Registered patient ABHA section:", await section.innerText());
  });
});

test.describe("real stack as facility admin", () => {
  test.use({ storageState: "tests/.auth/facilityAdmin.json" });

  test("(b2) Registration: two accounts on a mobile, choose one, register, linked", async ({
    page,
  }) => {
    recordTraffic(page, "b2");
    const facilityId = getFacilityId();
    await page.goto(`/facility/${facilityId}/patient/create`);
    const journey = page.getByTestId("abha-journey");
    const identify = journey.getByTestId("abha-identify-step");
    await identify
      .getByRole("radio", { name: "Mobile Number", exact: true })
      .click();
    await identify.getByTestId("abha-identifier-input").fill("9999999992");
