"""
Encryption of values sent to ABDM: RSA OAEP with MGF1(SHA-1) and SHA-1, using
the public key ABDM publishes, as standard base64.
"""

import base64
import logging

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding, rsa
from django.conf import settings
from django.core.cache import cache

from care.emr.abdm.client import abha_request
from care.emr.abdm.constants import (
    ENCRYPTION_ALGORITHM,
    PUBLIC_KEY_CACHE_KEY,
    AbdmPath,
)
from care.emr.abdm.exceptions import AbdmError

logger = logging.getLogger(__name__)


def _load_key(public_key):
    lines = [
        line.strip()
        for line in str(public_key).strip().splitlines()
        if line.strip() and not line.strip().startswith("-----")
    ]
    der = base64.b64decode("".join(lines), validate=True)
    key = serialization.load_der_public_key(der)
    if not isinstance(key, rsa.RSAPublicKey):
        raise TypeError
    return key


def get_public_key():
    """The ABDM public key, fetched and checked once per ABDM_PUBLIC_KEY_TTL."""
    cached = cache.get(PUBLIC_KEY_CACHE_KEY)
    if cached:
        return _load_key(cached)
    data = abha_request("GET", AbdmPath.CERTIFICATE)
    if not isinstance(data, dict):
        data = {}
    algorithm = data.get("encryptionAlgorithm")
    if algorithm != ENCRYPTION_ALGORITHM:
        logger.error(
            "ABDM certificate refused: unsupported encryption algorithm %r", algorithm
        )
        raise AbdmError(AbdmError.UNAVAILABLE)
    public_key = data.get("publicKey") or ""
    try:
        key = _load_key(public_key)
    except (TypeError, ValueError) as error:
        logger.error("ABDM certificate refused: the public key could not be read")
        raise AbdmError(AbdmError.UNAVAILABLE) from error
    cache.set(PUBLIC_KEY_CACHE_KEY, public_key, timeout=settings.ABDM_PUBLIC_KEY_TTL)
    return key


def evict_public_key():
    cache.delete(PUBLIC_KEY_CACHE_KEY)


def encrypt(value):
    ciphertext = get_public_key().encrypt(
        str(value).encode(),
        padding.OAEP(
            mgf=padding.MGF1(algorithm=hashes.SHA1()),  # noqa: S303
            algorithm=hashes.SHA1(),  # noqa: S303
            label=None,
        ),
    )
    return base64.b64encode(ciphertext).decode()
