test("verifies an ABHA number with either OTP method (VRFY_ABHA_101, VRFY_ABHA_201)", async ({
  page,
}) => {
  const abha = await mockAbha(page, {
    sendOtp: () =>
      respond(
        otpSentJourney(
          { message: AADHAAR_OTP_MESSAGE },
          {
            identifier_type: "abha_number",
            masked_identifier: "91-XXXX-XXXX-9012",
            auth_methods: ["aadhaar_otp", "mobile_otp"],
          },
        ),
      ),
  });
  const journey = await openRegistration(page, facilityId);
  const identify = journey.getByTestId("abha-identify-step");
  const input = identify.getByTestId("abha-identifier-input");
  const sendOtp = identify.getByRole("button", {
    name: "Send OTP",
    exact: true,
  });

  await test.step("An invalid ABHA number is refused before sending", async () => {
    await identify
      .getByRole("radio", { name: "ABHA Number", exact: true })
      .click();
    await input.fill("91-1234-5678");
    await sendOtp.click();
    await expect(identify.getByTestId("abha-field-error")).toHaveText(
      "Enter a valid 14-digit ABHA number",
    );
    expect(abha.requests).toEqual([]);
  });

  await test.step("Aadhaar OTP", async () => {
    await input.fill("91123456789012");
    await expect(
      identify.getByRole("radio", {
        name: "OTP on the mobile number linked with Aadhaar",
        exact: true,
      }),
    ).toBeChecked();
    await sendOtp.click();
    await expect(journey.getByTestId("abha-otp-step")).toContainText(
      AADHAAR_OTP_MESSAGE,
    );
    expect(abha.calls("sendOtp")[0].body).toEqual({
      identifier_type: "abha_number",
      identifier: "91-1234-5678-9012",
      auth_method: "aadhaar_otp",
      facility: facilityId,
    });
  });

  await test.step("Mobile OTP, without entering the ABHA number again", async () => {
    await journey.getByTestId("abha-start-again").click();
    await expect(
      identify.getByRole("radio", { name: "ABHA Number", exact: true }),
    ).toBeChecked();
    await expect(input).toHaveValue("91-1234-5678-9012");
    await expect(identify.getByTestId("abha-provenance")).toHaveText(
      "Entered at the desk",
    );
    await identify
      .getByRole("radio", {
        name: "OTP on the mobile number linked with ABHA",
        exact: true,
      })
      .click();
    await sendOtp.click();
    await expect(journey.getByTestId("abha-otp-step")).toBeVisible();
    expect(abha.calls("sendOtp")[1].body).toEqual({
      identifier_type: "abha_number",
      identifier: "91-1234-5678-9012",
      auth_method: "mobile_otp",
      facility: facilityId,
    });
  });
});

