test("counts down before each OTP resend and stops after the last (CRT_ABHA_106)", async ({
  page,
}) => {
  const mobile = randomMobile();
  const otpSent = (resends_remaining: number) =>
    respond(
      otpSentJourney({
        sent_to: maskMobile(mobile),
        resend_available_at: secondsFromNow(RESEND_COOLDOWN_SECONDS),
        resends_remaining,
      }),
    );
  const abha = await mockAbha(page, {
    sendOtp: () => otpSent(2),
    resendOtp: ({ call }) => {
      switch (call) {
        case 1:
          return otpSent(1);
        case 2:
          return abhaError(
            429,
            "resend_cooldown",
            "Please wait before resending",
            null,
            { retry_after: RESEND_COOLDOWN_SECONDS },
          );
        default:
          return otpSent(0);
      }
    },
  });
  const journey = await openRegistration(page, facilityId, mobile);
  await journey
    .getByRole("button", { name: "Send OTP", exact: true })
    .click();

  const otpStep = journey.getByTestId("abha-otp-step");
  const resendArea = otpStep.getByTestId("abha-resend");
  const resend = otpStep.getByTestId("abha-resend-otp");
  const countdown = /^Resend OTP in \d+ seconds$/;

  await test.step("The masked destination is shown (CRT_ABHA_105)", async () => {
    await expect(
      otpStep.getByRole("heading", { name: "Enter the OTP" }),
    ).toBeVisible();
    await expect(otpStep).toContainText(
      `An OTP has been sent to ${maskMobile(mobile)}.`,
    );
  });

  await test.step("Resend waits for the countdown", async () => {
    await expect(resend).toBeDisabled();
    await expect(resend).toHaveText(countdown);
    await expect(resendArea).toContainText("2 resends left");
    await expect(resend).toBeEnabled();
    await expect(resend).toHaveText("Resend OTP");
    await resend.click();
    await expect(resendArea).toContainText("1 resend left");
    await expect(resend).toBeDisabled();
  });

  await test.step("A 429 shows how long to wait", async () => {
    await expect(resend).toBeEnabled();
    await resend.click();
    await expect(resendArea.getByTestId("abha-field-error")).toHaveText(
      `Please wait ${RESEND_COOLDOWN_SECONDS} seconds before requesting another OTP.`,
    );
    await expect(resend).toBeDisabled();
    await expect(resend).toHaveText(countdown);
  });

  await test.step("No resend is offered after the last one", async () => {
    await expect(resend).toBeEnabled();
    await resend.click();
    await expect(resendArea).toHaveText("No resends left");
    await expect(resend).toHaveCount(0);
    expect(abha.calls("resendOtp").map((call) => call.body)).toEqual([
      { transaction_id: TRANSACTION_ID },
      { transaction_id: TRANSACTION_ID },
      { transaction_id: TRANSACTION_ID },
    ]);
  });
});
